var e=JSON.parse(`[[2501,"Використовуйте useMemo й useCallback лише тоді, коли є вимірювана проблема з продуктивністю. Вони корисні, щоб запобігати дорогим перемалюванням або повторним обчисленням, коли залежні значення не змінюються. Не застосовуйте їх за замовчуванням — це може погіршити продуктивність через накладні витрати мемоїзації. Оцінюйте складність обчислення й частоту повторних рендерів.","Коли застосування useMemo й useCallback виправдане\\nЦі хуки React призначені, щоб оптимізувати продуктивність, але їхнє використання має бути обґрунтованим. Основне правило: застосовуйте їх лише тоді, коли ви спостерігаєте реальні проблеми з продуктивністю, як-от часті повторні рендери або дорогі обчислення.\\n\\nКритерії їхнього використання\\n\\n- Дорогі обчислення: якщо функція всередині useMemo виконує складні операції (наприклад, сортування великого масиву, фільтрацію тисяч елементів), мемоїзація може бути корисною.\\n- Стабільні посилання: useCallback потрібний, коли ви передаєте колбек у дочірній компонент, обгорнутий у React.memo, й хочете уникнути його повторного рендера за незмінних залежностей.\\n- Вимірювана вигода: використовуйте інструменти профілювання (React DevTools Profiler), щоб бути впевненим, що мемоїзація справді скорочує час рендера.\\n\\nПриклад коду\\n\\nКоли їх не застосовувати\\n\\n- Для простих обчислень (наприклад, додавання чисел) — накладні витрати мемоїзації перевищують вигоду.\\n- Для колбеків, які передають у нативні HTML-елементи — вони не використовують React.memo.\\n- Без профілювання — передчасна оптимізація може ускладнити код без реального виграшу.\\n\\nВисновок: використовуйте useMemo й useCallback лише після того, як виявили вузькі місця продуктивності за допомогою профайлера. Вони корисні для дорогих обчислень і стабільних посилань у компонентах із React.memo, але їх не варто застосовувати за замовчуванням.","import React, { useMemo, useCallback, useState } from 'react';\\n\\nfunction ExpensiveList({ items, filter }) {\\n  // Expensive filtering — a useMemo is justified\\n  const filteredItems = useMemo(() => {\\n    return items.filter(item => item.name.includes(filter));\\n  }, [items, filter]);\\n\\n  // A simple computation — no useMemo is needed\\n  const count = items.length;\\n\\n  return (\\n    <ul>\\n      {filteredItems.map(item => (\\n        <li key={item.id}>{item.name}</li>\\n      ))}\\n    </ul>\\n  );\\n}\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  \\n  // A useCallback for a stable reference\\n  const handleClick = useCallback(() => {\\n    setCount(c => c + 1);\\n  }, []);\\n\\n  return (\\n    <div>\\n      <button onClick={handleClick}>{count}</button>\\n      <ExpensiveList items={bigArray} filter=\\"test\\" />\\n    </div>\\n  );\\n}"],[2502,"Щоб скасувати setTimeout усередині хука, використовуйте функцію очищення в useEffect. Збережіть ідентифікатор таймера, який повертає setTimeout, й викличте clearTimeout у функції, яку ви повертаєте. Це гарантує, що таймер буде скасований, коли компонент демонтується або коли ефект виконається знову.","Проблема з setTimeout у React\\nКоли використовують setTimeout усередині React-компонента, є ризик, що колбек виконається після того, як компонент уже демонтувався. Це може призвести до втрат пам'яті, помилок про оновлення стану демонтованого компонента або до неочікуваної поведінки.\\n\\nРішення за допомогою useEffect і функції очищення\\nReact надає механізм очищення через повернення функції з useEffect. Цю функцію викликають, коли компонент демонтується або перед тим, як ефект виконається знову. Використовуйте її, щоб викликати clearTimeout.\\n\\nОбробка залежностей і скидання стану\\nЯкщо таймер має перезапускатися, коли певні значення змінюються, укажіть їх у масиві залежностей. На кожній зміні залежності ефект перезапускається: спочатку викликають очищення (скасовуючи старий таймер), потім створюють новий.\\n\\nВисновок\\nЗавжди використовуйте функцію очищення в useEffect, щоб скасувати setTimeout. Це обов'язкова практика, щоб запобігати втратам пам'яті й помилкам у React-застосунках, особливо в роботі з асинхронними операціями й таймерами.","import { useEffect, useState } from 'react';\\n\\nfunction TimerComponent() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const timerId = setTimeout(() => {\\n      setCount(prev => prev + 1);\\n    }, 1000);\\n\\n    // The clean-up function\\n    return () => {\\n      clearTimeout(timerId);\\n    };\\n  }, []); // An empty array of dependencies — it runs once\\n\\n  return <div>Count: {count}</div>;\\n}\\n\\nuseEffect(() => {\\n  const timerId = setTimeout(() => {\\n    // the action\\n  }, delay);\\n\\n  return () => clearTimeout(timerId);\\n}, [delay]); // a restart when delay changes"],[2503,"Для невеликого одноразового SPA-проєкту ухвалення строгої архітектури на кшталт FSD зазвичай надмірне. Основна мета архітектури — підтримувати масштабування й довгострокову підтримуваність. Якщо проєкт не розвиватимуть далі, достатньо мінімальної організації коду. Однак навіть у невеликому проєкті корисно дотримуватися базових принципів, як-от розподілу відповідальності, щоб уникнути хаосу.","Для чого потрібна архітектура?\\nАрхітектура проєкту — набір угод і структурних рішень, які допомагають організувати код так, щоб його було легко зрозуміти, змінювати й розширювати. Feature-Sliced Design (FSD) — один із сучасних підходів для фронтенд-проєктів, який пропонує ясний розподіл за функційними модулями (за шарами).\\n\\nКоли архітектура обов'язкова?\\nЯкщо проєкт планують розвивати тривалий час, якщо над ним працює кілька розробників або якщо його інтегруватимуть з іншими системами — архітектура потрібна. Вона зменшує технічний борг і прискорює додавання нової функціональності.\\n\\nКоли можна обійтися без строгої архітектури?\\nДля одноразового SPA-проєкту, який не підтримуватимуть після здачі, строга архітектура на кшталт FSD може бути зайвою. У цьому разі достатньо:\\n- Розділити код на логічні блоки (наприклад, компоненти, утиліти, запити до API).\\n- Уникати глобальних змінних і сильної зв'язаності.\\n- Використовувати просту структуру тек, як-от \`components/\`, \`utils/\`, \`pages/\`.\\n\\nПриклад мінімальної структури для невеликого SPA\\n\\nТакий підхід не потребує ухвалення FSD, але зберігає читабельність і дає змогу швидко знайти потрібний файл.\\n\\nВисновок\\nДля одноразового невеликого SPA-проєкту ухвалення FSD надмірне. Достатньо базової організації коду з розподілом за теками. Якщо проєкт житиме довше або зростатиме, варто розглянути строгішу архітектуру, щоб уникнути проблем із підтримкою.","src/\\n  components/\\n    Header.js\\n    Footer.js\\n  pages/\\n    Home.js\\n    About.js\\n  utils/\\n    api.js\\n    helpers.js\\n  App.js\\n  index.js"],[2504,"Для SPA з авторизацією й однією багатокроковою формою менеджер стану не обов'язковий. Можна використати локальний стан компонентів і контекст React, щоб передавати дані між кроками форми. Менеджер стану виправданий для складної взаємодії безлічі компонентів, задля кешування даних або синхронізації із сервером. У цьому разі він додав би надмірної складності без істотної вигоди.","Коли менеджер стану потрібний?\\nМенеджер стану (наприклад, Redux, MobX, Zustand) розв'язує задачу керування глобальним станом у великих застосунках. Він дає змогу зберігати дані централізовано, доступно з будь-якого компонента, й полегшує зневадження й тестування. Однак його використання виправдане не завжди.\\n\\nАналіз сценарію\\nУ описаному сценарії — SPA з авторизацією й однією багатокроковою формою — стан застосунку відносно простий. Авторизація зазвичай зберігає токен й інформацію про користувача, а форма — дані, заповнені протягом кількох кроків. Щоб передавати дані між кроками форми, можна використати локальний стан батьківського компонента або React Context. Це не потребує встановлення додаткових бібліотек й не ускладнює архітектури.\\n\\nПриклад реалізації без менеджера стану\\n\\nКоли менеджер стану варто використовувати\\n\\n- Безліч компонентів використовують ті самі дані (наприклад, кошик в онлайн-магазині).\\n- Складна логіка синхронізації із сервером (кешування, оптимістичні оновлення).\\n- Потреба в інструментах зневадження (Redux DevTools).\\n\\nВисновок\\nДля простих SPA з обмеженою кількістю стану використання менеджера стану надмірне. Локальний стан і контекст React — легше, зрозуміліше рішення. Менеджер стану варто вводити лише тоді, коли застосунок зростає й з'являється реальна потреба в централізованому керуванні станом.","// A form component with multiple steps\\nfunction MultiStepForm() {\\n  const [step, setStep] = useState(1);\\n  const [formData, setFormData] = useState({});\\n\\n  const handleNext = (data) => {\\n    setFormData(prev => ({ ...prev, ...data }));\\n    setStep(step + 1);\\n  };\\n\\n  return (\\n    <AuthContext.Provider value={{ token }}>\\n      {step === 1 && <Step1 onNext={handleNext} />}\\n      {step === 2 && <Step2 onNext={handleNext} />}\\n      {step === 3 && <Step3 data={formData} />}\\n    </AuthContext.Provider>\\n  );\\n}"],[2505,"Щоб зберігати проміжний стан багатокрокової форми, можна використати локальний стан компонента, useReducer або Context API. Локальний стан придатний для простих форм, useReducer — для складної логіки, а Context API — задля доступу до даних із різних компонентів. Також можна використати Redux або бібліотеки на кшталт Formik і React Hook Form.","Основні підходи до зберігання стану багатокрокової форми\\nРозробляючи багатокрокові форми на фронтенді, важливо зберігати дані між кроками, щоб користувач міг повернутися назад або продовжити пізніше. Є кілька способів організувати таке зберігання, кожний з яких придатний для різних сценаріїв.\\n\\nЛокальний стан компонента\\nНайпростіший спосіб — зберігати всі дані форми в єдиному об'єкті всередині компонента, який керує кроками. Це зручно для невеликих форм із 2–3 кроками.\\n\\nuseReducer для складної логіки\\nЯкщо форма має багато полів і складні правила валідації, краще використати useReducer. Це дає змогу централізовано обробляти зміни й полегшує тестування.\\n\\nContext API задля глобального доступу\\nКоли форму розбито на окремі компоненти для кожного кроку, зручно використати Context API, щоб уникнути prop drilling. Створюють контекст, який надає дані форми й функції для їхнього оновлення всім дочірнім компонентам.\\n\\nВисновок\\nВибір способу залежить від складності форми й від архітектури застосунку. Для простих форм достатньо локального стану, для середніх — useReducer, а для великих проєктів із безліччю кроків і компонентів — Context API або Redux. Це забезпечує зручність у розробці й підтримці коду.","import React, { useState } from 'react';\\n\\nfunction MultiStepForm() {\\n  const [step, setStep] = useState(1);\\n  const [formData, setFormData] = useState({\\n    name: '',\\n    email: '',\\n    address: ''\\n  });\\n\\n  const updateField = (field, value) => {\\n    setFormData(prev => ({ ...prev, [field]: value }));\\n  };\\n\\n  // The rendering of the steps depending on step\\n}\\n\\nconst initialState = { name: '', email: '', address: '' };\\n\\nfunction formReducer(state, action) {\\n  switch (action.type) {\\n    case 'UPDATE_FIELD':\\n      return { ...state, [action.field]: action.value };\\n    case 'RESET':\\n      return initialState;\\n    default:\\n      return state;\\n  }\\n}\\n\\nfunction MultiStepForm() {\\n  const [formData, dispatch] = useReducer(formReducer, initialState);\\n}\\n\\nconst FormContext = React.createContext();\\n\\nfunction FormProvider({ children }) {\\n  const [formData, setFormData] = useState({});\\n  return (\\n    <FormContext.Provider value={{ formData, setFormData }}>\\n      {children}\\n    </FormContext.Provider>\\n  );\\n}"],[2506,"Для невеликого React-проєкту з корпоративними стандартами найкраще використати Webpack, оскільки це найгнучкіший і найналаштовуваніший збирач. Він підтримує React із коробки через Babel і дає змогу легко інтегрувати будь-які плагіни й лоадери. Якщо в компанії вже є готові конфігурації або шаблони, Webpack забезпечить їхню сумісність. Альтернативи на кшталт Vite або Parcel можуть бути простішими, але вони можуть не відповідати внутрішнім стандартам.","Вибір збирача для React-проєкту\\nОбираючи збирач для невеликого React-проєкту в умовах корпоративних стандартів, ключовим чинником стає сумісність із наявною інфраструктурою. Webpack — стандарт де-факто у великих компаніях завдяки своїй гнучкості й широкій екосистемі плагінів. Він дає змогу точно налаштувати процес збирання під будь-які вимоги, включно з оптимізацією, розділенням коду й підтримкою старіших браузерів.\\n\\nПрактичний приклад конфігурації Webpack для React\\n\\nЧому Webpack, а не альтернативи\\n\\n- Сумісність зі стандартами: Webpack легко адаптується до наявних корпоративних конфігурацій, до ESLint, Prettier й інших інструментів.\\n- Гнучкість: можливість тонко налаштувати все через лоадери й плагіни, щоб працювати з TypeScript, CSS Modules, зображеннями й шрифтами.\\n- Продуктивність: вбудовані оптимізації, як-от tree shaking і розділення коду, критичні для production-збирань.\\n\\nХоча Vite пропонує швидшу розробку завдяки ESM, він може не підтримувати специфічних корпоративних плагінів або потребувати додаткової конфігурації задля сумісності. Parcel, у свою чергу, надто автоматизований і не дає достатнього контролю.\\n\\nВисновок\\nДля невеликого React-проєкту в компанії з усталеними стандартами Webpack залишається оптимальним вибором завдяки своїй гнучкості, зрілості й сумісності з наявними інструментами. Він забезпечує повний контроль над збиранням й легко інтегрується в будь-яке корпоративне середовище.","// webpack.config.js\\nconst path = require('path');\\nconst HtmlWebpackPlugin = require('html-webpack-plugin');\\n\\nmodule.exports = {\\n  entry: './src/index.js',\\n  output: {\\n    path: path.resolve(__dirname, 'dist'),\\n    filename: 'bundle.js',\\n  },\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.jsx?$/,\\n        exclude: /node_modules/,\\n        use: {\\n          loader: 'babel-loader',\\n          options: {\\n            presets: ['@babel/preset-env', '@babel/preset-react'],\\n          },\\n        },\\n      },\\n      {\\n        test: /\\\\.css$/,\\n        use: ['style-loader', 'css-loader'],\\n      },\\n    ],\\n  },\\n  plugins: [\\n    new HtmlWebpackPlugin({\\n      template: './public/index.html',\\n    }),\\n  ],\\n  resolve: {\\n    extensions: ['.js', '.jsx'],\\n  },\\n};"],[2507,"React використовує алгоритм порівняння (diffing), щоб оновлювати DOM. Коли список змінюється, React порівнює старе й нове дерева віртуального DOM. Ключі допомагають React ідентифікувати елементи й мінімізувати перемалювання. Без ключів React може перестворити кожний елемент списку.","Як працює узгодження списків у React\\nКоли React оновлює список елементів, він використовує алгоритм узгодження, який порівнює дерева віртуального DOM до й після зміни. Цей процес заснований на двох припущеннях: елементи різних типів створюють різні дерева, а ключі дають React змогу ідентифікувати елементи між рендерами.\\n\\nРоль ключів\\nКлючі — унікальні ідентифікатори, які допомагають React зрозуміти, який елемент було додано, видалено або переміщено. Без ключів React порівнюватиме елементи за індексом, що може призвести до неправильного оновлення DOM й до втрати стану компонентів.\\n\\nАлгоритм порівняння\\nReact використовує алгоритм O(n), який проходить списком і порівнює елементи за ключем. Якщо ключі збігаються, React оновлює лише ті атрибути, які змінилися. Якщо ключ змінився, React видаляє старий елемент і створює новий. Це дає змогу ефективно оновлювати DOM без повного перемалювання.\\n\\nВисновок\\nВикористання стабільних, унікальних ключів у React-списках критично важливе для продуктивності й задля належного оновлення DOM. Це особливо корисно в роботі з динамічними списками, де елементи можуть додавати, видаляти або переставляти.","// An example with keys\\nconst items = ['a', 'b', 'c'];\\nreturn (\\n  <ul>\\n    {items.map((item, index) => (\\n      <li key={item}>{item}</li>\\n    ))}\\n  </ul>\\n);\\n\\n// Without keys React may recreate every element\\n{items.map((item, index) => (\\n  <li>{item}</li>\\n))}"],[2508,"React використовує ключі, щоб ідентифікувати елементи в масиві. Якщо ключі не вказано, React використовує індекс елемента. Коли перемикаються між різними масивами даних, React може повторно використати наявні DOM-вузли, якщо їхні індекси збігаються, що призводить до збереження стану компонентів. Це відбувається тому, що React не перестворює компонента, а оновлює його пропси.","Чому компоненти зберігають стан, коли явних ключів немає?\\nКоли ви рендерите список компонентів, не вказавши явних ключів, React за замовчуванням використовує індекс елемента в масиві як ключ. Це може призвести до неочікуваної поведінки при перемиканні між різними масивами даних.\\n\\nМеханізм узгодження\\nReact порівнює дерева віртуального DOM за допомогою алгоритму порівняння. Якщо ключі елементів збігаються, React вважає, що це той самий елемент, й оновлює лише його пропси, зберігаючи стан компонента.\\n\\nПриклад проблеми\\n\\nУ цьому прикладі на натисканні кнопки React повторно використовує наявні компоненти InputComponent, тому що їхні індекси (0 і 1) збігаються. Стан усередині компонентів (наприклад, набраний текст) буде збережений, хоча дані змінилися цілком.\\n\\nПравильне рішення\\nЗавжди використовуйте унікальні, стабільні ключі — наприклад, ідентифікатори з бази даних:\\n\\nВисновок\\nЯвні ключі потрібні задля належної роботи React під час рендерингу списків. Вони допомагають уникати помилок зі збереженням стану й забезпечують належне оновлення компонентів, коли дані змінюються.","function App() {\\n  const [items, setItems] = useState([{id: 1, text: 'A'}, {id: 2, text: 'B'}]);\\n  \\n  return (\\n    <div>\\n      {items.map((item, index) => (\\n        <InputComponent key={index} value={item.text} />\\n      ))}\\n      <button onClick={() => setItems([{id: 3, text: 'C'}, {id: 4, text: 'D'}])}>\\n        Change the data\\n      </button>\\n    </div>\\n  );\\n}\\n\\n{items.map(item => (\\n  <InputComponent key={item.id} value={item.text} />\\n))}"],[2509,"React Testing Library зосереджується на тестуванні поведінки компонентів із погляду користувача, працюючи з реальним DOM. Enzyme надає доступ до внутрішнього стану й методів компонентів, що призводить до тестування деталей реалізації. RTL сприяє тестам, стійким до рефакторингу, а Enzyme робить їх ламкими.","Філософія тестування\\nReact Testing Library (RTL) й Enzyme представляють два різні підходи до тестування React-компонентів. RTL дотримується принципу: «Чим більше ваші тести схожі на те, як використовують ваш застосунок, тим більше впевненості вони можуть дати». Enzyme, навпаки, надає низькорівневіший доступ до внутрішнього в компоненті.\\n\\nКлючові відмінності\\n\\n- Підхід до пошуку елементів: RTL використовує запити, засновані на доступності (getByRole, getByText, getByLabelText), імітуючи дії користувача. Enzyme використовує селектори (find('.class'), find(Component)).\\n- Доступ до стану: RTL не надає безпосереднього доступу до стану або пропсів компонента. Enzyme дає змогу викликати .state(), .props(), .instance().\\n- Тестування деталей реалізації: RTL активно відраджує тестувати внутрішні методи й стан. Enzyme це сприяє.\\n\\nПриклад коду\\n\\nУ прикладі RTL перевіряє, що користувач бачить «1» після кліку. Enzyme перевіряє внутрішній стан count.\\n\\nВисновок\\nReact Testing Library краща, щоб створювати надійні тести, які не ламаються під час рефакторингу. Enzyme може бути корисною, щоб швидко прототипувати тести, але її використання часто призводить до ламких тестів, прив'язаних до реалізації.","// React Testing Library\\nimport { render, screen, fireEvent } from '@testing-library/react';\\nimport Counter from './Counter';\\n\\ntest('increments counter', () => {\\n  render(<Counter />);\\n  const button = screen.getByRole('button', { name: /increment/i });\\n  fireEvent.click(button);\\n  expect(screen.getByText('1')).toBeInTheDocument();\\n});\\n\\n// Enzyme\\nimport { shallow } from 'enzyme';\\nimport Counter from './Counter';\\n\\ntest('increments counter', () => {\\n  const wrapper = shallow(<Counter />);\\n  wrapper.find('button').simulate('click');\\n  expect(wrapper.state('count')).toBe(1);\\n});"],[2510,"Щоб оптимізувати компонент, через який сторінка підвисає на великих даних, використовуйте віртуалізацію списку (наприклад, react-window), ліниве завантаження (React.lazy), мемоїзацію (React.memo, useMemo, useCallback) й пагінацію. Також можна розбити рендеринг на частини за допомогою requestAnimationFrame або Web Workers.","Проблема й її причини\\nКоли React-компонент обробляє й рендерить великий обсяг даних (наприклад, список із тисяч елементів), браузер може зависнути, тому що головний потік заблоковано. Це відбувається тому, що React виконує рендеринг синхронно, і браузер не може оновити інтерфейс, доки JavaScript не завершив своєї роботи.\\n\\nОсновні підходи до оптимізації\\n\\n- Віртуалізація списку — вона рендерить лише видимі елементи, використовуючи бібліотеки на кшталт react-window або react-virtualized.\\n- Ліниве завантаження — воно розбиває код на частини за допомогою React.lazy і Suspense.\\n- Мемоїзація — вона запобігає повторним обчисленням за допомогою React.memo, useMemo й useCallback.\\n- Пагінація — вона завантажує дані порціями, на запит користувача.\\n- Розбиття рендерингу — воно використовує requestAnimationFrame або setTimeout, щоб розподілити роботу по кадрах.\\n\\nПриклад із віртуалізацією\\n\\nПриклад із мемоїзацією\\n\\nВисновок\\nЗастосовуйте віртуалізацію для списків із тисячами елементів, мемоїзацію — щоб запобігати надлишковим перемалюванням, і ліниве завантаження — щоб зменшити початковий бандл. Ці техніки критичні, щоб створювати відгукливі інтерфейси з великими даними.","import { FixedSizeList as List } from 'react-window';\\n\\nconst Row = ({ index, style }) => (\\n  <div style={style}>Item {index}</div>\\n);\\n\\nconst BigList = ({ items }) => (\\n  <List\\n    height={400}\\n    itemCount={items.length}\\n    itemSize={35}\\n    width={300}\\n  >\\n    {Row}\\n  </List>\\n);\\n\\nconst ExpensiveComponent = React.memo(({ data }) => {\\n  // Heavy computations\\n  return <div>{data}</div>;\\n});\\n\\nconst Parent = ({ items }) => {\\n  const processed = useMemo(() => items.map(process), [items]);\\n  return processed.map(item => <ExpensiveComponent key={item.id} data={item} />);\\n};"],[2511,"Проблема overflow виникає, коли спадний список виходить за межі батьківського контейнера. Її можна розв'язати за допомогою CSS-властивості overflow: visible у батька, використання порталів React (ReactDOM.createPortal), щоб відрендерити список за межами контейнера, або застосування бібліотек, таких як Popper.js, для динамічного позиціювання. Також допомагає задання z-index і перевірка меж екрана.","Розуміння проблеми overflow\\nКоли спадний список відображається всередині контейнера з обмеженою висотою або з властивістю overflow: hidden, його вміст може бути обрізаний. Це часто зустрічається в модальних вікнах, бічних панелях або компонентах з фіксованою висотою. Проблема загострюється, якщо список має з'являтися за межами батьківського елемента.\\nОсновні підходи до розв'язання\\n\\n- CSS-рішення: задати overflow: visible батьківському контейнеру, якщо це не ламає дизайн. Проте це може зламати прокручування або макет.\\n- React Portals: використати ReactDOM.createPortal, щоб відрендерити спадний список в окремому DOM-вузлі (наприклад, у body). Це гарантує, що список не буде обмежений стилями батька.\\n- Бібліотеки позиціювання: Popper.js або Floating UI автоматично обчислюють оптимальну позицію списку, уникаючи і виходу за межі екрана, і overflow.\\nПриклад з порталом\\n\\nУ цьому прикладі список рендериться в body, тож overflow батька на нього не впливає. Також важливо керувати z-index і закриттям списку, коли клацання відбувається поза ним.\\nПриклад з Popper.js\\n\\nPopper.js автоматично коригує позицію так, щоб список не виходив за межі видимої області.\\nВисновок\\nЩоб розв'язати overflow у спадних списках, використовуйте портали, якщо потрібно повністю позбутися обмежень батька, або бібліотеки позиціювання для динамічної адаптації. CSS-рішення підходять лише для простих випадків без глибокої вкладеності.","import ReactDOM from 'react-dom';\\n\\nfunction Dropdown({ isOpen, children }) {\\n  if (!isOpen) return null;\\n  return ReactDOM.createPortal(\\n    <div className=\\"dropdown-menu\\">{children}</div>,\\n    document.body\\n  );\\n}\\n\\nimport { usePopper } from 'react-popper';\\n\\nfunction Dropdown({ referenceElement }) {\\n  const [popperElement, setPopperElement] = useState(null);\\n  const { styles, attributes } = usePopper(referenceElement, popperElement);\\n\\n  return (\\n    <div ref={setPopperElement} style={styles.popper} {...attributes.popper}>\\n      Вміст списку\\n    </div>\\n  );\\n}"],[2512,"Продуктивність drag-and-drop може деградувати з часом через накопичення обробників подій, які не скасували, особливо під час повторних перетягувань. Якщо обробники не видаляють, коли перетягування завершилося, вони й далі висять у пам'яті й викликаються, сповільнюючи роботу. Також можливі втрати пам'яті через створення нових DOM-елементів без їхнього очищення.","Чому продуктивність drag-and-drop падає поступово?\\nПроблема часто пов'язана з тим, як розробники реалізують механізм перетягування. На кожному новому циклі drag-and-drop (mousedown -> mousemove -> mouseup) можуть додавати нові обробники подій, не видаляючи старих. Із часом кількість активних слухачів зростає, і браузер витрачає все більше ресурсів на їхні виклики, навіть коли перетягування не активне.\\n\\nОсновні причини деградації\\n\\n- Накопичення обробників: якщо обробники mousemove і mouseup додають на кожному mousedown, але не видаляють після mouseup, вони залишаються в пам'яті.\\n- Втрати пам'яті: створення тимчасових DOM-елементів (наприклад, клонів об'єкта, який перетягують) без їхнього подальшого видалення призводить до зростання споживання пам'яті.\\n- Неоптимізовані обчислення: постійний перерахунок позицій елементів або виклик дорогих функцій (наприклад, getBoundingClientRect) на кожному mousemove без кешування.\\n\\nПриклад проблеми й рішення\\n\\nВисновок\\nЩоб запобігти деградації продуктивності drag-and-drop, завжди видаляйте тимчасові обробники подій, коли перетягування завершилося, використовуйте requestAnimationFrame, щоб оптимізувати частоту оновлень, й уникайте створення зайвих DOM-елементів без їхнього очищення. Це особливо важливо в застосунках із довгою сесією користувача.","// The problematic code: the handlers are not removed\\nlet dragItem = document.getElementById('drag');\\ndragItem.addEventListener('mousedown', function(e) {\\n  function onMouseMove(e) {\\n    // expensive computations\\n    dragItem.style.left = e.clientX + 'px';\\n  }\\n  function onMouseUp() {\\n    document.removeEventListener('mousemove', onMouseMove);\\n    document.removeEventListener('mouseup', onMouseUp);\\n  }\\n  document.addEventListener('mousemove', onMouseMove);\\n  document.addEventListener('mouseup', onMouseUp);\\n});\\n\\n// The fixed code: the handlers are removed once it has finished\\ndragItem.addEventListener('mousedown', function(e) {\\n  const onMouseMove = (e) => {\\n    requestAnimationFrame(() => {\\n      dragItem.style.left = e.clientX + 'px';\\n    });\\n  };\\n  const onMouseUp = () => {\\n    document.removeEventListener('mousemove', onMouseMove);\\n    document.removeEventListener('mouseup', onMouseUp);\\n  };\\n  document.addEventListener('mousemove', onMouseMove);\\n  document.addEventListener('mouseup', onMouseUp);\\n});"],[2513,"Використання top/left спричиняє перерахунок розкладки (reflow) на кожній зміні, що знижує продуктивність. styled-components генерує нові CSS-класи на кожному оновленні стилів, що погіршує проблему. Рекомендують використовувати CSS-властивість transform: translate(), щоб переміщувати елементи, оскільки вона працює на рівні композитингу й не спричиняє reflow.","Проблема використання top/left зі styled-components у drag-and-drop\\nРеалізуючи drag-and-drop, часто виникає спокуса змінювати позицію елемента через CSS-властивості \`top\` і \`left\`. Однак такий підхід має серйозні недоліки, особливо в поєднанні з бібліотекою styled-components.\\n\\nЧому top/left — поганий вибір\\nВластивості \`top\` і \`left\` стосуються геометрії елемента й впливають на розкладку сторінки. На кожній їхній зміні браузер виконує перерахунок позицій усіх елементів (reflow), що є дорогою операцією. У контексті drag-and-drop, де позиція змінюється десятки разів за секунду, це призводить до помітних лагів в інтерфейсі.\\n\\nОсобливості styled-components\\nstyled-components генерує CSS-класи динамічно. Коли ви передаєте в стилі змінні значення, бібліотека створює новий клас на кожному рендері. Це додатково навантажує React і браузер, оскільки стилі доводиться перестворювати й застосовувати до DOM.\\n\\nПриклад проблемного коду\\n\\nКожний рух мишки спричиняє повторний рендер і створення нового CSS-класу.\\n\\nПравильне рішення: transform\\nВластивість \`transform: translate(x, y)\` працює на рівні композитингу — браузер переміщує елемент без перерахунку розкладки. Це значно швидше. До того ж transform не потребує створення нових CSS-класів, тому styled-components не перестворюватиме стилів.\\n\\nВиправлений приклад\\n\\nТепер зміни позиції відбуваються плавно, без надлишкових перерахунків.\\n\\nВисновок\\nВикористовуйте \`transform: translate()\` для анімацій і переміщення елементів, особливо в drag-and-drop. Це забезпечує високу продуктивність й дає змогу уникнути проблем із динамічними стилями у styled-components.","const Draggable = styled.div\`\\n  position: absolute;\\n  top: \${props => props.y}px;\\n  left: \${props => props.x}px;\\n\`;\\n\\nfunction Component() {\\n  const [pos, setPos] = useState({x: 0, y: 0});\\n  \\n  const handleMouseMove = (e) => {\\n    setPos({x: e.clientX, y: e.clientY});\\n  };\\n  \\n  return <Draggable x={pos.x} y={pos.y} />;\\n}\\n\\nconst Draggable = styled.div\`\\n  position: absolute;\\n  transform: translate(\${props => props.x}px, \${props => props.y}px);\\n\`;\\n\\nfunction Component() {\\n  const [pos, setPos] = useState({x: 0, y: 0});\\n  \\n  const handleMouseMove = (e) => {\\n    setPos({x: e.clientX, y: e.clientY});\\n  };\\n  \\n  return <Draggable x={pos.x} y={pos.y} />;\\n}"],[2514,"Патерн «Фабрика» застосовують на фронтенді, коли потрібно створювати об'єкти (компоненти, класи) зі спільною структурою, але різними деталями. Наприклад, щоб генерувати модальні вікна, кнопки або елементи форм залежно від типу. Це робить код простішим і гнучкішим.","Що таке патерн «Фабрика»?\\nПатерн Factory — породжувальний патерн проєктування, який надає інтерфейс, щоб створювати об'єкти в суперкласі, але дає підкласам змогу змінювати тип створюваних об'єктів. У фронтенд-розробці він особливо корисний, коли потрібно створювати безліч однотипних елементів із різними конфігураціями.\\n\\nДе його застосовувати на фронтенді?\\n\\n- Створення UI-компонентів (кнопок, модальних вікон, карточок) на основі переданого типу.\\n- Генерація елементів форми (input, select, checkbox) із конфігурації.\\n- Створення об'єктів для роботи з API (різних адаптерів для різних версій).\\n\\nПриклад на JavaScript\\n\\nВисновок\\nПатерн «Фабрика» варто застосовувати, коли код часто створює об'єкти зі схожою логікою, але різними параметрами. Це зменшує дублювання й полегшує додавання нових типів об'єктів.","class ButtonFactory {\\n  createButton(type) {\\n    switch (type) {\\n      case 'primary':\\n        return new PrimaryButton();\\n      case 'secondary':\\n        return new SecondaryButton();\\n      default:\\n        return new DefaultButton();\\n    }\\n  }\\n}\\n\\nclass PrimaryButton {\\n  render() { return '<button class=\\"primary\\">OK</button>'; }\\n}\\n\\nconst factory = new ButtonFactory();\\nconst btn = factory.createButton('primary');\\nconsole.log(btn.render()); // <button class=\\"primary\\">OK</button>"],[2515,"Стан завантаження при асинхронній валідації зазвичай додають на рівні поля або форми. Використовуйте прапорець isLoading, який встановлюють у true перед тим, як запит почнеться, й у false, коли він завершився. Лоадер відображають поруч із полем введення, щоб користувач розумів, що перевірка триває. Важливо блокувати надсилання форми, доки валідація не завершилася, й обробляти помилки.","Концепція асинхронної валідації з лоадером\\nАсинхронну валідацію виконують, коли дані потрібно перевірити на сервері — наприклад, унікальність імені користувача. Протягом цього часу користувач має бачити індикатор завантаження, щоб розуміти, що система працює. Лоадер зазвичай розміщують поруч із полем введення або всередині кнопки надсилання.\\n\\nДе додавати стан завантаження\\n\\n- На рівні поля: прапорець isLoading для кожного поля, яке потребує асинхронної перевірки.\\n- На рівні форми: загальний прапорець isSubmitting для всієї форми, коли надсилання даних потребує валідації.\\n\\nЯк це належно реалізувати\\nВикористовуйте стан компонента (наприклад, useState у React), щоб зберігати прапорець завантаження. Встановлюйте його в true перед викликом асинхронної функції й у false, коли відповідь надійшла. Відображайте спінер або текст «Перевіряємо...» поруч із полем. Приклад у React:\\n\\nВисновок\\nДодавання лоадера при асинхронній валідації покращує користувацький досвід, запобігає повторним надсиланням й інформує користувача про процес. Застосовуйте цей підхід у формах реєстрації й входу або в будь-якій іншій формі, де потрібна перевірка на сервері.","const [isLoading, setIsLoading] = useState(false);\\nconst [error, setError] = useState(null);\\n\\nconst validateUsername = async (value) => {\\n  setIsLoading(true);\\n  setError(null);\\n  try {\\n    const response = await fetch('/api/check-username', { method: 'POST', body: JSON.stringify({ username: value }) });\\n    if (!response.ok) throw new Error('Username taken');\\n  } catch (err) {\\n    setError(err.message);\\n  } finally {\\n    setIsLoading(false);\\n  }\\n};"],[2516,"Патерн Observer використовують, коли один об'єкт (суб'єкт) повідомляє безліч залежних об'єктів (спостерігачів) про зміни свого стану. Наприклад, у користувацькому інтерфейсі, коли дані моделі змінюються, усі пов'язані подання автоматично оновлюють. Це реалізує слабку зв'язаність і полегшує підтримку коду.","Що таке патерн Observer?\\nПатерн Observer — поведінковий патерн проєктування, який визначає залежність «один до багатьох» між об'єктами. Коли один об'єкт (суб'єкт) змінює свій стан, усі залежні об'єкти (спостерігачі) автоматично отримують повідомлення й оновлюються. Це дає змогу уникати тісної зв'язаності й полегшує розширення системи.\\n\\nДе його застосовують у реальних застосунках?\\nОдин із найпоширеніших прикладів — системи подій у користувацьких інтерфейсах. Наприклад, у вебзастосунку на JavaScript, коли дані в моделі змінюються (наприклад, список задач), усі компоненти, які відображають ці дані (наприклад, таблиця й лічильник), мають оновитися. Патерн Observer дає змогу підписати ці компоненти на зміни моделі й автоматично реагувати.\\n\\nПриклад коду на JavaScript\\n\\nВисновок\\nПатерн Observer корисний у системах, де безліч компонентів потрібно автоматично повідомляти про зміни — в UI-фреймворках (React, Vue), у системах подій або коли реалізують pub/sub-моделі. Він покращує модульність й полегшує підтримку коду.","class Subject {\\n  constructor() {\\n    this.observers = [];\\n  }\\n  subscribe(observer) {\\n    this.observers.push(observer);\\n  }\\n  unsubscribe(observer) {\\n    this.observers = this.observers.filter(obs => obs !== observer);\\n  }\\n  notify(data) {\\n    this.observers.forEach(observer => observer.update(data));\\n  }\\n}\\n\\nclass Observer {\\n  constructor(name) {\\n    this.name = name;\\n  }\\n  update(data) {\\n    console.log(\`\${this.name} received the data: \${data}\`);\\n  }\\n}\\n\\nconst subject = new Subject();\\nconst observer1 = new Observer('Observer 1');\\nconst observer2 = new Observer('Observer 2');\\n\\nsubject.subscribe(observer1);\\nsubject.subscribe(observer2);\\nsubject.notify('A new message');\\n// The output: Observer 1 received the data: A new message\\n//             Observer 2 received the data: A new message"],[2517,"Краще показувати сторінку частково, використовуючи скелетони або індикатори завантаження для окремих блоків. Це покращує сприйняття швидкості й дає користувачеві змогу взаємодіяти з тими частинами, які вже завантажилися. Очікування всіх даних погіршує UX і може призвести до втрати користувачів.","Проблема\\nКоли частина даних на сторінці залежить від повільного зовнішнього сервісу, виникає дилема: чекати на повне завантаження чи показати частковий вміст. Очікування всіх даних блокує рендеринг і погіршує користувацький досвід, особливо на мобільних пристроях або за нестабільного з'єднання.\\n\\nРішення: часткове завантаження\\nСучасний підхід — одразу показати сторінку з доступними даними, а для повільних блоків відображати скелетони (сірі прямокутники, які імітують структуру вмісту) або спінери. Це називають асинхронним рендерингом із прогресивним покращенням.\\n\\nПриклад реалізації в React\\n\\nКоли це застосовувати\\n\\n- Якщо частини даних незалежні — показуйте їх одразу.\\n- Якщо дані критичні для навігації (наприклад, меню) — можна показати скелетон, але не блокуйте всієї сторінки.\\n- Для SEO й SSR очікування може бути потрібним, але з використанням стримінгу.\\n\\nВисновок: часткове завантаження з візуальним зворотним зв'язком (скелетонами, спінерами) краще за повне очікування, оскільки воно покращує сприйняття продуктивності й утримує користувача на сторінці.","import React, { useState, useEffect } from 'react';\\n\\nfunction UserProfile({ userId }) {\\n  const [user, setUser] = useState(null);\\n  const [orders, setOrders] = useState(null);\\n\\n  useEffect(() => {\\n    fetch(\`/api/users/\${userId}\`)\\n      .then(res => res.json())\\n      .then(setUser);\\n    fetch(\`/api/orders/\${userId}\`)\\n      .then(res => res.json())\\n      .then(setOrders);\\n  }, [userId]);\\n\\n  return (\\n    <div>\\n      {user ? <h1>{user.name}</h1> : <div className=\\"skeleton\\" />}\\n      {orders ? <OrderList items={orders} /> : <div className=\\"skeleton\\" />}\\n    </div>\\n  );\\n}"],[2518,"Так, попередній результат валідації потрібно скидати на кожному новому введенні користувача. Це потрібно, щоб користувач бачив актуальний стан помилок, а не застарілі повідомлення. Наприклад, якщо поле було позначене як невалідне, а користувач потім його виправив, повідомлення про помилку має зникнути. Інакше користувач буде дезорієнтований і не зрозуміє, що помилку вже виправлено.","Розробляючи форми з валідацією, важливо вчасно оновлювати стан помилок. Якщо попередній результат валідації не скидають на новому введенні, користувач бачитиме застарілі повідомлення, що призводить до плутанини й поганого користувацького досвіду.\\n\\nЧому це важливо\\n\\n- Зворотний зв'язок у реальному часі: користувач має одразу бачити, що його виправлення система прийняла.\\n- Запобігання хибним помилкам: якщо поле було невалідним і потім стало валідним, повідомлення про помилку має зникнути.\\n- Покращений UX: користувач не витрачатиме часу на виправлення проблем, які вже розв'язані.\\n\\nПриклад реалізації\\nПодивімося на просту форму з валідацією email у React. На кожній зміні поля ми скидаємо попередню помилку й запускаємо нову валідацію.\\n\\nУ цьому прикладі на кожному виклику \`handleChange\` ми спочатку скидаємо помилку й потім перевіряємо нове значення. Якщо користувач набрав коректний email, помилка не з'явиться.\\n\\nВисновок\\nСкидання попереднього результату валідації на кожному новому введенні — обов'язкова практика, щоб створювати інтуїтивні форми. Воно забезпечує актуальний зворотний зв'язок і запобігає дезінформуванню користувача.","import React, { useState } from 'react';\\n\\nfunction EmailForm() {\\n  const [email, setEmail] = useState('');\\n  const [error, setError] = useState('');\\n\\n  const validateEmail = (value) => {\\n    // We reset the previous error\\n    setError('');\\n    \\n    if (!value.includes('@')) {\\n      setError('The email must contain @');\\n    }\\n  };\\n\\n  const handleChange = (e) => {\\n    const value = e.target.value;\\n    setEmail(value);\\n    validateEmail(value);\\n  };\\n\\n  return (\\n    <div>\\n      <input\\n        type=\\"email\\"\\n        value={email}\\n        onChange={handleChange}\\n      />\\n      {error && <p style={{color: 'red'}}>{error}</p>}\\n    </div>\\n  );\\n}"],[2519,"Краще показати елементи одразу, але з індикацією процесу валідації. Це покращує користувацький досвід, оскільки користувач бачить миттєвий зворотний зв'язок. Якщо чекати на повну валідацію, інтерфейс здаватиметься повільним. Виняток — критичні дані, де помилка неприпустима.","Вступ\\nПитання стосується балансу між продуктивністю й користувацьким досвідом у роботі з формами або списками даних. Основна дилема: показати елементи одразу (оптимістичний UI) чи після повної валідації (консервативний підхід).\\n\\nОптимістичний UI\\nЦей підхід полягає в тому, щоб відображати дані негайно, навіть якщо вони ще не пройшли перевірки. Наприклад, коли елемент додають до списку:\\n\\nПереваги: інтерфейс залишається відгукливим, і користувач бачить результат миттєво. Недоліки: можливі тимчасово некоректні дані.\\n\\nКонсервативний підхід\\nТут дані відображають лише після успішної валідації. Це гарантує, що користувач ніколи не побачить помилкових даних, але збільшує час очікування.\\n\\nКоли що обирати\\n\\n- Оптимістичний UI — для некритичних даних (наприклад, коментарів, лайків), де тимчасова помилка не страшна.\\n- Консервативний — для фінансових операцій, медичних даних або будь-якого випадку, де помилка неприпустима.\\n\\nВисновок\\nОптимальна стратегія — гібридна: показувати елементи одразу з індикацією статусу валідації, але для критичних даних використовувати блокування інтерфейсу, доки не надійде підтвердження.","function addItem(item) {\\n  // We add it to the state at once\\n  setItems(prev => [...prev, { ...item, status: 'pending' }]);\\n  \\n  // The asynchronous validation\\n  validateItem(item)\\n    .then(validated => {\\n      setItems(prev => prev.map(i => \\n        i.id === item.id ? { ...validated, status: 'valid' } : i\\n      ));\\n    })\\n    .catch(error => {\\n      setItems(prev => prev.filter(i => i.id !== item.id));\\n      showError(error);\\n    });\\n}\\n\\nasync function addItem(item) {\\n  try {\\n    const validated = await validateItem(item);\\n    setItems(prev => [...prev, validated]);\\n  } catch (error) {\\n    showError(error);\\n  }\\n}"],[2520,"Патерн «Команда» перетворює запит або операцію в окремий об'єкт, який містить усю інформацію, потрібну, щоб її виконати. Це дає змогу параметризувати об'єкти операціями, ставити запити в чергу, логувати їх і підтримувати скасування. На фронтенді його часто використовують, щоб реалізувати історію дій (undo/redo), макроси й асинхронні черги.","Що таке патерн «Команда»?\\nПатерн Command — поведінковий патерн проєктування, який перетворює запит у самодостатній об'єкт. Цей об'єкт містить усі дані, потрібні, щоб виконати дію: посилання на отримувача, параметри й метод виконання. Такий підхід відділяє надсилача запиту від його виконавця, що дає гнучкість у керуванні операціями.\\n\\nЯк він працює?\\nОсновні учасники патерну:\\n- Command — інтерфейс із методом execute() й, за потреби, undo().\\n- ConcreteCommand — конкретна реалізація, яка прив'язує дію до отримувача.\\n- Invoker — ініціатор, який зберігає команду й викликає її виконання.\\n- Receiver — об'єкт, який безпосередньо виконує бізнес-логіку.\\n\\nПриклад на JavaScript для фронтенду\\nПодивімося на простий текстовий редактор із можливістю скасовувати дії:\\n\\nДе його застосовують на фронтенді?\\n\\n- Undo/Redo — у текстових редакторах, графічних редакторах, формах.\\n- Макроси й скрипти — запис послідовності дій задля повторного виконання.\\n- Черги асинхронних операцій — наприклад, надсилання кількох запитів із можливістю відкотити.\\n- Компоненти з відкладеним виконанням — кнопки, які ставлять команду в чергу замість діяти негайно.\\n\\nВисновок\\nПатерн «Команда» корисний, коли ініціацію операції потрібно відділити від її виконання, особливо якщо потрібна підтримка скасування, логування або черг. На фронтенді він незамінний, щоб створювати інтерактивні інтерфейси з історією дій і гнучким керуванням операціями користувача.","class Command {\\n  execute() {}\\n  undo() {}\\n}\\n\\nclass InsertTextCommand extends Command {\\n  constructor(receiver, text) {\\n    super();\\n    this.receiver = receiver;\\n    this.text = text;\\n  }\\n  execute() {\\n    this.receiver.insert(this.text);\\n  }\\n  undo() {\\n    this.receiver.deleteLast(this.text.length);\\n  }\\n}\\n\\nclass TextEditor {\\n  constructor() {\\n    this.content = '';\\n    this.history = [];\\n  }\\n  insert(text) {\\n    this.content += text;\\n  }\\n  deleteLast(n) {\\n    this.content = this.content.slice(0, -n);\\n  }\\n  executeCommand(command) {\\n    command.execute();\\n    this.history.push(command);\\n  }\\n  undo() {\\n    const command = this.history.pop();\\n    if (command) command.undo();\\n  }\\n}\\n\\nconst editor = new TextEditor();\\neditor.executeCommand(new InsertTextCommand(editor, 'Hello'));\\neditor.executeCommand(new InsertTextCommand(editor, ' World'));\\nconsole.log(editor.content); // 'Hello World'\\neditor.undo();\\nconsole.log(editor.content); // 'Hello'"],[2521,"На кліку по кнопці в React викликають функцію setState, яка оновлює стан компонента. Це призводить до повторного рендера самого компонента й усіх його дочірніх компонентів, якщо їх не оптимізовано за допомогою React.memo або PureComponent. Повторний рендер відбувається, тому що React порівнює віртуальний DOM й оновлює реальний DOM лише там, де є зміни.","Як працює повторний рендер у React\\nКоли користувач клікає по кнопці, викликають обробник події, який оновлює стан через setState. React позначає компонент як «брудний» і планує повторний рендер. Під час повторного рендера React викликає функцію компонента (або метод render для класових компонентів) і порівнює отриманий віртуальний DOM із попереднім.\\n\\nЯкі компоненти перерендеряться\\n\\n- Компонент, у якому відбулася зміна стану, завжди перерендерюється.\\n- Усі його дочірні компоненти також перерендерюються за замовчуванням, навіть якщо їхні пропси не змінилися.\\n- Якщо дочірній компонент обгорнутий у React.memo або є PureComponent, він перерендериться лише тоді, коли його пропси зміняться.\\n\\nПриклад коду\\n\\nУ цьому прикладі на кліку по кнопці Parent перерендериться, але Child не перерендериться завдяки React.memo, оскільки його пропси не змінилися.\\n\\nВисновок\\nРозуміння механізму повторного рендера допомагає оптимізувати продуктивність React-застосунків, особливо в роботі з великими деревами компонентів. Використовуйте React.memo, useMemo і useCallback, щоб запобігати зайвим повторним рендерам.","function Parent() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(count + 1)}>Click</button>\\n      <Child />\\n    </div>\\n  );\\n}\\n\\nconst Child = React.memo(() => {\\n  console.log('Child rendered');\\n  return <div>Child</div>\\n});"],[2522,"Так, дочірній компонент рендериться наново на кожному набиранні тексту в input. Це відбувається тому, що зміна стану (через useState) у батьківському компоненті спричиняє його повторний рендер, що за замовчуванням призводить до повторного рендера всіх дочірніх компонентів. React не оптимізує цього автоматично, якщо не використовують React.memo або інші методи.","Чому відбувається повторний рендер дочірнього компонента?\\nКоли користувач набирає текст в input, обробник події onChange оновлює стан батьківського компонента за допомогою setState (наприклад, через useState). Зміна стану запускає повторний рендер батька, і React за замовчуванням рекурсивно перемальовує всі його дочірні компоненти, навіть якщо їхні пропси не змінилися. Це стандартна поведінка React, щоб забезпечити актуальність UI.\\n\\nПриклад коду\\n\\nУ цьому прикладі на кожному набиранні тексту в консолі з'являтиметься повідомлення 'Child re-rendered', що підтверджує повторний рендер дочірнього компонента.\\n\\nЯк це застосовують на практиці?\\nТака поведінка може бути небажаною для важких компонентів. Задля оптимізації використовують React.memo, який запобігає повторному рендеру, якщо пропси не змінилися. Також можна винести стан в окремий компонент або використати useMemo/useCallback задля стабільних посилань.\\n\\nВисновок\\nРозуміння цього механізму важливе, щоб оптимізувати продуктивність React-застосунків. Використовуйте React.memo для дочірніх компонентів, які не залежать від стану, що змінюється, аби уникати зайвих рендерів.","function Parent() {\\n  const [text, setText] = useState('');\\n  return (\\n    <div>\\n      <input value={text} onChange={e => setText(e.target.value)} />\\n      <Child />\\n    </div>\\n  );\\n}\\n\\nfunction Child() {\\n  console.log('Child re-rendered');\\n  return <div>Static content</div>;\\n}"],[2523,"Щоб дочірній компонент не рендерився при набиранні тексту в input, обгорніть його в React.memo. Це запобігатиме повторному рендеру, якщо пропси не змінилися. Також переконайтеся, що функції зворотного виклику, які передають у дочірній компонент, обгорнуті в useCallback, аби їхні посилання залишалися стабільними.","Проблема зайвих повторних рендерів\\nУ React, коли стан батьківського компонента змінюється (наприклад, при набиранні тексту в input), усі його дочірні компоненти за замовчуванням перерендерюються. Це може призвести до проблем із продуктивністю, особливо якщо дочірній компонент виконує важкі обчислення або містить складну вкладеність.\\n\\nРішення з React.memo\\nReact.memo — компонент вищого порядку (HOC), який запам'ятовує результат рендерингу. Він порівнює нові пропси з попередніми за допомогою поверхневого порівняння. Якщо пропси не змінилися, React.memo пропускає повторний рендер й використовує закешований результат.\\n\\nВажливість useCallback\\nЯкщо ви передаєте функцію безпосередньо (без useCallback), нове посилання на функцію створюватимуть на кожному рендері батька. React.memo побачить зміну пропа onClick й виконає повторний рендер, незважаючи на обгортку. useCallback гарантує, що посилання на функцію залишиться тим самим, якщо залежності не змінилися.\\n\\nВисновок\\nВикористовуйте React.memo для дочірніх компонентів, які не мають реагувати на зміни стану батька, й поєднуйте його з useCallback для функційних пропсів. Це стандартний підхід до оптимізації продуктивності React-застосунків, особливо в роботі з формами, списками або анімаціями.","import React, { useState, useCallback } from 'react';\\n\\nconst ExpensiveChild = React.memo(({ onClick }) => {\\n  console.log('Child rendered');\\n  return <button onClick={onClick}>Click me</button>;\\n});\\n\\nfunction Parent() {\\n  const [text, setText] = useState('');\\n  \\n  const handleClick = useCallback(() => {\\n    console.log('Button clicked');\\n  }, []);\\n\\n  return (\\n    <div>\\n      <input value={text} onChange={e => setText(e.target.value)} />\\n      <ExpensiveChild onClick={handleClick} />\\n    </div>\\n  );\\n}"],[2524,"useEffect із залежністю виконується після рендера, коли вказане значення змінилося, й призначений задля синхронізації із зовнішнім світом. Обробник події викликають одразу на дію користувача. useEffect придатний для запитів і логування, а обробник — для валідації, надсилання форми й анімацій.","Різниця між useEffect й обробником події\\nУ React побічні ефекти можна виконувати двома основними способами: через \`useEffect\` (декларативно) й через обробники подій (імперативно). Розуміння різниці критичне задля належного керування станом і продуктивністю.\\n\\nКоли код виконується\\n\\n- useEffect запускають після того, як React закомітив зміни в DOM. Якщо вказано масив залежностей, ефект виконується лише тоді, коли ці значення змінюються. Це асинхронно щодо рендера.\\n- Обробник події (наприклад, \`onClick\`) викликають синхронно в момент дії користувача, перед наступним рендером.\\n\\nПриклад коду\\n\\nКоли що використовувати\\n\\n- useEffect — задля синхронізації із зовнішніми системами (запитів, підписок, таймерів), коли потрібно реагувати на зміни стану або пропсів.\\n- Обробник події — задля негайної реакції на дії користувача (валідації, надсилання форми, анімацій, оновлення локального стану).\\n\\nВисновок: використовуйте useEffect для декларативних побічних ефектів, які мають відбуватися після рендера, й обробники подій — для імперативних дій, які потребують миттєвої відповіді.","import { useState, useEffect } from 'react';\\n\\nfunction Example() {\\n  const [count, setCount] = useState(0);\\n\\n  // useEffect: it runs after the render, when count has changed\\n  useEffect(() => {\\n    console.log('Count changed to', count);\\n    // A request to an API can be made here\\n  }, [count]);\\n\\n  // The handler: it is called at once on a click\\n  const handleClick = () => {\\n    console.log('Button clicked, current count:', count);\\n    setCount(count + 1);\\n  };\\n\\n  return <button onClick={handleClick}>Click me</button>;\\n}"],[2525,"Крім useEffect, можна використати useLayoutEffect задля синхронного виконання після DOM-мутацій, callback ref задля безпосереднього доступу до DOM-вузла на монтуванні, MutationObserver, щоб відстежувати появу елемента, й атрибут autofocus у HTML. Ці підходи дають змогу уникати зайвих рендерів і покращити продуктивність.","Альтернативні способи автофокуса\\nАвтофокус на елементі при його появі в DOM можна реалізувати кількома способами, крім стандартного useEffect. Кожний із них має власні особливості й області застосування.\\n\\n1. useLayoutEffect\\nЦей хук виконується синхронно після всіх DOM-мутацій, але перед тим, як браузер намалює зміни. Це гарантує, що фокус буде встановлений перед тим, як користувач побачить елемент.\\n\\n2. Callback ref\\nCallback ref дає змогу виконати дію одразу після того, як елемент змонтувався. Це гнучкіший підхід, який не потребує додаткових ефектів.\\n\\n3. MutationObserver\\nДля елементів, які додають динамічно, можна використати MutationObserver, який відстежує зміни в DOM й встановлює фокус, коли потрібний елемент з'являється.\\n\\n4. HTML-атрибут autofocus\\nНайпростіший спосіб — використати вбудований атрибут autofocus, який працює без JavaScript, але його підтримує не кожний браузер, і він може конфліктувати з React.\\n\\nВисновок: вибір способу залежить від контексту: useLayoutEffect придатний задля синхронного фокуса, callback ref — для простих випадків, MutationObserver — для динамічних елементів, а autofocus — для статичного HTML. Використовуйте ці підходи, щоб оптимізувати продуктивність й уникати зайвих рендерів.","import { useLayoutEffect, useRef } from 'react';\\n\\nfunction AutoFocusInput() {\\n  const inputRef = useRef(null);\\n\\n  useLayoutEffect(() => {\\n    inputRef.current?.focus();\\n  }, []);\\n\\n  return <input ref={inputRef} />;\\n}\\n\\nfunction AutoFocusInput() {\\n  const inputRef = useCallback((node) => {\\n    node?.focus();\\n  }, []);\\n\\n  return <input ref={inputRef} />;\\n}\\n\\nconst observer = new MutationObserver((mutations) => {\\n  mutations.forEach((mutation) => {\\n    mutation.addedNodes.forEach((node) => {\\n      if (node.matches?.('input')) {\\n        node.focus();\\n        observer.disconnect();\\n      }\\n    });\\n  });\\n});\\n\\nobserver.observe(document.body, { childList: true, subtree: true });\\n\\n<input autofocus />"],[2526,"На фронтенд-проєктах я віддаю перевагу модульній архітектурі тек, заснованій на фічах (feature-based). У ній кожний модуль містить усі компоненти, стилі, тести й логіку, пов'язані з ним. Це полегшує навігацію, масштабування й підтримку коду. Наприклад, тека «auth» включає компоненти, хуки, запити до API й утиліти для авторизації.","Вибір архітектури тек на фронтенд-проєктах\\nАрхітектура тек безпосередньо впливає на підтримуваність, масштабованість і швидкість розробки. Найефективніший підхід для середніх і великих проєктів — архітектура на основі фіч (модульна). Вона групує код за функційними можливостями, а не за технічною роллю.\\n\\nЧому на основі фіч?\\n\\n- Ізоляція: кожний модуль самодостатній, що полегшує рефакторинг і видалення функціональності.\\n- Масштабування: нові фічі додають, не змінюючи наявної структури.\\n- Навігація: розробник швидко знаходить потрібний код, оскільки всі пов'язані файли поруч один з одним.\\n\\nПриклад структури\\n\\nВисновок\\nАрхітектуру на основі фіч рекомендують для проєктів, де важливі довгострокова підтримка й командна робота. Вона зменшує зв'язаність коду й прискорює онбординг нових розробників.","src/\\n  features/\\n    auth/\\n      components/\\n        LoginForm.tsx\\n        RegisterForm.tsx\\n      hooks/\\n        useAuth.ts\\n      api/\\n        authApi.ts\\n      utils/\\n        validateEmail.ts\\n      tests/\\n        LoginForm.test.tsx\\n    dashboard/\\n      components/\\n        Chart.tsx\\n        StatsCard.tsx\\n      hooks/\\n        useDashboardData.ts\\n  shared/\\n    ui/\\n      Button.tsx\\n      Modal.tsx\\n    utils/\\n      formatDate.ts\\n  app/\\n    App.tsx\\n    routes.tsx"],[2527,"Щоб знаходити надлишкові повторні рендери, використовують React DevTools Profiler, який показує, які компоненти перемальовуються й чому. Також можна використати console.log або прапорці в компонентах. Інструменти на кшталт Why Did You Render допомагають автоматично виявляти зайві повторні рендери. Оптимізація включає React.memo, useMemo й useCallback.","Інструменти, щоб виявляти надлишкові повторні рендери\\nОсновний інструмент — React DevTools Profiler. Він записує сесію взаємодії із застосунком і показує, які компоненти перемалювалися, скільки це тривало й які пропси або стан змінилися. Це дає змогу швидко знайти проблемні місця.\\n\\nПрактичні підходи\\n\\n- React.memo — він обгортає компонент, запобігаючи повторному рендеру, якщо пропси не змінилися (поверхневе порівняння).\\n- useMemo й useCallback — вони мемоїзують значення й функції, щоб посилання на них залишалися стабільними між рендерами.\\n- Належна структура стану — підіймайте стан лише до потрібного рівня й уникайте зберігання обчислених даних у стані.\\n\\nПриклад коду\\n\\nУ цьому прикладі \`ExpensiveComponent\` перемальовується лише тоді, коли \`text\` змінюється, а не на кожному кліку по кнопці, завдяки \`React.memo\` й \`useMemo\`.\\n\\nВисновок\\nВикористовуйте React DevTools Profiler задля початкового аналізу, а потім застосовуйте мемоїзацію й оптимізацію структури компонентів. Це особливо корисно у великих застосунках із частими оновленнями даних, щоб уникнути обвалу продуктивності.","import React, { useState, useMemo } from 'react';\\n\\nconst ExpensiveComponent = React.memo(({ data }) => {\\n  console.log('Render ExpensiveComponent');\\n  return <div>{data}</div>;\\n});\\n\\nfunction App() {\\n  const [count, setCount] = useState(0);\\n  const [text, setText] = useState('');\\n\\n  // The memoization, so that the reference does not change when count changes\\n  const memoizedData = useMemo(() => text.toUpperCase(), [text]);\\n\\n  return (\\n    <div>\\n      <button onClick={() => setCount(c => c + 1)}>{count}</button>\\n      <input value={text} onChange={e => setText(e.target.value)} />\\n      <ExpensiveComponent data={memoizedData} />\\n    </div>\\n  );\\n}"],[2528,"Кешування у фронтенд-застосунку можна реалізувати на кількох рівнях: HTTP-кеш (через заголовки Cache-Control), кеш браузера (localStorage, sessionStorage, IndexedDB), кеш Service Worker (Cache API) й кеш CDN. Кожний рівень розв'язує власну задачу: HTTP-кеш зменшує кількість запитів до сервера, Service Worker дає змогу кешувати ресурси задля офлайн-режиму, а localStorage/IndexedDB зберігають дані застосунку. Вибір рівня залежить від типу даних і від вимог до їхньої актуальності.","Рівні кешування у фронтенд-застосунку\\nКешування на боці клієнта — ключова техніка, щоб прискорити завантаження сторінок і зменшити навантаження на сервер. Воно дає змогу зберігати копії ресурсів (HTML, CSS, JS, зображень, даних API) локально, аби на повторних запитах їх не завантажували знову. Подивімося на основні рівні кешування.\\n\\nHTTP-кеш (Cache-Control, ETag)\\nЦим рівнем керують заголовки відповіді сервера. Браузер автоматично зберігає відповіді у своєму внутрішньому кеші й використовує їх, доки їхній час життя не спливе. Приклад конфігурації на сервері (Node.js/Express):\\n\\nТут ресурс буде закешований на 1 годину. Щоб перевірити його актуальність, використовують ETag або Last-Modified.\\n\\nКеш Service Worker (Cache API)\\nService Worker — проксі-шар між браузером і мережею. Він може перехоплювати запити й повертати закешовані відповіді, навіть коли інтернету немає. Приклад кешування статичних файлів:\\n\\nЦе дає застосункові змогу працювати офлайн і прискорює завантаження на слабкому з'єднанні.\\n\\nКеш на рівні застосунку (localStorage, IndexedDB)\\nЩоб зберігати дані застосунку (наприклад, налаштування користувача, результати API), використовують Web Storage API або IndexedDB. Приклад із localStorage:\\n\\nIndexedDB придатна для великих обсягів структурованих даних.\\n\\nКеш CDN\\nContent Delivery Network (CDN) кешує статичні ресурси на географічно розподілених серверах. Це не цілком клієнтський кеш, але він впливає на час завантаження. Конфігурація зазвичай відбувається на боці постачальника CDN.\\n\\nВисновок: кешування у фронтенд-застосунку варто застосовувати, щоб покращити користувацький досвід і зменшити навантаження на сервер. HTTP-кеш придатний для статичних файлів, Service Worker — для офлайн-режиму й динамічних даних, а localStorage/IndexedDB — для даних застосунку. Вибір рівня залежить від конкретних вимог до актуальності й обсягу даних.","app.get('/api/data', (req, res) => {\\n  res.set('Cache-Control', 'public, max-age=3600');\\n  res.json({ data: 'some data' });\\n});\\n\\nself.addEventListener('install', event => {\\n  event.waitUntil(\\n    caches.open('v1').then(cache => {\\n      return cache.addAll(['/index.html', '/style.css', '/app.js']);\\n    })\\n  );\\n});\\n\\nself.addEventListener('fetch', event => {\\n  event.respondWith(\\n    caches.match(event.request).then(response => {\\n      return response || fetch(event.request);\\n    })\\n  );\\n});\\n\\n// Saving\\nlocalStorage.setItem('user', JSON.stringify({ name: 'John' }));\\n\\n// Reading\\nconst user = JSON.parse(localStorage.getItem('user'));"],[2529,"Так, ефект буде тригеритися на кожному рендері, якщо в залежності передають spread-об'єкт. Причина в тому, що оператор розгортання створює новий об'єкт щоразу, коли він рендериться, а React порівнює залежності за посиланням. Новий об'єкт завжди має нове посилання, тому useEffect виконуватиметься на кожному рендері, навіть якщо поля об'єкта не змінилися.","Проблема зі spread-об'єктом у залежностях useEffect\\nКоли ви передаєте spread-об'єкт у масив залежностей useEffect, ви створюєте новий об'єкт на кожному рендері. React використовує строге порівняння (===), щоб перевіряти залежності. Оскільки кожний новий об'єкт має унікальне посилання в пам'яті, React вважає, що залежність змінилася, й запускає ефект наново.\\n\\nПриклад коду\\n\\nУ цьому прикладі ефект виконуватиметься на кожному рендері, навіть якщо data не змінився. Це відбувається тому, що { ...data } створює новий об'єкт із новим посиланням.\\n\\nПравильне рішення\\nЩоб уникнути цієї проблеми, передавайте в залежності конкретні поля об'єкта:\\n\\nАбо використайте стабільне посилання на об'єкт, якщо він не змінюється:\\n\\nВисновок\\nВикористовуйте оператор розгортання в залежностях useEffect лише якщо вам справді потрібно реагувати на кожну зміну об'єкта. У більшості випадків краще передавати конкретні поля або використати useMemo, щоб стабілізувати посилання.","const MyComponent = ({ data }) => {\\n  useEffect(() => {\\n    console.log('Effect runs');\\n  }, [{ ...data }]); // A new object every time\\n\\n  return <div>{data.name}</div>;\\n};\\n\\nuseEffect(() => {\\n  console.log('Effect runs only when name changes');\\n}, [data.name]); // Only the particular field\\n\\nconst stableData = useMemo(() => data, [data]);\\n\\nuseEffect(() => {\\n  console.log('Effect runs');\\n}, [stableData]);"],[2530,"Використовуйте useRef, щоб зберігати попереднє значення пропа. Усередині useEffect оновлюйте ref.current після того, як використали його для порівняння. Це дає змогу отримати попереднє значення на наступному рендері.","Як отримати попереднє значення пропа за допомогою useRef\\nУ React немає вбудованого способу отримати попереднє значення пропа, але це можна зробити за допомогою хука useRef разом із useEffect. useRef створює об'єкт, який зберігає своє значення між рендерами, не спричиняючи повторного рендера при зміні.\\n\\nРеалізація\\nСтворіть ref, який зберігатиме попереднє значення. Усередині useEffect оновлюйте ref.current після того, як використали його. Отже, на наступному рендері ref.current міститиме попереднє значення.\\n\\nЯк це працює\\n\\n- useRef створює ref із початковим значенням undefined.\\n- useEffect запускають після кожного рендера, коли value змінюється.\\n- Усередині useEffect ми оновлюємо ref.current, але це не спричиняє повторного рендера.\\n- На наступному рендері usePrevious повертає попереднє значення, оскільки ref.current ще не оновили.\\n\\nВисновок\\nЦей патерн корисний, щоб порівнювати поточні й попередні значення пропсів — наприклад, задля анімацій, логування або умовних ефектів. Його просто реалізувати, й він не потребує додаткових бібліотек.","import { useRef, useEffect } from 'react';\\n\\nfunction usePrevious(value) {\\n  const ref = useRef();\\n  useEffect(() => {\\n    ref.current = value;\\n  }, [value]);\\n  return ref.current;\\n}\\n\\nfunction MyComponent({ count }) {\\n  const prevCount = usePrevious(count);\\n  return (\\n    <div>\\n      <p>The current one: {count}</p>\\n      <p>The previous one: {prevCount}</p>\\n    </div>\\n  );\\n}"],[2531,"Передавання функції в useState дає змогу виконати ініціалізацію стану лише один раз, на першому рендері. Це корисно, коли початкове значення потребує складного обчислення або читання з localStorage. На відміну від передавання значення, функцію не викликатимуть на кожному оновленні компонента, що покращує продуктивність.","Що таке лінива ініціалізація в useState?\\nУ React хук useState може приймати не лише значення, а й функцію. Коли передають функцію, React викликає її лише один раз — на першому рендері компонента. Це називають лінивою ініціалізацією. Результат виклику функції стає початковим станом.\\n\\nКоли це потрібно?\\nЛінива ініціалізація корисна, коли початковий стан потребує дорогих операцій: читання з localStorage, складних математичних обчислень, парсингу великих даних. Без неї ці операції виконували б на кожному рендері, навіть якщо стан уже ініціалізували.\\n\\nПриклад коду\\n\\nВідмінність від передавання значення\\nЯкщо ви передаєте значення, його обчислюватимуть на кожному рендері (якщо це вираз). Функцію ж викликають лише один раз. Це особливо важливо для важких операцій або коли початкове значення залежить від пропсів, які можуть змінюватися.\\n\\nВисновок\\nВикористовуйте ліниву ініціалізацію в useState, коли початковий стан потребує дорогих обчислень або асинхронних операцій. Це покращує продуктивність і робить код передбачуванішим.","// Bad: the computation on every render\\nconst [state, setState] = useState(expensiveComputation());\\n\\n// Good: the computation only once\\nconst [state, setState] = useState(() => expensiveComputation());\\n\\n// An example with localStorage\\nconst [theme, setTheme] = useState(() => {\\n  const saved = localStorage.getItem('theme');\\n  return saved ? saved : 'light';\\n});"],[2532,"У useState можна покласти будь-яке значення: примітив (число, рядок, булеве), об'єкт, масив, null, undefined або функцію. Якщо передають функцію, React викличе її лише на першому рендері — це називають лінивою ініціалізацією. Не можна передавати Promise або інші асинхронні значення безпосередньо.","Що можна передати в initialValue useState?\\nХук \`useState\` у React приймає початкове значення стану. Це може бути будь-який тип даних JavaScript: примітиви (числа, рядки, булеві), об'єкти, масиви, \`null\`, \`undefined\` або навіть функція. Основне правило: значення має бути синхронним, а не асинхронним (наприклад, Promise не підійде).\\n\\nЛінива ініціалізація\\nЯкщо початковий стан потребує складного обчислення, можна передати функцію. React викличе її лише один раз, на першому рендері компонента, що покращує продуктивність. Наприклад:\\n\\nЦе особливо корисно, коли початкове значення отримують із localStorage або з API (але синхронно).\\n\\nПриклади використання\\n\\n- Примітиви: \`useState(0)\`, \`useState('hello')\`, \`useState(true)\`\\n- Об'єкти: \`useState({ name: 'John', age: 30 })\`\\n- Масиви: \`useState([1, 2, 3])\`\\n- null/undefined: \`useState(null)\`\\n- Функція: \`useState(() => 42)\`\\n\\nЩо не можна передати?\\nНе можна передавати асинхронних значень, як-от Promise або результату виклику асинхронної функції. Якщо дані потрібно завантажити із сервера, використайте \`useEffect\`, щоб встановити стан після монтування.\\n\\nВисновок\\nВикористовуйте \`useState\` із будь-яким синхронним значенням. Для дорогих обчислень застосовуйте ліниву ініціалізацію через функцію. Це стандартна практика в React задля керування станом компонентів.","const [state, setState] = useState(() => {\\n  const initial = expensiveComputation();\\n  return initial;\\n});"],[2533,"Хуки в React виконуються синхронно під час рендерингу компонента. Це означає, що виклик хука на кшталт useState або useEffect відбувається в тому самому потоці, що й рендеринг. Однак оновлення стану, спричинене хуком, може бути відкладене й оброблене асинхронно на наступному рендері. Важливо пам'ятати, що самі хуки не асинхронні, але їхні ефекти можуть бути такими.","Синхронна природа хуків\\nХуки в React, як-от useState, useEffect, useContext й інші, виконуються синхронно під час рендерингу компонента. Це означає, що коли ви викликаєте хук, його логіку обробляють негайно, у тому самому потоці виконання, що й функцію компонента. React гарантує, що порядок викликів хуків зберігається між рендерами, що дає йому змогу належно зв'язувати стан й ефекти.\\n\\nПриклад синхронного виконання\\n\\nУ цьому прикладі useState викликають синхронно, і значення count доступне одразу після виклику. Однак setCount, який оновлює стан, працює асинхронно: React планує новий рендер, але не виконує його миттєво.\\n\\nАсинхронні аспекти\\nХоча самі хуки синхронні, деякі їхні ефекти можуть бути асинхронними. Наприклад, useEffect може містити асинхронні операції, як-от запити до API. Але сам хук useEffect викликають синхронно після рендерингу, а його колбек виконується пізніше.\\n\\nТут useEffect реєструє ефект синхронно, але fetch виконується асинхронно.\\n\\nВисновок\\nХуки React синхронні за природою, що забезпечує передбачуваність і порядок виконання. Асинхронність виникає лише в колбеках ефектів або коли стан оновлюється, що планують на наступний рендер. Це важливо враховувати в розробці, щоб уникати помилок, пов'язаних з очікуванням миттєвих змін стану.","function Counter() {\\n  const [count, setCount] = useState(0); // synchronously\\n  console.log('Render:', count); // it runs at once\\n  return <button onClick={() => setCount(count + 1)}>{count}</button>;\\n}\\n\\nuseEffect(() => {\\n  fetch('/data').then(response => response.json()); // asynchronously\\n}, []);"],[2534,"Компонент-степер відображає послідовність кроків. Проп length задає загальну кількість кроків, а activeStep указує на поточний активний крок. Компонент візуально підсвічує активний крок і показує прогрес користувача. Це полегшує навігацію в багатокрокових формах або процесах.","Що таке компонент-степер?\\nКомпонент Stepper — елемент UI, який візуалізує послідовність кроків у процесі — наприклад, у багатокроковій формі або в помічникові налаштування. Він допомагає користувачеві зрозуміти, на якому етапі він перебуває й скільки кроків залишилося.\\n\\nПропси length й activeStep\\nПроп \`length\` визначає загальну кількість кроків у процесі. Проп \`activeStep\` указує індекс поточного активного кроку (починаючи з 0). Компонент використовує ці значення, щоб відображати індикатори кроків, підсвічувати активний крок й, можливо, позначати завершені кроки.\\n\\nПриклад реалізації\\n\\nЗастосування\\nСтепери широко використовують у формах реєстрації, процесах оформлення замовлення, налаштуванні застосунків й у будь-якому сценарії, у якому дії потрібно виконувати крок за кроком. Вони покращують користувацький досвід, роблячи процес прозорим і керованим.\\n\\nВисновок: компонент-степер із пропсами length й activeStep — простий, ефективний спосіб візуалізувати прогрес у багатокрокових інтерфейсах. Його варто застосовувати всюди, де користувачеві потрібно виконати кілька кроків послідовно, щоб зменшити когнітивне навантаження й покращити зручність.","function Stepper({ length, activeStep }) {\\n  const steps = Array.from({ length }, (_, i) => i);\\n  return (\\n    <div style={{ display: 'flex', gap: '8px' }}>\\n      {steps.map((step) => (\\n        <div\\n          key={step}\\n          style={{\\n            width: '30px',\\n            height: '30px',\\n            borderRadius: '50%',\\n            backgroundColor: step === activeStep ? '#007bff' : '#ccc',\\n            display: 'flex',\\n            alignItems: 'center',\\n            justifyContent: 'center',\\n            color: '#fff',\\n          }}\\n        >\\n          {step + 1}\\n        </div>\\n      ))}\\n    </div>\\n  );\\n}"],[2535,"Елемент \`<dialog>\` у HTML має атрибут open, який показує діалог. У React керування ним через проп open означає, що компонент контролює видимість діалогу за допомогою стану. Коли open дорівнює true, діалог відображають; інакше його приховують. Щоб його закрити, можна використати метод close() або змінити стан.","Керування через проп open\\nЕлемент \`<dialog>\` — нативний HTML-елемент, щоб створювати модальні вікна. У React керування його видимістю через проп open дає змогу зробити компонент керованим: стан батька визначає, чи діалог відкритий.\\n\\nЯк це працює\\nПроп open — булеве значення. Коли воно true, діалог відображають; коли false — приховують. Однак просто встановити атрибут open недостатньо задля належної роботи модального вікна: також потрібно використовувати методи show() або showModal() задля відкриття й close() задля закриття. У React це роблять через refs й ефекти.\\n\\nПриклад коду\\n\\nЗастосування\\nТакий підхід використовують, щоб створювати модальні вікна, попапи або діалоги підтвердження. Проп open дає батьківському компонентові повний контроль над видимістю, що полегшує керування станом.\\n\\nВисновок: використовуйте керування через проп open, коли стан діалогу потрібно синхронізувати із зовнішніми даними — наприклад, щоб відкрити його на кліку або після завантаження.","import React, { useRef, useEffect } from 'react';\\n\\nfunction Dialog({ open, onClose, children }) {\\n  const dialogRef = useRef(null);\\n\\n  useEffect(() => {\\n    const dialog = dialogRef.current;\\n    if (open) {\\n      dialog.showModal(); // or show() for a non-modal one\\n    } else {\\n      dialog.close();\\n    }\\n  }, [open]);\\n\\n  return (\\n    <dialog ref={dialogRef} onClose={onClose}>\\n      {children}\\n      <button onClick={onClose}>Close</button>\\n    </dialog>\\n  );\\n}"],[2536,"Елемент \`<dialog>\` надає методи showModal() і close() для керування своїм відображенням. У React потрібно дістатися DOM-елемента через useRef, а потім викликати ці методи у своїх обробниках подій. Це дозволяє створювати модальні вікна без сторонніх бібліотек.","Що таке елемент \`<dialog>\`\\nЕлемент \`<dialog>\` — нативний HTML-елемент, призначений для створення модальних вікон і діалогів. Він надає вбудовані методи showModal() для відкриття вікна в модальному режимі (із заблокованим тлом) і close() для його закриття. Це спрощує розробку, оскільки не потрібні додаткові бібліотеки.\\nВикористання в React через рефи\\nУ React для доступу до DOM-елемента використовується хук useRef. Створюється реф і прикріплюється до елемента \`<dialog>\`. Потім методи showModal() і close() викликаються в обробниках подій (наприклад, onClick) через значення current рефа.\\n\\nОсобливості та застосування\\nМетод showModal() відкриває діалог поверх решти вмісту й блокує взаємодію з тлом. Щоб закрити його, можна використати close() або натиснути клавішу Escape. Елемент \`<dialog>\` також підтримує подію 'close', яку можна обробити для додаткової логіки. Цей підхід корисний для простих модальних вікон, повідомлень або форм, коли не потрібні складна анімація чи налаштування.\\nВисновок: використовуйте \`<dialog>\` з рефами в React, щоб швидко створювати модальні вікна без зовнішніх залежностей, якщо ваш проєкт не вимагає складного керування станом або стилізацією.","import { useRef } from 'react';\\n\\nfunction Modal() {\\n  const dialogRef = useRef(null);\\n\\n  const openModal = () => {\\n    dialogRef.current?.showModal();\\n  };\\n\\n  const closeModal = () => {\\n    dialogRef.current?.close();\\n  };\\n\\n  return (\\n    <>\\n      <button onClick={openModal}>Open Modal</button>\\n      <dialog ref={dialogRef}>\\n        <p>Modal content</p>\\n        <button onClick={closeModal}>Close</button>\\n      </dialog>\\n    </>\\n  );\\n}"],[2537,"React.memo приймає функцію порівняння (areEqual) як свій необов'язковий другий аргумент. Вона отримує попередні й нові пропси й має повернути true, якщо пропси рівні (повторного рендера не потрібно), і false, якщо вони різні (повторний рендер потрібний). За замовчуванням використовують поверхневе порівняння.","Що таке React.memo й для чого потрібний другий аргумент\\nReact.memo — компонент вищого порядку (HOC), який мемоїзує функційний компонент. Він запобігає повторному рендерингу, якщо пропси не змінилися. За замовчуванням React.memo використовує поверхневе порівняння пропсів. Однак у деяких випадках потрібна власна логіка порівняння — саме для цього й існує другий аргумент.\\n\\nДругий аргумент: функція areEqual\\nДругий аргумент — функція, яка приймає два параметри: prevProps і nextProps. Вона має повернути true, якщо пропси вважають рівними (повторного рендера не потрібно), і false, якщо вони різні (повторний рендер потрібний). Якщо функцію не передали, React.memo використовує стандартне поверхневе порівняння.\\n\\nКоли це корисно?\\n\\n- Коли пропси містять об'єкти або масиви, які створюють наново на кожному рендері батька, тоді як їхній вміст не змінюється.\\n- Коли потрібно ігнорувати зміни певних пропсів.\\n- Задля оптимізації продуктивності в компонентах із важкими обчисленнями.\\n\\nВажливі зауваження\\n\\n- Функцію порівняння викликають лише тоді, коли пропси змінюються. Якщо компонент перерендерюється з іншої причини (наприклад, через зміну стану), мемоїзацію не застосовують.\\n- Не варто зловживати власним порівнянням — воно саме може бути дорогим.\\n- Якщо функція порівняння надто часто повертає false, мемоїзація втрачає сенс.\\n\\nВисновок: другий аргумент React.memo — функція areEqual задля точного контролю над тим, коли компонент має перерендерюватися. Використовуйте її, коли поверхневого порівняння недостатньо — наприклад, у роботі з вкладеними об'єктами або масивами, — щоб уникати зайвих повторних рендерів і покращити продуктивність.","const MyComponent = React.memo(\\n  (props) => <div>{props.value}</div>,\\n  (prevProps, nextProps) => {\\n    // The custom comparison logic\\n    return prevProps.value === nextProps.value;\\n  }\\n);"],[2538,"Щоб ініціалізувати масив у useState, передайте масив як початкове значення: const [items, setItems] = useState([]). Якщо масив має бути порожнім, використовуйте порожній масив []. Для заздалегідь заповненого масиву передайте його безпосередньо: useState([1, 2, 3]). Уникайте передавання функції, яка повертає масив, якщо не потрібна лінива ініціалізація.","Ініціалізація масиву в useState\\nУ React хук useState дає змогу зберігати стан компонента. Для масиву початкове значення передають як аргумент. Найпростіший випадок — порожній масив: \`useState([])\`. Якщо масив має містити дані, передайте їх безпосередньо: \`useState([1, 2, 3])\`.\\n\\nЛінива ініціалізація\\nЯкщо початковий стан потребує складного обчислення, використайте функцію-ініціалізатор: \`useState(() => computeInitialArray())\`. Це гарантує, що обчислення виконають лише один раз, на першому рендері.\\n\\nПриклад коду\\n\\nВажливі моменти\\n\\n- Не змінюйте масив безпосередньо (push, splice) — використовуйте методи, які повертають новий масив (spread, concat, filter, map).\\n- Щоб оновити стан, завжди передавайте нове значення або функцію, яка повертає нове значення.\\n- У роботі з об'єктами всередині масиву створюйте копії об'єктів, коли їх змінюєте.\\n\\nВисновок: належна ініціалізація масиву в useState — передавання початкового значення (порожнього або заповненого) або функції задля лінивої ініціалізації. Це основа роботи з колекціями даних у React.","import React, { useState } from 'react';\\n\\nfunction TodoList() {\\n  const [todos, setTodos] = useState([]); // an empty array\\n  const [initialTodos] = useState(() => {\\n    // the lazy initialization\\n    return ['Learn React', 'Build project'];\\n  });\\n\\n  const addTodo = (text) => {\\n    setTodos([...todos, text]); // the addition of an element\\n  };\\n\\n  return (\\n    <div>\\n      <ul>\\n        {todos.map((todo, index) => (\\n          <li key={index}>{todo}</li>\\n        ))}\\n      </ul>\\n      <button onClick={() => addTodo('New task')}>Add</button>\\n    </div>\\n  );\\n}"],[2539,"Проблема в тому, що setInterval створює замикання над значенням стану, яким воно було в момент створення інтервалу. Щоб використати актуальне значення, можна передати функцію в setState (prev => prev + 1) або використати useRef, щоб зберігати поточне значення. Також можна перестворювати інтервал, коли залежність змінюється, за допомогою useEffect.","Проблема із замиканнями в setInterval\\nКоли ви використовуєте setInterval усередині useEffect, функція зворотного виклику створює замикання над змінною стану, яка була актуальною в момент створення інтервалу. Це означає, що навіть якщо стан оновлюється, інтервал і далі використовує старе значення.\\n\\nРішення з функційним оновленням\\nНайпростіший спосіб — використати функційну форму setState, яка отримує попередній стан і повертає новий:\\n\\nРішення з useRef\\nІнший підхід — зберігати актуальне значення в ref й читати його всередині інтервалу:\\n\\nВисновок\\nВикористовуйте функційне оновлення стану для простих випадків або useRef, коли актуальне значення потрібно прочитати без перестворення інтервалу. Це гарантує належну роботу таймерів й дає змогу уникнути багів із застарілими даними.","const [count, setCount] = useState(0);\\n\\nuseEffect(() => {\\n  const id = setInterval(() => {\\n    setCount(prev => prev + 1); // it always uses the current value\\n  }, 1000);\\n  return () => clearInterval(id);\\n}, []);\\n\\nconst [count, setCount] = useState(0);\\nconst countRef = useRef(count);\\n\\nuseEffect(() => {\\n  countRef.current = count;\\n}, [count]);\\n\\nuseEffect(() => {\\n  const id = setInterval(() => {\\n    console.log(countRef.current); // always current\\n  }, 1000);\\n  return () => clearInterval(id);\\n}, []);"],[2540,"TanStack Query (React Query) спеціалізується на керуванні серверним станом: кешуванні, синхронізації й оновленні даних з API. Redux — універсальний менеджер стану, який часто використовують для клієнтського стану, але для серверного стану він потребує, щоб писали чимало шаблонного коду (редюсери, дії, thunk'и). TanStack Query автоматично обробляє кеш, фоновий refetching й інвалідацію, а Redux залишає це розробникові.","Основна різниця\\nTanStack Query (раніше React Query) і Redux розв'язують різні задачі, хоча обидва керують станом. TanStack Query створили спеціально для роботи із серверним станом — даними, які надходять з API й можуть застаріти. Він надає вбудовані механізми задля кешування, фонового refetching, пагінації й інвалідації. Redux — універсальний контейнер для стану, який не розрізняє серверних і клієнтських даних. Щоб працювати з API в Redux, доводиться вручну налаштовувати middleware (наприклад, Redux Thunk або Redux Saga) й писати редюсери для кожного запиту.\\n\\nПриклад коду\\nTanStack Query:\\n\\nRedux із Thunk:\\n\\nКоли що використовувати\\n\\n- TanStack Query — для будь-якого застосунку, який активно взаємодіє з API. Він скорочує код, автоматично оновлює дані й керує кешем.\\n- Redux — коли потрібний складний клієнтський стан (наприклад, кошик, налаштування UI, форми) або коли серверний і клієнтський стан тісно переплетені.\\n\\nВисновок: TanStack Query — найкращий вибір для серверного стану, Redux — для клієнтського. Їх можна поєднувати в одному проєкті.","import { useQuery } from '@tanstack/react-query';\\n\\nfunction Posts() {\\n  const { data, isLoading, error } = useQuery({\\n    queryKey: ['posts'],\\n    queryFn: () => fetch('/api/posts').then(res => res.json()),\\n  });\\n\\n  if (isLoading) return 'Loading...';\\n  if (error) return 'Error!';\\n  return data.map(post => <div key={post.id}>{post.title}</div>);\\n}\\n\\n// actions.js\\nexport const fetchPosts = () => async (dispatch) => {\\n  dispatch({ type: 'posts/fetchStart' });\\n  try {\\n    const res = await fetch('/api/posts');\\n    const data = await res.json();\\n    dispatch({ type: 'posts/fetchSuccess', payload: data });\\n  } catch (err) {\\n    dispatch({ type: 'posts/fetchError', payload: err });\\n  }\\n};\\n\\n// reducer.js\\nconst initialState = { data: [], isLoading: false, error: null };\\nexport default function postsReducer(state = initialState, action) {\\n  switch (action.type) {\\n    case 'posts/fetchStart': return { ...state, isLoading: true };\\n    case 'posts/fetchSuccess': return { ...state, isLoading: false, data: action.payload };\\n    case 'posts/fetchError': return { ...state, isLoading: false, error: action.payload };\\n    default: return state;\\n  }\\n}"],[2541,"Щоб передати параметр в onClick, не викликавши функції негайно, використовуйте стрілкову функцію: onClick={() => handleClick(param)}. Це створює нову функцію, яку викличуть на кліку. Як альтернативу можна використати .bind: onClick={handleClick.bind(null, param)}. Безпосередній виклик handleClick(param) виконає функцію одразу, під час рендера.","Передавання параметрів в обробник onClick\\nУ React й JavaScript важливо передавати параметри в обробники подій так, щоб функцію не викликали негайно, коли компонент рендериться. Якщо написати \`onClick={handleClick(param)}\`, \`handleClick\` виконається одразу, а не на кліку, що часто призводить до багів.\\n\\nОсновні способи\\n\\n- Стрілкова функція: \`onClick={() => handleClick(param)}\` — вона створює нову функцію, яку викличуть на подію. Це найпоширеніший і найчитабельніший спосіб.\\n- Метод .bind: \`onClick={handleClick.bind(null, param)}\` — він повертає нову функцію з прив'язаним контекстом й аргументами. Він може бути менш продуктивним за частих повторних рендерів, але працює належно.\\n\\nПриклад коду\\n\\nУ цьому прикладі \`id\` передають у \`handleClick\` лише на кліку, а не під час рендера.\\n\\nВисновок\\nВикористовуйте стрілкові функції, щоб передавати параметри в обробники подій у React — це просто, безпечно й відповідає найкращим практикам. Уникайте безпосередніх викликів функцій у JSX, щоб запобігти неочікуваному виконанню коду.","function Button({ id }) {\\n  const handleClick = (param) => {\\n    console.log('Clicked:', param);\\n  };\\n\\n  return (\\n    <button onClick={() => handleClick(id)}>\\n      Click me\\n    </button>\\n  );\\n}"],[2542,"React використовує поверхневе порівняння, щоб визначати зміни стану. Коли ви викликаєте setState, React порівнює попереднє й нове значення за допомогою оператора строгої рівності (===). Мутація масиву через push змінює вміст масиву, але посилання на масив залишається тим самим. Тому React вважає, що стан не змінився, й не запускає повторного рендера.","Чому мутація не спричиняє повторного рендера?\\nУ React стан має бути незмінним. Коли ви використовуєте хук \`useState\`, React зберігає посилання на об'єкт стану. Коли викликають функцію оновлення (наприклад, \`setState\`), React порівнює нове значення з попереднім за допомогою \`Object.is\` (аналога \`===\`). Якщо посилання не змінилося, React вважає, що стан залишився тим самим, і пропускає повторний рендер.\\n\\nПриклад проблеми\\n\\nЯк це працює під капотом?\\nReact використовує алгоритм узгодження. Коли викликають \`setState\`, React позначає компонент як такий, що потребує оновлення. Потім, під час рендера, він порівнює попереднє дерево віртуального DOM із новим. Якщо стан не змінився (за посиланням), React пропускає рендер компонента й його дочірніх елементів, що покращує продуктивність.\\n\\nВисновок\\nЗавжди створюйте нові об'єкти й масиви, оновлюючи стан у React. Використовуйте оператор розгортання, \`map\`, \`filter\` або бібліотеки на кшталт Immer задля зручної роботи з незмінністю. Це гарантує, що зміни виявляють належно, а інтерфейс поводиться передбачувано.","const [items, setItems] = useState([1, 2, 3]);\\n\\n// Wrong: a mutation\\nitems.push(4);\\nsetItems(items); // React does not see the changes, so there will be no re-render\\n\\n// Right: the creation of a new array\\nsetItems([...items, 4]); // A new reference, so a re-render will happen"],[2543,"Якщо асинхронна операція в useEffect повертає помилку, React не обробляє її автоматично. Помилка може призвести до необробленого проміса, який спричинить попередження в консолі або падіння застосунку. Задля належної обробки потрібно використати try/catch усередині ефекту й оновити стан помилки. Також важливо скасовувати запити, коли компонент демонтується, через функцію очищення.","Що відбувається при помилці в асинхронному useEffect?\\nКоли ви виконуєте асинхронну операцію всередині useEffect — наприклад, fetch-запит — й вона завершується помилкою, React не перехоплює цієї помилки автоматично. Це може призвести до необробленого відхилення проміса, яке в строгих середовищах (наприклад, у Node.js) може завершити процес, а в браузері просто виводить попередження в консоль. Компонент тим часом не дізнається про помилку, а користувач не бачить жодного повідомлення.\\n\\nЯк належно обробляти помилки?\\nЗадля належної обробки використовуйте конструкцію try/catch усередині асинхронної функції, оголошеної в useEffect. Оновлюйте стан компонента, щоб відобразити помилку користувачеві. Також важливо скасовувати запити, коли компонент демонтується, щоб уникнути оновлення стану після демонтування (це спричиняє попередження React).\\n\\nПрактичні рекомендації\\n\\n- Завжди обгортайте свій асинхронний код у try/catch усередині useEffect.\\n- Використовуйте прапорець або AbortController, щоб скасовувати запити, коли він демонтується.\\n- Не робіть сам useEffect асинхронним — React очікує, що ефект повертає функцію очищення або undefined.\\n\\nВисновок: обробка помилок в асинхронних операціях useEffect — обов'язкова практика задля стабільних React-застосунків. Вона запобігає необробленим промісам і дає змогу належно повідомляти користувача про проблеми.","useEffect(() => {\\n  let cancelled = false;\\n  async function fetchData() {\\n    try {\\n      const response = await fetch('/api/data');\\n      if (!cancelled) {\\n        setData(await response.json());\\n      }\\n    } catch (error) {\\n      if (!cancelled) {\\n        setError(error.message);\\n      }\\n    }\\n  }\\n  fetchData();\\n  return () => { cancelled = true; };\\n}, []);"],[2544,"Next.js — це фреймворк на основі React, який додає серверний рендеринг (SSR), статичну генерацію (SSG), маршрутизацію на основі файлової системи й API-маршрути. На відміну від чистого React, який є лише клієнтською бібліотекою для UI, Next.js надає готову архітектуру для full-stack застосунків. Він полегшує SEO, покращує продуктивність завдяки завантаженню даних заздалегідь і автоматично оптимізує бандли.","Призначення Next.js\\nNext.js — готовий до продакшну фреймворк для React, який розв'язує задачі, що лежать за межами клієнтської бібліотеки. Він надає вбудовані рішення для серверного рендерингу (SSR), статичної генерації (SSG), інкрементальної статичної регенерації (ISR), маршрутизації, оптимізації зображень і API-маршрутів. Це дозволяє створювати і повноцінні вебзастосунки з серверною логікою, і високопродуктивні статичні сайти.\\nКлючові відмінності від чистого React\\n\\n- Маршрутизація: у React використовують React Router, який працює на клієнті. Next.js використовує файлову систему, щоб визначати маршрути (pages/ або app/), що полегшує навігацію й підтримує динамічні шляхи.\\n- Рендеринг: React рендерить усе на клієнті (CSR). Next.js дозволяє вибирати між CSR, SSR, SSG та ISR для кожної сторінки, що покращує SEO й час завантаження.\\n- API-маршрути: Next.js дозволяє створювати серверні ендпоїнти всередині проєкту (pages/api), що знімає потребу в окремому бекенді для простих задач.\\n- Оптимізація: вбудована оптимізація зображень, шрифтів і скриптів, а також автоматичне розбиття коду — у React це вимагає додаткових бібліотек.\\nПриклад коду: сторінка з SSR у Next.js\\n\\nУ цьому прикладі дані завантажують на сервері, перед тим як HTML буде надіслано клієнтові, що покращує SEO й час до першого контенту (FCP). У чистому React довелося б використовувати useEffect і обробляти стан завантаження.\\nВисновок\\nNext.js варто застосовувати, коли потрібна SEO-оптимізація, швидке завантаження сторінок, вбудована серверна логіка або статична генерація контенту. Для простих односторінкових застосунків без потреби в SEO чистий React може бути легшим рішенням.","// pages/posts/[id].js\\nexport async function getServerSideProps(context) {\\n  const { id } = context.params;\\n  const res = await fetch(\`https://api.example.com/posts/\${id}\`);\\n  const post = await res.json();\\n  return { props: { post } };\\n}\\n\\nexport default function Post({ post }) {\\n  return <div><h1>{post.title}</h1><p>{post.body}</p></div>;\\n}"],[2545,"React Fragment — вбудований компонент React, який дає змогу групувати кілька елементів, не додаючи зайвого вузла до DOM. Його використовують, коли з компонента потрібно повернути кілька елементів, але обгортка на кшталт \`<div>\` ламає структуру або стилі. Fragment не створює реального HTML-елемента, що покращує продуктивність і чистоту розмітки.","Що таке React Fragment?\\nReact Fragment — легкий спосіб групувати дочірні елементи в JSX, не додаючи зайвого вузла до DOM. У звичайному JSX не можна повернути кілька елементів без обгортки, тому часто використовують \`<div>\`. Однак це може призвести до надлишкової вкладеності, до проблем із CSS (наприклад, із Flexbox або Grid) й до зайвих вузлів, які сповільнюють рендеринг.\\n\\nДля чого він потрібний?\\nFragment розв'язує ці проблеми: він не створює реального HTML-елемента, а лише групує дітей для React. Це особливо корисно в таблицях, у списках або коли використовують CSS-сітки, де зайвий \`<div>\` може зламати розкладку.\\n\\nПриклад використання\\n\\nМожна також використати скорочений синтаксис \`<>...</>\`, який не потребує імпорту.\\n\\nВисновок\\nReact Fragment — простий, ефективний інструмент, щоб групувати елементи, не забруднюючи DOM. Застосовуйте його щоразу, коли обгортка потрібна лише для JSX, а не для стилів або семантики.","import React, { Fragment } from 'react';\\n\\nfunction Table() {\\n  return (\\n    <table>\\n      <tr>\\n        <Fragment>\\n          <td>Cell 1</td>\\n          <td>Cell 2</td>\\n        </Fragment>\\n      </tr>\\n    </table>\\n  );\\n}"],[2546,"useRef створює об'єкт із властивістю .current, яка зберігається між рендерами. Задля доступу до DOM-елемента потрібно передати ref в атрибут елемента. useRef також використовують, щоб зберігати будь-які змінювані дані (наприклад, таймери, попередні значення), зміна яких не спричиняє повторного рендера компонента.","Що таке useRef і як він працює\\nuseRef — хук React, який повертає змінюваний ref-об'єкт з єдиною властивістю .current. Цей об'єкт зберігається протягом усього життєвого циклу компонента й не змінюється між рендерами. На відміну від useState, зміна ref.current не спричиняє повторного рендера компонента.\\n\\nДоступ до DOM-елементів\\nОсновне застосування useRef — отримання безпосереднього доступу до DOM-елемента. Це корисно, щоб сфокусувати поле введення, задля анімацій й задля інтеграції з бібліотеками, які працюють із DOM безпосередньо.\\n\\nЗберігання змінюваних значень\\nuseRef також використовують, щоб зберігати будь-які дані, які потрібно зберегти між рендерами, не впливаючи на них. Наприклад, щоб зберігати ідентифікатор таймера, попереднє значення пропа або екземпляр стороннього об'єкта.\\n\\nВисновок\\nuseRef — універсальний інструмент для роботи з DOM й задля зберігання змінюваних даних у React. Його варто застосовувати, коли потрібен безпосередній доступ до елемента або треба зберегти значення, не спричиняючи повторного рендера — наприклад, для таймерів, анімацій або інтеграції із зовнішніми бібліотеками.","import { useRef, useEffect } from 'react';\\n\\nfunction AutoFocusInput() {\\n  const inputRef = useRef(null);\\n\\n  useEffect(() => {\\n    inputRef.current.focus();\\n  }, []);\\n\\n  return <input ref={inputRef} type=\\"text\\" />;\\n}\\n\\nimport { useRef, useEffect, useState } from 'react';\\n\\nfunction Timer() {\\n  const [count, setCount] = useState(0);\\n  const intervalRef = useRef(null);\\n\\n  useEffect(() => {\\n    intervalRef.current = setInterval(() => {\\n      setCount(prev => prev + 1);\\n    }, 1000);\\n    return () => clearInterval(intervalRef.current);\\n  }, []);\\n\\n  return <div>{count}</div>;\\n}"],[2547,"useContext — хук React, який дає компонентам змогу отримати доступ до даних із контексту, не передаючи пропсів через увесь ланцюжок. Він розв'язує проблему prop drilling, коли дані доводиться передавати через багато рівнів вкладених компонентів. Замість цього ви створюєте контекст за допомогою createContext, обгортаєте компоненти в Provider й використовуєте useContext, щоб прочитати значення.","Що таке useContext й для чого він потрібний\\nuseContext — хук у React, який дає компонентові змогу підписатися на контекст й отримати його поточне значення. Контекст — механізм, щоб передавати дані деревом компонентів без потреби передавати пропси на кожному рівні. Основна проблема, яку розв'язує useContext, — props drilling, коли дані передають через безліч проміжних компонентів, які самі їх не використовують. Це робить код громіздким і важким для підтримки.\\n\\nЯк він працює?\\nСпочатку створюють контекст за допомогою \`React.createContext()\`. Потім компонент-провайдер обгортає дочірні компоненти й передає значення через атрибут \`value\`. Будь-який компонент усередині провайдера може використати \`useContext(MyContext)\`, щоб отримати це значення. Коли значення контексту змінюється, усі підписані компоненти перерендерюються.\\n\\nПриклад коду\\n\\nКоли його застосовувати?\\nuseContext ідеальний для глобальних даних, які рідко змінюються, як-от теми, мови або аутентифікації. Однак для стану, який часто оновлюється (наприклад, даних форми), краще використовувати Redux або інші бібліотеки, оскільки контекст може спричиняти надлишкові повторні рендери. Висновок: useContext — простий, ефективний спосіб уникнути prop drilling, але його варто застосовувати для даних, які не змінюються надто часто.","import React, { createContext, useContext, useState } from 'react';\\n\\nconst ThemeContext = createContext('light');\\n\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Toolbar />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction Toolbar() {\\n  const { theme, setTheme } = useContext(ThemeContext);\\n  return (\\n    <div>\\n      <p>Current theme: {theme}</p>\\n      <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>\\n        Toggle\\n      </button>\\n    </div>\\n  );\\n}"],[2548,"React використовує поверхневе порівняння (===) для кожного елемента масиву залежностей. Якщо хоча б одне значення змінилося за посиланням, ефект виконується наново. Це дає React змогу ефективно визначати, коли побічні ефекти потрібно оновити, уникаючи зайвих викликів.","Як працює відстежування залежностей у useEffect\\nReact порівнює поточні значення залежностей із попередніми на кожному рендері. Для цього використовують строгу рівність (Object.is), яка аналогічна операторові ===, але враховує NaN. Якщо хоча б одна залежність змінилася, ефект запускають знову.\\n\\nПриклад із примітивами й об'єктами\\n\\nДля примітивів (чисел, рядків) порівняння відбувається за значенням. Для об'єктів і масивів — за посиланням. Тому зміна властивості об'єкта без створення нового об'єкта не спричинить виконання ефекту.\\n\\nПрактичне застосування\\nЦей механізм критичний задля оптимізації продуктивності. Якщо передати в залежності масив, який створюють наново на кожному рендері, ефект виконуватиметься щоразу. Щоб цього уникнути, використовують useMemo або useCallback, аби стабілізувати посилання.\\n\\nВисновок: розуміння поверхневого порівняння залежностей допомагає уникати нескінченних циклів і зайвих викликів ефектів, що особливо важливо у складних React-застосунках.","const [count, setCount] = useState(0);\\nconst [user, setUser] = useState({ name: 'Alice' });\\n\\nuseEffect(() => {\\n  console.log('The effect has run');\\n}, [count, user]);\\n\\n// On setCount(1) — the effect will run (count has changed)\\n// On setUser({ name: 'Alice' }) — the effect will run (a new reference to the object)"],[2549,"Виклик хука після умовного return порушує правила хуків React. React спирається на порядок, у якому викликають хуки між рендерами. Якщо хук викликають після return, його можуть пропустити на наступному рендері, що призведе до помилки «Rendered fewer hooks than expected».","Чому це проблема\\nReact використовує порядок, у якому викликають хуки, щоб зіставляти стан між рендерами. Якщо хук викликають після умовного return, то за різних умов рендера кількість і порядок хуків можуть змінитися. Це порушує внутрішні очікування React і спричиняє помилку.\\n\\nПриклад\\n\\nУ цьому прикладі, якщо \`flag\` дорівнює \`true\`, компонент повертає \`null\`, і хуки не викликають. На наступному рендері з \`flag = false\` React очікує, що хуки викличуть у тому самому порядку, але їхня кількість змінилася, що призводить до помилки.\\n\\nЯк це виправити\\nУсі хуки потрібно викликати на верхньому рівні компонента, перед будь-якими умовними return. Умовний return можна розмістити після всіх хуків, або можна використати умовний рендеринг усередині JSX.\\n\\nВисновок\\nДотримання правил хуків гарантує, що компоненти працюють стабільно й передбачувано. Завжди розміщуйте свої хуки перед будь-якими умовними інструкціями, щоб уникати помилок часу виконання.","function MyComponent({ flag }) {\\n  if (flag) {\\n    return null;\\n  }\\n  const [value, setValue] = useState(0); // An error!\\n  useEffect(() => {}, []);\\n  return <div>{value}</div>;\\n}\\n\\nfunction MyComponent({ flag }) {\\n  const [value, setValue] = useState(0);\\n  useEffect(() => {}, []);\\n  if (flag) {\\n    return null;\\n  }\\n  return <div>{value}</div>;\\n}"],[2550,"Мікрофронтенди можуть взаємодіяти через глобальний механізм подій (Event Bus), спільний стан (наприклад, стор Redux), параметри URL або через батьківський контейнер. Кожний мікрофронтенд підписується на події або читає спільні дані. Це дає їм змогу обмінюватися інформацією, не ламаючи ізоляції.","Способи взаємодії мікрофронтендів\\nМікрофронтенди — незалежні частини інтерфейсу, які розробляють і розгортають окремо, але які працюють разом в одному застосунку. Щоб їх координувати, потрібні механізми комунікації, які не ламають їхньої автономії.\\n\\nОсновні підходи\\n\\n- Event Bus: глобальний об'єкт, через який мікрофронтенди надсилають й отримують події. Наприклад, один мікрофронтенд публікує подію 'userLoggedIn', а інший підписується на неї й оновлює UI.\\n- Спільний стан: використання єдиного стора, як-от Redux або MobX, доступного всім мікрофронтендам. Зміни в одному модулі автоматично відображають в інших.\\n- URL і маршрутизація: передавання даних через параметри запиту або хеш URL. Наприклад, під час переходу між мікрофронтендами інформацію про поточного користувача передають в адресному рядку.\\n- Батьківський контейнер (shell): головний застосунок виступає посередником, передаючи пропси або викликаючи методи дочірніх модулів.\\n\\nПриклад з Event Bus\\n\\nВисновок\\nВибір способу залежить від складності застосунку: для простих сценаріїв підійде Event Bus, для складних — спільний стан. Головне — зберегти слабку зв'язаність, щоб мікрофронтенди залишалися незалежними.","// Micro-frontend A publishes an event\\nwindow.eventBus.publish('cartUpdated', { items: 3 });\\n\\n// Micro-frontend B subscribes\\nwindow.eventBus.subscribe('cartUpdated', (data) => {\\n  console.log('The cart has been updated:', data.items);\\n});"],[2551,"Context API придатний для простого передавання даних, які рідко змінюються — наприклад, теми або мови. Зовнішній менеджер стану (Redux, Zustand) потрібний за частих оновлень, складної логіки або великої кількості взаємопов'язаних частин стану. Context спричиняє повторний рендер усіх споживачів на будь-якій зміні, що знижує продуктивність. Зовнішні рішення оптимізують оновлення й надають інструменти задля зневадження.","Коли Context API достатній\\nContext API у React призначений, щоб передавати дані деревом компонентів без явного просвердлювання пропсів. Він добре працює для статичних або рідко змінюваних значень, як-от теми дизайну, локалі користувача або даних аутентифікації. У цих сценаріях оновлення відбуваються нечасто, і продуктивність не страждає.\\n\\nКоли потрібний зовнішній менеджер стану\\nЯкщо стан оновлюється часто (наприклад, на кожному натисканні клавіші у формі) або має складну логіку з безліччю залежностей, Context може спричинити надмірні повторні рендери. Зовнішні бібліотеки на кшталт Redux або Zustand використовують підписки на окремі частини стану, що мінімізує перемалювання. Вони також надають middleware, devtools і строгу архітектуру для великих застосунків.\\n\\nПриклад порівняння\\n\\nВисновок\\nВикористовуйте Context API для глобальних даних, які рідко змінюються. Для динамічного стану з частими оновленнями або складною бізнес-логікою обирайте зовнішній менеджер стану, щоб зберегти продуктивність і підтримуваність коду.","// Context - a re-render of all of the consumers on a change\\nconst ThemeContext = React.createContext('light');\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Header /> {/* it re-renders */}\\n      <Footer /> {/* it re-renders */}\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\n// Redux - only the subscribed component updates\\nconst selectTheme = (state) => state.theme;\\nfunction Header() {\\n  const theme = useSelector(selectTheme);\\n  return <div>{theme}</div>;\\n}"],[2552,"Так, React гарантує, що посилання на функцію-сетер, повернуту з useState, залишається стабільним між рендерами. Це означає, що функцію не перестворюють на кожному рендері, якщо компонент не демонтується й не монтується наново. Така стабільність дає змогу безпечно використовувати сетер у залежностях ефектів або передавати його в дочірні компоненти без зайвих повторних рендерів.","Стабільність посилання на сетер із useState\\nReact гарантує, що функція-сетер, повернута з хука useState, зберігає те саме посилання між рендерами компонента. Це означає, що на кожному виклику useState в тому самому компоненті повертають ту саму функцію для оновлення стану, якщо компонент не демонтували цілком і не змонтували наново.\\n\\nЧому це важливо\\nСтабільність посилання критична задля оптимізації продуктивності в React. Коли ви передаєте сетер як проп у дочірній компонент або використовуєте його в масиві залежностей хука useEffect, стабільне посилання запобігає зайвим повторним рендерам і повторним викликам ефектів. Якби посилання змінювалося на кожному рендері, це призвело б до нескінченних циклів або надлишкових обчислень.\\n\\nПриклад коду\\n\\nУ цьому прикладі setCount передають у залежності useEffect. Завдяки стабільності посилання ефект виконується лише тоді, коли компонент монтується, а не на кожній зміні count.\\n\\nВинятки й особливості\\n\\n- Стабільність гарантовано лише для сетера з useState. Інші хуки, наприклад useReducer, також повертають стабільний dispatch.\\n- Якщо компонент демонтується й монтується наново (наприклад, при зміні key), сетер буде новим.\\n- У строгому режимі React (StrictMode) рендери можуть викликати двічі, але посилання на сетер залишається стабільним у межах одного монтування.\\n\\nВисновок\\nСтабільність посилання на сетер із useState — фундаментальна особливість React, яка полегшує оптимізацію й запобігає багам, пов'язаним зі змінюваними посиланнями. Використовуйте цю властивість, щоб безпечно передавати сетер у дочірні компоненти або в залежності ефектів, не боячись зайвих повторних рендерів.","import React, { useState, useEffect } from 'react';\\n\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    // setCount is stable, so the effect will run only once\\n    console.log('Effect runs');\\n  }, [setCount]);\\n\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => setCount(c => c + 1)}>Increment</button>\\n    </div>\\n  );\\n}"],[2553,"Коли таймер оновлює стан у батьківському компоненті, React перемальовує батька й усі його дочірні компоненти, навіть якщо їхні пропси не змінилися. Це відбувається тому, що на кожному рендері створюють нові посилання на функції й об'єкти. Це можна виправити за допомогою React.memo задля мемоїзації дочірнього компонента, useCallback задля стабілізації функційних пропсів й useMemo задля стабілізації об'єктів.","Чому таймер спричиняє повторний рендер дочірніх компонентів\\nУ React щоразу, коли стан компонента оновлюється (наприклад, через setInterval), відбувається його повторний рендер. Під час повторного рендера батька всі дочірні компоненти також перемальовуються за замовчуванням, навіть якщо їхні пропси не змінилися. Це тому, що React не порівнює пропсів автоматично — він просто викликає render для всіх нащадків.\\n\\nПроблема погіршується, якщо в пропси передають функції або об'єкти, створені безпосередньо в JSX. На кожному рендері створюють нові посилання, що ламає навіть React.memo, якщо не використовують useCallback або useMemo.\\n\\nЯк це виправити\\nЄ три основні підходи:\\n- React.memo — він обгортає компонент, щоб той перемальовувався лише тоді, коли пропси змінюються (поверхневе порівняння).\\n- useCallback — він мемоїзує функцію, щоб її посилання залишалося стабільним між рендерами.\\n- useMemo — він мемоїзує результат обчислення або об'єкт.\\n\\nПриклад коду\\n\\nУ цьому прикладі Child обгорнутий у React.memo, а handleClick стабілізований через useCallback. Завдяки цьому Child не перемальовуватиметься на кожному тіку таймера.\\n\\nВисновок\\nВикористовуйте React.memo для компонентів, які часто отримують ті самі пропси, й useCallback/useMemo — щоб стабілізувати посилання. Це особливо важливо в роботі з таймерами, анімаціями або великими списками, щоб уникати зайвих повторних рендерів і зберегти продуктивність застосунку.","import React, { useState, useEffect, useCallback, memo } from 'react';\\n\\nconst Child = memo(({ onClick }) => {\\n  console.log('Child re-render');\\n  return <button onClick={onClick}>Click</button>;\\n});\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const timer = setInterval(() => setCount(c => c + 1), 1000);\\n    return () => clearInterval(timer);\\n  }, []);\\n\\n  // Without a useCallback — a new function every render\\n  const handleClick = useCallback(() => {\\n    console.log('Clicked');\\n  }, []);\\n\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <Child onClick={handleClick} />\\n    </div>\\n  );\\n}"],[2554,"Основні способи: React.memo задля мемоїзації компонента, useMemo задля мемоїзації значень, useCallback задля мемоїзації функцій зворотного виклику. Також можна винести важкі обчислення в useMemo й уникати передавання нових об'єктів і функцій на кожному рендері. Це допомагає React пропустити рендер, якщо пропси не змінилися.","Проблема зайвих повторних рендерів\\nУ React, коли стан батьківського компонента оновлюється, усі його дочірні компоненти за замовчуванням перерендерюються, навіть якщо їхні пропси не змінилися. Це може призвести до знижених показників продуктивності, особливо в глибоких деревах компонентів або за важких обчислень.\\n\\nОсновні способи запобігання\\n\\n- React.memo — він обгортає компонент і порівнює пропси поверхнево. Якщо пропси не змінилися, компонент не перерендерюється.\\n- useMemo — він мемоїзує результат обчислення, щоб об'єкти й масиви не перестворювали на кожному рендері.\\n- useCallback — він мемоїзує функцію, щоб посилання на неї залишалося стабільним між рендерами.\\n\\nПриклад коду\\n\\nУ цьому прикладі \`Child\` обгорнутий у \`React.memo\`, а пропси \`data\` й \`onClick\` стабільні завдяки \`useMemo\` й \`useCallback\`. Коли \`other\` змінюється, \`Child\` не перерендериться.\\n\\nДодаткові техніки\\n\\n- Підняття стану — перенесення спільного стану вище, щоб уникати зайвих рендерів.\\n- Використання ключів задля належного порівняння елементів списку.\\n- Розподіл компонентів на контейнери й презентаційні.\\n\\nВисновок: застосовуйте \`React.memo\`, \`useMemo\` й \`useCallback\` усвідомлено, лише коли профілювання показує проблему з продуктивністю. Надмірна мемоїзація може ускладнити код і не дати виграшу.","import React, { useState, useMemo, useCallback } from 'react';\\n\\nconst Child = React.memo(({ onClick, data }) => {\\n  console.log('Child render');\\n  return <button onClick={onClick}>{data.value}</button>;\\n});\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  const [other, setOther] = useState(0);\\n\\n  // A useMemo for a stable object\\n  const data = useMemo(() => ({ value: count }), [count]);\\n\\n  // A useCallback for a stable function\\n  const handleClick = useCallback(() => {\\n    setCount(c => c + 1);\\n  }, []);\\n\\n  return (\\n    <div>\\n      <Child onClick={handleClick} data={data} />\\n      <button onClick={() => setOther(o => o + 1)}>Other: {other}</button>\\n    </div>\\n  );\\n}"],[2555,"Лінтер (eslint-plugin-react-hooks) вимагає, щоб ви вказували в масиві залежностей кожну змінну й функцію, яку використовують усередині useEffect. Порожній масив означає, що ефект виконується лише один раз, на монтуванні. Якщо всередині ефекту використовують пропси, стан або інші значення, вони можуть бути застарілими (stale closure). Лінтер попереджає про це, щоб запобігти багам. Якщо порожній масив навмисний, потрібно або винести логіку в useRef, або додати коментар // eslint-disable-next-line.","Чому лінтер нарікає на порожній масив залежностей у useEffect?\\nЛінтер — а саме плагін \`eslint-plugin-react-hooks\` — аналізує код на відповідність правилам хуків React. Одне з ключових правил — \`react-hooks/exhaustive-deps\`. Воно вимагає, щоб кожна змінна, функція й проп, які використовують усередині \`useEffect\`, були перелічені в масиві залежностей. Якщо масив порожній, тоді як усередині ефекту є посилання на зовнішні значення, лінтер видає попередження або помилку.\\n\\nПроблема застарілих замикань\\nКоли ви передаєте порожній масив \`[]\`, ефект виконується лише один раз — коли компонент монтується. Усі змінні, захоплені в замиканні ефекту, зберігають свої значення станом на момент першого рендера. Якщо ці змінні зміняться пізніше (наприклад, через \`useState\` або пропси), ефект і далі використовуватиме старі значення. Це називають застарілим замиканням.\\n\\nПриклад проблеми\\n\\nУ цьому прикладі \`count\` усередині \`setInterval\` завжди дорівнюватиме 0, тому що ефект захопив його на першому рендері. Лінтер попереджає, що \`count\` має бути в залежностях.\\n\\nКоли порожній масив навмисний\\nІноді порожній масив справді потрібний — наприклад, задля підписки на зовнішнє джерело даних або задля аналітики, яка має спрацювати один раз. У таких випадках можна:\\n- Використати \`useRef\`, щоб зберігати актуальні значення, аби уникнути застарілих замикань.\\n- Додати коментар \`// eslint-disable-next-line react-hooks/exhaustive-deps\` над рядком із масивом, щоб вимкнути попередження.\\n\\nПравильний підхід\\n\\nУ цій версії ми використовуємо функційну форму \`setCount\`, яка не залежить від зовнішнього \`count\`. Лінтер бачить, що всередині ефекту немає посилань на змінні з рендера, тому порожній масив припустимий.\\n\\nВисновок\\nЛінтер нарікає на порожній масив залежностей, щоб запобігти багам із застарілими замиканнями. Якщо порожній масив навмисний, переконайтеся, що всередині ефекту не використовують зовнішніх змінних, або використайте \`useRef\`, щоб їх зберігати. Як останній засіб можна вимкнути правило для конкретного рядка, але це має бути усвідомлене рішення.","function Timer({ start }) {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const id = setInterval(() => {\\n      setCount(count + 1); // count is always 0, since it was captured on mounting\\n    }, 1000);\\n    return () => clearInterval(id);\\n  }, []); // the linter complains: count is not stated in the dependencies\\n\\n  return <div>{count}</div>;\\n}\\n\\nfunction Timer({ start }) {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const id = setInterval(() => {\\n      setCount(prev => prev + 1); // we use the functional form of setState\\n    }, 1000);\\n    return () => clearInterval(id);\\n  }, []); // now the linter does not complain, since there are no external dependencies\\n\\n  return <div>{count}</div>;\\n}"],[2556,"Не можна передати асинхронну функцію в useEffect безпосередньо, оскільки вона повертає проміс, а не функцію очищення. Замість цього потрібно оголосити асинхронну функцію всередині колбека й викликати її. Також важливо обробляти помилки через try/catch й використовувати функцію очищення, щоб скасовувати запити, коли компонент демонтується.","Проблема з async/await у useEffect\\nХук useEffect очікує, що задана йому функція або нічого не повертає, або повертає функцію очищення. Асинхронна функція завжди повертає проміс, тому передавання її безпосередньо спричинить помилку або небажану поведінку.\\n\\nПравильний підхід\\nСтворіть асинхронну функцію всередині колбека useEffect і викличте її одразу. Це дає змогу використовувати await й обробляти помилки.\\n\\nОбробка скасування запитів\\nЩоб запобігти втратам пам'яті, коли компонент демонтується, використовуйте прапорець або AbortController.\\n\\nВисновок\\nВикористовуйте внутрішню асинхронну функцію з try/catch і функцією очищення, щоб безпечно працювати з асинхронними операціями в useEffect. Це запобігає втратам пам'яті й належно обробляє помилки.","useEffect(() => {\\n  const fetchData = async () => {\\n    try {\\n      const response = await fetch('/api/data');\\n      const data = await response.json();\\n      setData(data);\\n    } catch (error) {\\n      console.error('A loading error:', error);\\n    }\\n  };\\n  fetchData();\\n}, []);\\n\\nuseEffect(() => {\\n  const controller = new AbortController();\\n  const fetchData = async () => {\\n    try {\\n      const response = await fetch('/api/data', { signal: controller.signal });\\n      const data = await response.json();\\n      setData(data);\\n    } catch (error) {\\n      if (error.name !== 'AbortError') {\\n        console.error(error);\\n      }\\n    }\\n  };\\n  fetchData();\\n  return () => controller.abort();\\n}, []);"],[2557,"useEffect приймає синхронну функцію, щоб React міг гарантувати, що ефект виконується після рендера, а функцію очищення викликають перед демонтуванням або повторним виконанням. Синхронність дає React змогу керувати порядком виконання й уникати гонок у даних. Якби функція була асинхронною, React не міг би належно обробити очищення й залежність від попереднього стану.","Чому useEffect приймає синхронну функцію?\\nuseEffect у React призначений, щоб виконувати побічні ефекти, як-от запити до API, підписки або маніпуляції з DOM. Перший аргумент має бути синхронною функцією, щоб React міг контролювати її виконання й гарантувати, що ефект запускають лише після того, як рендер завершився. Це також дає React змогу викликати функцію очищення, повернуту з ефекту, у правильний момент — перед тим як компонент демонтується, або перед тим як ефект виконається знову, коли залежності змінюються.\\n\\nЯк це працює на практиці?\\nКоли ви передаєте асинхронну функцію безпосередньо, React не може чекати на її завершення, що може призвести до проблем з очищенням і до втрат пам'яті. Замість цього варто оголосити асинхронну функцію всередині синхронного колбека й викликати її. Наприклад:\\n\\nТут зовнішня функція синхронна, що дає React змогу належно керувати її виконанням й очищенням.\\n\\nДе це застосовують?\\nЦей підхід використовують у кожному React-застосунку для роботи з побічними ефектами. Він гарантує, що компоненти поводяться передбачувано, й запобігає помилкам, пов'язаним з асинхронністю.\\n\\nВисновок: використовуйте синхронну функцію в useEffect, щоб React міг належно керувати життєвим циклом ефекту, а асинхронні операції виконуйте всередині неї — задля безпеки й чистоти коду.","useEffect(() => {\\n  const fetchData = async () => {\\n    const response = await fetch('/api/data');\\n    const data = await response.json();\\n    setData(data);\\n  };\\n  fetchData();\\n}, []);"],[2558,"Коли функцію оновлення стану викликають у дочірньому компоненті, React оновлює стан у батьківському компоненті. Це спричиняє повторний рендер батьківського компонента й усіх його дочірніх компонентів, включно з тим, який викликав функцію. React за замовчуванням перерендерює всі дочірні елементи, якщо не використовують оптимізацій на кшталт React.memo.","Як працює рендеринг, коли передають функцію оновлення стану\\nУ React станом керують на рівні компонента, де його оголошено за допомогою хука useState. Коли функцію оновлення стану (setState) передають у дочірній компонент через пропси й викликають там, вона змінює стан саме в батьківському компоненті. Це запускає процес повторного рендерингу, який починається з батька й поширюється вниз деревом компонентів.\\n\\nЯкі компоненти перерендеряться\\n\\n- Батьківський компонент, де стан оголошено, перерендерюється першим.\\n- Усі дочірні компоненти батька, включно з тим, який викликав функцію, також перерендерюються за замовчуванням.\\n- Якщо дочірні компоненти не використовують React.memo або інших оптимізацій, їх перерендерять незалежно від того, чи їхні пропси змінилися.\\n\\nПриклад коду\\n\\nНа натисканні кнопки в Child викликають onIncrement, який оновлює count у Parent. Це призводить до повторного рендера Parent й Child, як видно з повідомлення в консолі.\\n\\nВисновок\\nРозуміння цього механізму важливе задля оптимізації продуктивності React-застосунків. Якщо дочірній компонент не має перерендерюватися на кожній зміні стану батька, використовуйте React.memo або винесіть стан в окремий контекст.","function Parent() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <Child onIncrement={() => setCount(c => c + 1)} />\\n    </div>\\n  );\\n}\\n\\nfunction Child({ onIncrement }) {\\n  console.log('Child re-rendered');\\n  return <button onClick={onIncrement}>Increment</button>;\\n}"],[2559,"Redux використовує однонапрямлений потік даних. Коли користувач ініціює дію, викликають dispatch(action). Redux передає дію й поточний стан у редюсер, який повертає новий стан. Потім стор оновлюють, і підписані компоненти перемальовуються.","Як працює цикл Redux\\nRedux — передбачуваний контейнер стану для JavaScript-застосунків. Його ключова особливість — однонапрямлений потік даних, який робить зміни стану передбачуваними й легкими для відстежування.\\n\\nШлях дії від диспатчу до оновлення стану\\n\\n- Дія: користувач або код ініціює дію, створюючи об'єкт дії з полем type й необов'язковими даними (payload).\\n- dispatch(action): виклик store.dispatch(action) надсилає дію до стора.\\n- Редюсер: стор передає поточний стан і дію в кореневий редюсер. Редюсер — чиста функція, яка приймає попередній стан і дію й повертає новий стан, не мутуючи початкового.\\n- Оновлення стора: стор заміняє поточний стан новим, повернутим редюсером.\\n- Повідомлення підписників: стор викликає всіх підписаних слухачів (наприклад, через connect або useSelector у React), що призводить до перемальовування компонентів.\\n\\nПриклад коду\\n\\nВисновок\\nЦикл Redux забезпечує строгу послідовність: дія → dispatch → редюсер → новий стан → оновлення UI. Це полегшує зневадження, тестування й підтримку великих застосунків, де важливо контролювати зміни стану.","// An action creator\\nconst increment = () => ({ type: 'INCREMENT' });\\n\\n// A reducer\\nconst counterReducer = (state = { count: 0 }, action) => {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return { count: state.count + 1 };\\n    default:\\n      return state;\\n  }\\n};\\n\\n// The store\\nimport { createStore } from 'redux';\\nconst store = createStore(counterReducer);\\n\\n// The dispatch\\nstore.dispatch(increment());\\nconsole.log(store.getState()); // { count: 1 }"],[2560,"createListenerMiddleware — вбудований у Redux Toolkit middleware, який дає змогу запускати побічні ефекти у відповідь на дії Redux. Він слухає певні дії й виконує колбеки, що зручно задля логування, навігації або викликів API. На відміну від createAsyncThunk, він не створює нових дій, а просто реагує на наявні.","Що таке createListenerMiddleware?\\ncreateListenerMiddleware — middleware з Redux Toolkit, який дає змогу виконувати довільний код (побічні ефекти) у відповідь на диспатч певних дій. Він схожий на саги або epics, але його простіше й легше використовувати, оскільки він не потребує додаткових бібліотек.\\n\\nЯк він працює?\\nMiddleware перехоплює кожний диспатч і перевіряє, чи він відповідає заданим умовам (наприклад, типу дії). Якщо умову виконано, запускають колбек, який може виконувати асинхронні операції, диспатчити інші дії або взаємодіяти зі станом.\\n\\nПриклад використання\\n\\nДе його застосовують?\\n\\n- Логування дій користувача\\n- Навігація після успішної дії (наприклад, перенаправлення після входу)\\n- Синхронізація з localStorage або IndexedDB\\n- Виклик API без створення thunk'а\\n\\nВисновок\\ncreateListenerMiddleware — зручний інструмент, щоб обробляти побічні ефекти в Redux, коли повна потужність саг або thunk'ів не потрібна. Він особливо корисний для простих сценаріїв, де потрібно реагувати на дії, не змінюючи логіки редюсерів.","import { createListenerMiddleware, isAnyOf } from '@reduxjs/toolkit';\\nimport { addTodo, removeTodo } from './todosSlice';\\n\\nconst listenerMiddleware = createListenerMiddleware();\\n\\nlistenerMiddleware.startListening({\\n  matcher: isAnyOf(addTodo, removeTodo),\\n  effect: async (action, listenerApi) => {\\n    console.log('A todo has been changed:', action);\\n    // Other actions can be dispatched\\n    listenerApi.dispatch({ type: 'log/action', payload: action.type });\\n  },\\n});\\n\\nexport default listenerMiddleware;"],[2561,"React.memo — компонент вищого порядку, який мемоїзує результат рендерингу компонента, запобігаючи його повторному рендеру за незмінних пропсів. useMemo — хук, який мемоїзує результат обчислення функції, запобігаючи дорогим обчисленням на кожному рендері. React.memo працює на рівні компонента, useMemo — на рівні значення.","Основна різниця\\nReact.memo й useMemo служать, щоб оптимізувати продуктивність, але вони працюють на різних рівнях. React.memo — компонент вищого порядку (HOC), який обгортає компонент і запобігає його повторному рендеру, якщо пропси не змінилися (поверхневе порівняння). useMemo — хук, який мемоїзує результат виконання функції й перераховує його лише тоді, коли залежності змінюються.\\n\\nПриклади використання\\nReact.memo застосовують до компонента:\\n\\nuseMemo використовують усередині функційного компонента:\\n\\nКоли що застосовувати\\n\\n- React.memo — коли потрібно уникнути повторного рендера цілого компонента за незмінних пропсів.\\n- useMemo — коли потрібно уникнути дорогих обчислень або зберегти посилальну стабільність об'єкта чи масиву між рендерами.\\n\\nВисновок: React.memo оптимізує рендер компонента, а useMemo — обчислення. Використовуйте їх разом задля максимальної продуктивності, але не зловживайте ними, оскільки мемоїзація також потребує ресурсів.","const MyComponent = React.memo(({ data }) => {\\n  console.log('Rendered');\\n  return <div>{data}</div>;\\n});\\n\\nconst sortedList = useMemo(() => {\\n  return items.sort((a, b) => a - b);\\n}, [items]);"],[2562,"Функційний компонент перерендерюється, коли викликають функцію-сетер, повернуту useState. React порівнює нове значення з поточним за допомогою Object.is. Якщо значення різні, компонент і його дочірні елементи перерендерюються. Якщо вони однакові, повторного рендера не відбувається.","Коли відбувається повторний рендер при використанні useState\\nУ React функційний компонент перерендерюється щоразу, коли викликають функцію-сетер, отриману з хука \`useState\`. Це основний механізм оновлення UI у відповідь на зміни стану.\\n\\nМеханізм порівняння\\nReact використовує строге порівняння \`Object.is\`, щоб визначити, чи значення стану змінилося. Якщо нове значення відрізняється від попереднього, компонент перерендерюється. Якщо значення однакові (наприклад, коли передають той самий об'єкт або примітив), повторного рендера не відбувається.\\n\\nПриклад коду\\n\\nВажливі нюанси\\n\\n- Коли в сетер передають функцію (наприклад, \`setCount(prev => prev + 1)\`), React гарантує, що буде використане актуальне значення стану.\\n- Якщо стан — об'єкт або масив, потрібно створити нове посилання, щоб повторний рендер відбувся. Мутація наявного об'єкта повторного рендера не спричинить.\\n- Повторний рендер компонента також може спричинити зміна пропсів або контексту.\\n\\nВисновок: використовуйте useState для локального стану компонента. Пам'ятайте, що повторний рендер відбувається лише тоді, коли значення змінюється, а не на кожному виклику сетера. Для складного стану використовуйте функційну форму оновлення.","import React, { useState } from 'react';\\n\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n\\n  const handleClick = () => {\\n    setCount(count + 1); // a re-render will happen\\n  };\\n\\n  const handleSameValue = () => {\\n    setCount(count); // a re-render will NOT happen, since the value has not changed\\n  };\\n\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={handleClick}>Increment</button>\\n      <button onClick={handleSameValue}>Set same</button>\\n    </div>\\n  );\\n}"],[2563,"useTransition — хук React, який дає змогу позначити оновлення стану як низькопріоритетне. Він допомагає уникати блокування інтерфейсу під час виконання важких операцій, як-от рендерингу великих списків. Хук повертає кортеж: isPending (прапорець очікування) і startTransition (функцію, щоб запустити перехід). Це покращує користувацький досвід, роблячи застосунок відгукливішим.","Що таке useTransition?\\nuseTransition — хук із React 18, який є частиною Concurrent Mode. Він дає розробникові змогу вказати, що певне оновлення стану менш пріоритетне й може бути відкладене, щоб не блокувати нагальніших взаємодій користувача, як-от набирання тексту або кліків.\\n\\nЯк він працює?\\nКоли ви викликаєте startTransition, React позначає всі оновлення стану всередині нього як перехідні. React може перервати ці оновлення, якщо з'явиться вищопріоритетна задача (наприклад, оновлення з поля введення). Це запобігає зависанню інтерфейсу.\\n\\nПриклад використання\\n\\nДе його застосовувати?\\n\\n- Пошук із фільтрацією великих даних\\n- Перемикання між вкладками з важким вмістом\\n- Анімації й переходи між сторінками\\n\\nВисновок: useTransition корисний, коли потрібно зберегти відгукливість інтерфейсу, поки виконуються ресурсомісткі операції, особливо в застосунках із частими оновленнями стану.","import { useState, useTransition } from 'react';\\n\\nfunction SearchComponent() {\\n  const [query, setQuery] = useState('');\\n  const [results, setResults] = useState([]);\\n  const [isPending, startTransition] = useTransition();\\n\\n  const handleChange = (e) => {\\n    setQuery(e.target.value); // the urgent update\\n    startTransition(() => {\\n      // the low-priority update\\n      setResults(filterData(e.target.value));\\n    });\\n  };\\n\\n  return (\\n    <div>\\n      <input value={query} onChange={handleChange} />\\n      {isPending && <span>Loading...</span>}\\n      <ul>{results.map(item => <li key={item.id}>{item.name}</li>)}</ul>\\n    </div>\\n  );\\n}"],[2564,"На кожному рендері створюють новий об'єкт-масив із новим посиланням у пам'яті. Якщо масив передають як проп у дочірній компонент, React.memo не зможе запобігти повторному рендеру, оскільки порівняння за посиланням покаже зміну. Це призводить до зайвих повторних рендерів і знижених показників продуктивності.","Проблема створення нового масиву на кожному рендері\\nУ React на кожному рендері компонента всі змінні, оголошені всередині нього, створюють наново. Це стосується й масивів й об'єктів. Навіть якщо вміст масиву не змінився, створюють новий об'єкт із новим посиланням у пам'яті.\\n\\nВплив на дочірні компоненти\\nЯкщо такий масив передають як проп у дочірній компонент, обгорнутий у React.memo, мемоїзація не спрацює. React.memo порівнює пропси поверхнево — тобто за посиланням. Нове посилання буде прийняте за зміну, й дочірній компонент перерендериться, навіть якщо дані не змінилися.\\n\\nПриклад коду\\n\\nКоли це критично\\nПроблема стає помітною за великої кількості дочірніх компонентів, за складних обчислень усередині них або за частих повторних рендерів батька. У простих застосунках це може бути непомітним, але у великих проєктах зайві повторні рендери можуть істотно сповільнити роботу.\\n\\nВисновок\\nВикористовуйте useMemo задля стабільних масивів й об'єктів, які передають як пропси в мемоїзовані компоненти. Це запобігає зайвим повторним рендерам і покращує продуктивність застосунку.","// Bad: a new array on every render\\nfunction Parent() {\\n  const items = ['a', 'b', 'c']; // a new reference every time\\n  return <Child list={items} />;\\n}\\n\\n// Good: the memoization of the array\\nfunction Parent() {\\n  const items = useMemo(() => ['a', 'b', 'c'], []);\\n  return <Child list={items} />;\\n}"],[2565,"useMemo кешує результат обчислення між рендерами. Якщо залежності не змінилися, повертають збережене значення. Це запобігає перестворенню масивів й об'єктів на кожному рендері, що оптимізує продуктивність.","Що таке useMemo й для чого він потрібний\\nuseMemo — хук React, який дає змогу мемоїзувати (закешувати) результат обчислення між рендерами компонента. Коли компонент перемальовується, усі змінні й функції всередині нього створюють наново. Для масивів й об'єктів це означає, що новий екземпляр створюють щоразу, навіть якщо вміст не змінився. Це може призвести до зайвих повторних рендерів дочірніх компонентів, які залежать від цих даних.\\n\\nЯк він працює?\\nuseMemo приймає два аргументи: функцію, яка повертає значення, й масив залежностей. React запам'ятовує результат функції й повертає його на повторних рендерах, якщо залежності залишилися тими самими. Якщо залежності змінилися, функція виконується наново.\\n\\nПриклад коду\\n\\nКоли застосовувати useMemo?\\nВикористовуйте useMemo для дорогих обчислень (наприклад, фільтрації великих масивів, складних математичних операцій) або щоб стабілізувати посилання на об'єкти й масиви, які передають у дочірні компоненти, обгорнуті в React.memo. Однак не варто мемоїзувати все без розбору — це додає накладних витрат на порівняння залежностей. Застосовуйте його лише тоді, коли є реальна проблема з продуктивністю.\\n\\nВисновок: useMemo допомагає уникати зайвих обчислень і повторних рендерів, кешуючи результат, доки залежності не зміняться. Це корисно, щоб оптимізувати React-застосунки, особливо в роботі з великими даними або з компонентами, які часто перемальовуються.","import React, { useMemo } from 'react';\\n\\nfunction MyComponent({ items, filter }) {\\n  // Without a useMemo: every render creates a new array\\n  // const filteredItems = items.filter(item => item.includes(filter));\\n\\n  // With a useMemo: the array is recreated only when items or filter changes\\n  const filteredItems = useMemo(() => {\\n    return items.filter(item => item.includes(filter));\\n  }, [items, filter]);\\n\\n  return (\\n    <ul>\\n      {filteredItems.map(item => <li key={item}>{item}</li>)}\\n    </ul>\\n  );\\n}"],[2566,"React.memo не гарантує відсутності зайвих повторних рендерів, коли передають складні об'єкти або масиви. Він використовує поверхневе порівняння пропсів — тобто порівнює посилання, а не вміст. Якщо новий об'єкт або масив створюють на кожному рендері батька, посилання змінюється, й React.memo вважає пропси зміненими, спричиняючи повторний рендер дочірнього компонента.","Як працює React.memo\\nReact.memo — компонент вищого порядку, який запам'ятовує результат рендерингу й пропускає повторний рендер, якщо пропси не змінилися. За замовчуванням він використовує поверхневе порівняння — він порівнює посилання на об'єкти, а не їхній вміст.\\n\\nПроблема з об'єктами й масивами\\nЯкщо в пропси передають складні об'єкти або масиви, які створюють наново на кожному рендері батька (літерали об'єктів або масивів, результати викликів функцій), то посилання на них буде новим. React.memo побачить, що посилання змінилося, й виконає повторний рендер, навіть якщо вміст об'єкта або масиву залишився тим самим.\\n\\nУ цьому прикладі Child перерендерюватиметься на кожній зміні count, незважаючи на React.memo, тому що об'єкт data створюють наново.\\n\\nЯк розв'язати проблему\\nЩоб уникнути зайвих повторних рендерів, потрібно стабілізувати посилання на об'єкти й масиви. Для цього можна використати:\\n- \`useMemo\` — щоб мемоїзувати обчислені значення\\n- \`useCallback\` — щоб мемоїзувати функції\\n- Винесення констант поза компонент\\n\\nВисновок\\nReact.memo ефективний лише зі стабільними посиланнями в пропсах. Для складних об'єктів і масивів потрібно використовувати мемоїзацію за допомогою useMemo або виносити незмінні дані поза компонент. Інакше React.memo не дасть очікуваного ефекту й може навіть погіршити продуктивність через накладні витрати на порівняння.","// An example: a new object is created every time\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  const data = { name: 'John' }; // a new reference on every render\\n  return <Child data={data} />;\\n}\\n\\nconst Child = React.memo(({ data }) => {\\n  console.log('Child re-rendered');\\n  return <div>{data.name}</div>;\\n});\\n\\n// The use of a useMemo for stabilizing the reference\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  const data = useMemo(() => ({ name: 'John' }), []);\\n  return <Child data={data} />;\\n}"],[2567,"Виклик setState усередині компонента позначає його як такий, що потребує оновлення. Потім React за замовчуванням перерендерює цей компонент й усі його дочірні компоненти, навіть якщо їхні пропси не змінилися. Це може призвести до непотрібних повторних рендерів, тому задля оптимізації використовують React.memo або shouldComponentUpdate.","Як setState впливає на дочірні компоненти\\nКоли ви викликаєте setState у батьківському компоненті, React позначає цей компонент як «брудний» і планує його повторний рендер. Під час наступного рендера React створює нове дерево віртуального DOM для батька й усіх його дочірніх елементів. За замовчуванням дочірні компоненти також перерендерюються, навіть якщо їхні пропси залишилися тими самими.\\n\\nЧому це відбувається\\nReact не порівнює пропсів автоматично — він просто викликає функцію рендера для кожного дочірнього компонента. Це гарантує, що UI завжди синхронний зі станом, але може бути надлишковим. Наприклад:\\n\\nНа кожному кліку Child виводитиме повідомлення, хоча його вміст не змінюється.\\n\\nЯк це оптимізувати\\n\\n- React.memo — він обгортає компонент і запобігає повторному рендеру, якщо пропси не змінилися (поверхневе порівняння).\\n- useMemo/useCallback — вони мемоїзують значення й функції, щоб пропси залишалися стабільними.\\n- shouldComponentUpdate (у класових компонентах) — він дає змогу керувати повторним рендером вручну.\\n\\nВисновок\\nРозуміння цього механізму важливе, щоб писати продуктивні React-застосунки. Використовуйте React.memo для компонентів, які часто перерендерюються без зміни своїх пропсів, й уникайте зайвого передавання нових об'єктів або функцій на кожному рендері.","function Parent() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(count + 1)}>Click</button>\\n      <Child />\\n    </div>\\n  );\\n}\\n\\nfunction Child() {\\n  console.log('Child re-rendered');\\n  return <div>Static content</div>;\\n}"],[2568,"Якщо дочірні компоненти не обгорнуто в React.memo, то на кожному повторному рендері батька вони перерендеряться, незалежно від того, чи їхні пропси змінилися. React за замовчуванням рекурсивно перерендерює всі дочірні компоненти. React.memo запобігає цьому, виконуючи поверхневе порівняння пропсів.","Поведінка дочірніх компонентів при повторному рендері батька\\nУ React, коли батьківський компонент перерендерюється (наприклад, через зміну стану або пропсів), усі його дочірні компоненти також перерендерюються за замовчуванням. Це відбувається рекурсивно: кожний дочірній компонент у свою чергу перерендерює власних нащадків. Така поведінка гарантує, що користувацький інтерфейс завжди синхронний із поточним станом застосунку.\\n\\nПриклад без React.memo\\n\\nНа кожному кліку по кнопці обидва дочірні компоненти перерендеряться, навіть якщо їхні пропси не змінилися. Це видно з виведення в консоль.\\n\\nЯк React.memo розв'язує проблему\\nReact.memo — компонент вищого порядку, який запам'ятовує результат рендерингу. Він виконує поверхневе порівняння пропсів й, якщо пропси не змінилися, використовує збережений результат, запобігаючи непотрібному повторному рендеру.\\n\\nТепер, коли стан батька змінюється, дочірні компоненти не перерендеряться, якщо їхні пропси залишилися тими самими.\\n\\nВисновок\\nВикористовуйте React.memo, щоб оптимізувати продуктивність у випадках, де дочірні компоненти часто перерендерюються через зміни в батькові, тоді як їхні пропси змінюються рідко. Однак не варто обгортати кожний компонент у React.memo без потреби, оскільки це додає накладних витрат на порівняння пропсів.","import React, { useState } from 'react';\\n\\nconst Child = ({ name }) => {\\n  console.log('Child rendered:', name);\\n  return <div>{name}</div>;\\n};\\n\\nconst Parent = () => {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(c => c + 1)}>Click</button>\\n      <Child name=\\"Alice\\" />\\n      <Child name=\\"Bob\\" />\\n    </div>\\n  );\\n};\\n\\nconst Child = React.memo(({ name }) => {\\n  console.log('Child rendered:', name);\\n  return <div>{name}</div>;\\n});"],[2569,"На першому монтуванні React спочатку рендерить батьківський компонент, потім дітей. Коли рендеринг усіх компонентів у дереві завершився, React синхронно запускає ефекти (useEffect) у порядку від дітей до батьків. Це гарантує, що DOM уже оновлено перед тим, як побічні ефекти виконуються.","Порядок рендера вкладених React-компонентів при першому монтуванні\\nReact використовує рекурсивний підхід, щоб рендерити дерево компонентів. На першому монтуванні процес поділено на дві фази: фазу рендера й фазу commit.\\n\\nФаза рендера\\nReact починає з кореневого компонента й викликає його функцію рендера. Якщо компонент повертає дочірні компоненти, React рекурсивно рендерить їх перед тим, як завершити рендер батька. Отже, порядок викликів функцій рендера йде згори вниз: спочатку батько, потім його діти, потім онуки й так далі.\\n\\nФаза commit й ефекти\\nКоли рендеринг усіх компонентів завершився, React оновлює реальний DOM. Потім запускають ефекти (useEffect). Ефекти виконуються в порядку від дочірніх компонентів до батьків (знизу вгору). Це тому, що ефекти дітей можуть залежати від DOM, створеного батьком.\\n\\nПрактичне застосування\\nЦей порядок важливий задля належної роботи з побічними ефектами, як-от підписками на події або запитами даних. Наприклад, якщо дочірній компонент використовує дані, отримані в ефекті батька, це може призвести до помилок, оскільки ефект батька виконується пізніше.\\n\\nВисновок: розуміння порядку рендера й ефектів допомагає уникати багів у роботі з вкладеними компонентами й із залежностями в useEffect. Завжди враховуйте, що рендеринг іде згори вниз, а ефекти — знизу вгору.","function Parent() {\\n  console.log('Parent render');\\n  return <Child />;\\n}\\n\\nfunction Child() {\\n  console.log('Child render');\\n  return <div>Hello</div>;\\n}\\n\\n// The output: Parent render, Child render\\n\\nfunction Parent() {\\n  useEffect(() => console.log('Parent effect'));\\n  return <Child />;\\n}\\n\\nfunction Child() {\\n  useEffect(() => console.log('Child effect'));\\n  return <div>Hello</div>;\\n}\\n\\n// The output: Child effect, Parent effect"],[2570,"useEffect може імітувати componentDidMount із порожнім масивом залежностей, componentDidUpdate — коли вказані залежності, й componentWillUnmount — через функцію очищення. Для componentDidMount передайте порожній масив; для componentDidUpdate — масив зі змінними, які відстежують; для componentWillUnmount поверніть функцію з useEffect.","Відповідність useEffect методам життєвого циклу\\nХук useEffect у React об'єднує функціональність кількох методів життєвого циклу класових компонентів. Він дає змогу виконувати побічні ефекти після рендерингу компонента й керувати їхнім очищенням.\\n\\ncomponentDidMount\\nЩоб відтворити поведінку componentDidMount (виконати код один раз після того, як компонент змонтувався), використовують useEffect із порожнім масивом залежностей:\\n\\ncomponentDidUpdate\\nЩоб імітувати componentDidUpdate (виконати код, коли певні пропси або стан змінюються), укажіть залежності в масиві:\\n\\nЯкщо ефект має виконуватися на будь-якому оновленні, пропустіть масив залежностей (але це може призвести до нескінченного циклу).\\n\\ncomponentWillUnmount\\nЩоб очистити ресурси, коли компонент демонтується (аналог componentWillUnmount), поверніть функцію з useEffect:\\n\\nФункція очищення також виконується перед тим, як ефект запускають знову, якщо залежності змінилися.\\n\\nВисновок\\nuseEffect — універсальний інструмент задля керування побічними ефектами у функційних React-компонентах. Він заміняє componentDidMount, componentDidUpdate і componentWillUnmount, роблячи код лаконічнішим і передбачуванішим. Використовуйте його для роботи з API, підписками, таймерами й іншими асинхронними операціями.","useEffect(() => {\\n  // The code runs once after the mounting\\n  fetchData();\\n}, []);\\n\\nuseEffect(() => {\\n  // The code runs on every change of userId\\n  fetchUserData(userId);\\n}, [userId]);\\n\\nuseEffect(() => {\\n  const subscription = subscribeToUpdates();\\n  return () => {\\n    // The clean-up on the unmounting\\n    subscription.unsubscribe();\\n  };\\n}, []);"],[2571,"Методи життєвого циклу в класових компонентах React — спеціальні функції, які викликають автоматично на різних етапах існування компонента: монтуванні, оновленні й демонтуванні. Основні методи: constructor(), render(), componentDidMount(), componentDidUpdate(), componentWillUnmount(). Вони дають змогу виконувати ініціалізацію, оновлення даних й очищення ресурсів.","Що таке методи життєвого циклу?\\nУ класових компонентах React життєвий цикл компонента поділено на три фази: монтування (створення й вставлення в DOM), оновлення (коли пропси або стан змінюються) й демонтування (видалення з DOM). Для кожної фази є спеціальні методи, які React викликає автоматично. Вони дають розробникові контроль над поведінкою компонента в ключові моменти.\\n\\nОсновні методи й їхнє застосування\\n\\n- constructor(props) — його викликають, коли компонент створюють. Його використовують, щоб ініціалізувати стан й прив'язати методи. У ньому не можна викликати setState().\\n- render() — обов'язковий метод; він повертає JSX. Він має бути чистою функцією без побічних ефектів.\\n- componentDidMount() — його викликають одразу після того, як компонент змонтувався в DOM. Він ідеальний для запитів до API, для підписок й для налаштування таймерів.\\n- componentDidUpdate(prevProps, prevState) — його викликають після того, як компонент оновився. Він дає змогу реагувати на зміни пропсів або стану — наприклад, задля повторного запиту даних.\\n- componentWillUnmount() — його викликають перед тим, як компонент видаляють із DOM. Його використовують задля очищення: відписки від подій, зупинки таймерів, скасування запитів.\\n\\nПриклад коду\\n\\nВисновок\\nМетоди життєвого циклу в класових компонентах React забезпечують структурований спосіб керувати побічними ефектами й станом. Вони особливо корисні у складних компонентах, де потрібний точний контроль над ініціалізацією, оновленням й очищенням ресурсів. Однак у сучасній розробці з функційними компонентами й хуками (useEffect) ці методи використовують рідше, але розуміння того, як вони працюють, залишається важливим, щоб підтримувати застарілий код й задля глибокого розуміння React.","class Timer extends React.Component {\\n  constructor(props) {\\n    super(props);\\n    this.state = { seconds: 0 };\\n  }\\n\\n  componentDidMount() {\\n    this.interval = setInterval(() => {\\n      this.setState({ seconds: this.state.seconds + 1 });\\n    }, 1000);\\n  }\\n\\n  componentDidUpdate(prevProps, prevState) {\\n    if (this.state.seconds === 10) {\\n      console.log('10 seconds reached');\\n    }\\n  }\\n\\n  componentWillUnmount() {\\n    clearInterval(this.interval);\\n  }\\n\\n  render() {\\n    return <div>Seconds: {this.state.seconds}</div>;\\n  }\\n}"],[2572,"Це методи життєвого циклу класових компонентів React. componentDidMount викликають після того, як компонент змонтувався, й використовують для запитів до API й для підписок. componentDidUpdate викликають після того, як пропси або стан оновилися, й він дає змогу реагувати на зміни. componentWillUnmount викликають перед тим, як компонент видаляють, й використовують, щоб очищати підписки й таймери. componentDidCatch перехоплює помилки в дочірніх компонентах і дає змогу відобразити резервний UI.","Методи життєвого циклу класових компонентів React\\nУ класових компонентах React є спеціальні методи, які викликають автоматично на різних етапах життя компонента: монтуванні, оновленні, демонтуванні й обробці помилок. Ці методи дають розробникові змогу виконувати побічні ефекти, як-от запити до сервера, підписки або очищення ресурсів.\\n\\ncomponentDidMount\\nЙого викликають одразу після того, як компонент вставили в DOM. Це ідеальне місце, щоб виконувати запити до API, налаштовувати підписки або ініціалізувати сторонні бібліотеки.\\n\\ncomponentDidUpdate\\nЙого викликають після кожного оновлення компонента (зміни пропсів або стану). Він дає змогу реагувати на зміни — наприклад, оновлювати дані, коли ID змінюється.\\n\\ncomponentWillUnmount\\nЙого викликають перед тим, як компонент видаляють із DOM. Його використовують, щоб скасовувати підписки, очищати таймери або видаляти обробники подій, аби уникати втрат пам'яті.\\n\\ncomponentDidCatch\\nВін перехоплює помилки, які виникли в дочірніх компонентах (у рендері, методах життєвого циклу або в конструкторах). Він дає змогу відобразити резервний UI й залогувати помилку.\\n\\nВисновок: ці методи потрібні, щоб керувати побічними ефектами й ресурсами в класових компонентах. З появою хуків у функційних компонентах їх замінили useEffect й Error Boundary, але розуміння методів життєвого циклу важливе для роботи із застарілим кодом й задля глибокого розуміння React.","class MyComponent extends React.Component {\\n  componentDidMount() {\\n    fetch('/api/data')\\n      .then(res => res.json())\\n      .then(data => this.setState({ data }));\\n  }\\n  render() { return <div>{this.state?.data}</div>; }\\n}\\n\\ncomponentDidUpdate(prevProps) {\\n  if (this.props.userId !== prevProps.userId) {\\n    this.fetchUser(this.props.userId);\\n  }\\n}\\n\\ncomponentWillUnmount() {\\n  clearInterval(this.timer);\\n  this.subscription.unsubscribe();\\n}\\n\\ncomponentDidCatch(error, info) {\\n  console.error('Error caught:', error, info);\\n  this.setState({ hasError: true });\\n}\\nrender() {\\n  if (this.state.hasError) return <h1>Something went wrong.</h1>;\\n  return this.props.children;\\n}"],[2573,"useEffect дає змогу виконувати побічні ефекти у функційних компонентах. Він заміняє методи життєвого циклу componentDidMount, componentDidUpdate і componentWillUnmount. Ви передаєте функцію й масив залежностей; ефект запускають після рендера й коли залежності змінюються. Повернуту функцію використовують задля очищення (наприклад, відписки від подій).","Що таке useEffect і для чого він потрібний\\nuseEffect — хук у React, який дає змогу виконувати побічні ефекти у функційних компонентах. Побічні ефекти — операції, які впливають на зовнішній світ або залежать від нього: наприклад, запити до API, підписки на події, робота з таймерами або зміна DOM вручну. У класових компонентах для цього використовували методи життєвого циклу, як-от componentDidMount, componentDidUpdate і componentWillUnmount. useEffect об'єднує їх в одному API, роблячи код чистішим і передбачуванішим.\\n\\nЯк працює useEffect?\\nХук приймає два аргументи: функцію-ефект й необов'язковий масив залежностей. Функція-ефект виконується після кожного рендера компонента, якщо вказані залежності змінилися. Якщо масив залежностей порожній, ефект виконується лише один раз, після монтування. Якщо залежності не вказано, ефект запускають після кожного рендера. Функція може повернути функцію очищення, яку викликають перед тим, як компонент демонтується, або перед тим, як ефект запускають знову.\\n\\nПриклади використання\\nПодивімося на простий приклад: завантаження даних із сервера, коли компонент монтується.\\n\\nУ цьому прикладі useEffect виконує запит до API, коли той монтується, й щоразу, коли userId змінюється. Якби ми не вказали залежності, запит виконували б на кожному рендері, що неефективно.\\n\\nІнший приклад — підписка на подію й її очищення:\\n\\nФункція очищення видаляє обробник події, запобігаючи втратам пам'яті.\\n\\nВисновок\\nuseEffect — потужний інструмент задля керування побічними ефектами у функційних React-компонентах. Він робить код декларативнішим і зменшує дублювання, заміняючи кілька методів життєвого циклу одним хуком. Використовуйте його для кожної операції, не пов'язаної безпосередньо з рендерингом, й завжди вказуйте правильні залежності, щоб уникати неочікуваної поведінки.","import React, { useState, useEffect } from 'react';\\n\\nfunction UserProfile({ userId }) {\\n  const [user, setUser] = useState(null);\\n\\n  useEffect(() => {\\n    fetch(\`/api/users/\${userId}\`)\\n      .then(response => response.json())\\n      .then(data => setUser(data));\\n  }, [userId]); // the effect is started when userId changes\\n\\n  return <div>{user ? user.name : 'Loading...'}</div>;\\n}\\n\\nimport React, { useEffect } from 'react';\\n\\nfunction WindowSizeTracker() {\\n  useEffect(() => {\\n    const handleResize = () => console.log(window.innerWidth);\\n    window.addEventListener('resize', handleResize);\\n\\n    return () => {\\n      window.removeEventListener('resize', handleResize);\\n    };\\n  }, []); // an empty array — the effect only on the mounting\\n\\n  return <div>Resize the window</div>;\\n}"],[2574,"Рекурсивні компоненти викликають самі себе, щоб обробляти вкладені дані. Компонент приймає масив елементів й для кожного елемента рендерить його вміст й потім рекурсивно викликає себе для дочірніх елементів. Важливо передавати кожному елементові унікальний ключ і належно обробляти базовий випадок, коли дочірніх елементів немає.","Що таке рекурсивні компоненти?\\nРекурсивні компоненти — компоненти, які викликають самі себе, щоб обробляти вкладені структури даних. Це особливо корисно в роботі з деревами, багаторівневими меню, коментарями з відповідями або файловими системами.\\n\\nЯк це працює?\\nКомпонент приймає масив даних й для кожного елемента рендерить його вміст. Якщо елемент має дочірні елементи, компонент рекурсивно викликає себе, щоб їх відобразити. Базовий випадок — відсутність дочірніх елементів, що запобігає нескінченній рекурсії.\\n\\nПриклад коду\\n\\nВажливі моменти\\n\\n- Завжди передавайте кожному елементові унікальний ключ задля ефективного оновлення DOM.\\n- Перевіряйте наявність дочірніх елементів перед рекурсивним викликом, щоб уникати помилок.\\n- Уникайте глибокої вкладеності, оскільки вона може призвести до проблем із продуктивністю.\\n\\nВисновок\\nРекурсивні компоненти — потужний інструмент для роботи з вкладеними даними. Їх варто застосовувати, коли структура даних має невизначену глибину — наприклад, у деревоподібних меню, файлових системах або багаторівневих коментарях.","function TreeNode({ node }) {\\n  return (\\n    <li>\\n      {node.name}\\n      {node.children && (\\n        <ul>\\n          {node.children.map(child => (\\n            <TreeNode key={child.id} node={child} />\\n          ))}\\n        </ul>\\n      )}\\n    </li>\\n  );\\n}\\n\\nfunction Tree({ data }) {\\n  return (\\n    <ul>\\n      {data.map(node => (\\n        <TreeNode key={node.id} node={node} />\\n      ))}\\n    </ul>\\n  );\\n}"],[2575,"Керованою формою в React керують через стан компонента. Для кожного поля введення створюють окреме значення у стані, а обробник onChange оновлює відповідне поле. Це дає React змогу контролювати значення полів і полегшує валідацію й надсилання даних.","Що таке керована форма?\\nУ React керована форма — форма, чиї значення полів зберігають у стані компонента й оновлюють через обробники подій. React стає єдиним джерелом істини для даних форми, що полегшує керування, валідацію й надсилання.\\n\\nРеалізація з кількома полями\\nДля кількох полів зручно використати об'єкт у стані, у якому ключі відповідають іменам полів. Обробник onChange використовує атрибут name поля, щоб динамічно оновити стан.\\n\\nПереваги й застосування\\n\\n- Проста валідація: можна перевіряти дані на кожній зміні.\\n- Дані легко надіслати на сервер: стан уже містить усі значення.\\n- Зручно для динамічних форм, де кількість полів може змінюватися.\\n\\nВисновок: керовані форми з кількома полями введення застосовують у React, щоб створювати інтерактивні, керовані користувацькі інтерфейси, особливо коли потрібна валідація або складна логіка надсилання даних.","import React, { useState } from 'react';\\n\\nfunction MyForm() {\\n  const [formData, setFormData] = useState({\\n    username: '',\\n    email: '',\\n    password: ''\\n  });\\n\\n  const handleChange = (e) => {\\n    const { name, value } = e.target;\\n    setFormData(prev => ({ ...prev, [name]: value }));\\n  };\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    console.log(formData);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input name=\\"username\\" value={formData.username} onChange={handleChange} />\\n      <input name=\\"email\\" value={formData.email} onChange={handleChange} />\\n      <input name=\\"password\\" type=\\"password\\" value={formData.password} onChange={handleChange} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}"],[2576,"Винесення функції-обробника за межі компонента виправдане, коли вона не залежить від пропсів або стану компонента й не використовує замикань над його внутрішніми змінними. Це дає змогу уникнути створення нової функції на кожному рендері, що покращує продуктивність. Наприклад, можна винести статичні обробники подій, як-от обробники кліків, яким не потрібний доступ до стану. Однак якщо функція залежить від стану або пропсів, краще використати useCallback.","Чому виносити функцію-обробник за межі компонента?\\nУ React на кожному рендері компонента всі функції, оголошені всередині нього, створюють наново. Це може призвести до зайвих повторних рендерів дочірніх компонентів, якщо вони отримують ці функції як пропси. Винесення функції поза компонент дає змогу зберегти посилання на ту саму функцію між рендерами, що оптимізує продуктивність.\\n\\nКоли це виправдано?\\n\\n- Функція не використовує стану або пропсів компонента (вона чиста й статична).\\n- Функція не залежить від замикань над внутрішніми змінними компонента.\\n- Компонент часто перерендерюється, а дочірні компоненти використовують React.memo або PureComponent.\\n\\nПриклад коду\\n\\nКоли її не варто виносити?\\nЯкщо функція залежить від стану або пропсів, винесення призведе до втрати доступу до актуальних значень. У таких випадках використовуйте useCallback із правильними залежностями.\\n\\nВисновок\\nВинесення функцій-обробників за межі компонента — простий, ефективний спосіб оптимізації, який варто застосовувати для статичних обробників, які не залежать від внутрішнього стану компонента.","// The unoptimized version: the function is created every time\\nfunction MyComponent() {\\n  const handleClick = () => {\\n    console.log('Clicked');\\n  };\\n  return <button onClick={handleClick}>Click</button>;\\n}\\n\\n// The optimized version: the function has been moved outside\\nconst handleClick = () => {\\n  console.log('Clicked');\\n};\\n\\nfunction MyComponent() {\\n  return <button onClick={handleClick}>Click</button>;\\n}"],[2577,"Подія onChange спрацьовує щоразу, коли користувач змінює значення поля введення — наприклад, набирає або видаляє символ. У React її використовують, щоб оновлювати стан компонента на кожній зміні, що дає змогу створювати керовані компоненти. Обробник отримує об'єкт події, з якого поточне значення можна отримати через event.target.value.","Як працює подія onChange у полях форми\\nПодія \`onChange\` у HTML й JavaScript спрацьовує, коли користувач змінює вміст елемента форми, як-от \`<input>\`, \`<select>\` або \`<textarea>\`. На відміну від події \`oninput\`, яка спрацьовує на кожній зміні, \`onchange\` зазвичай спрацьовує після втрати фокуса, але в React вона поводиться як \`oninput\` і викликається на кожній зміні значення.\\n\\nВикористання в React\\nУ React подію \`onChange\` використовують, щоб створювати керовані компоненти, де стан форми зберігають у компоненті й оновлюють через обробник. Це дає React змогу контролювати значення поля й реагувати на кожну зміну.\\n\\nУ цьому прикладі на кожному набраному символі викликають \`handleChange\`, який оновлює стан \`name\`. Поле введення відображає поточне значення зі стану, що робить його керованим.\\n\\nДе її застосовують\\nПодію \`onChange\` широко використовують у формах задля валідації в реальному часі, автодоповнення, пошуку з підказками й інших інтерактивних елементів. Вона дає змогу реагувати на кожну зміну введення, забезпечуючи динамічне оновлення інтерфейсу.\\n\\nВисновок\\nВикористовуйте \`onChange\` у React, щоб створювати керовані компоненти, коли стан полів форми потрібно відстежувати й керувати ним у реальному часі. Це особливо корисно задля валідації, фільтрації й інших сценаріїв, які потребують негайної реакції на введення користувача.","import React, { useState } from 'react';\\n\\nfunction MyForm() {\\n  const [name, setName] = useState('');\\n\\n  const handleChange = (event) => {\\n    setName(event.target.value);\\n  };\\n\\n  return (\\n    <input type=\\"text\\" value={name} onChange={handleChange} />\\n  );\\n}"],[2578,"Замість кількох викликів useState для кожного поля форми можна використати єдиний об'єкт стану. Для цього створюють один хук useState з об'єктом, який містить усі поля. Оновлення відбувається через функцію setState, використовуючи оператор розгортання або функційне оновлення, щоб решта полів залишилася незмінною. Це робить код простішим, а керування формою — централізованішим.","Об'єднання полів форми в один об'єкт стану\\nУ React, щоб керувати формою, часто використовують кілька хуків useState для кожного поля. Однак це призводить до дублювання коду й ускладнює підтримку. Ефективніший підхід — зберігати всі поля в одному об'єкті стану. Це дає змогу централізовано керувати формою й полегшує скидання, валідацію й надсилання даних.\\n\\nЯк це працює\\nЗамість створювати окремі частини стану для кожного поля, ви створюєте один об'єкт, у якому ключі — імена полів, а значення — їхні поточні значення. Задля оновлення використовують функцію setState, яка приймає новий об'єкт або функцію, що повертає новий об'єкт на основі попереднього стану. Важливо використовувати оператор розгортання (...prevState) або Object.assign, щоб не втратити інших полів.\\n\\nПриклад коду\\n\\nПереваги й застосування\\n\\n- Він робить код простішим: менше хуків, легше читати й підтримувати.\\n- Він зручний задля скидання форми: достатньо викликати setFormData із початковим об'єктом.\\n- Дані легко передати в API або для валідації.\\n- Він придатний для форм будь-якого розміру, особливо тих, які мають велику кількість полів.\\n\\nВисновок: використовуйте єдиний об'єкт стану для форми, коли потрібні централізоване керування, простіший код і зручність роботи з даними. Цей підхід особливо корисний у складних формах із безліччю полів.","import React, { useState } from 'react';\\n\\nfunction MyForm() {\\n  const [formData, setFormData] = useState({\\n    username: '',\\n    email: '',\\n    password: ''\\n  });\\n\\n  const handleChange = (e) => {\\n    const { name, value } = e.target;\\n    setFormData(prevState => ({\\n      ...prevState,\\n      [name]: value\\n    }));\\n  };\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    console.log(formData);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input name=\\"username\\" value={formData.username} onChange={handleChange} />\\n      <input name=\\"email\\" value={formData.email} onChange={handleChange} />\\n      <input name=\\"password\\" type=\\"password\\" value={formData.password} onChange={handleChange} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}"],[2579,"Віртуальні списки з елементами змінної висоти потребують динамічного вимірювання висоти кожного елемента. Зазвичай використовують підхід із попереднім обчисленням позицій на основі відомих розмірів або бібліотеки, які вимірюють висоту після рендерингу. Це дає змогу належно обчислити видиму область й позиціювати елементи, уникаючи повного малювання всього списку.","Базова концепція\\nВіртуальні списки (або віртуалізація списків) — техніка, за якої відображають лише невелику частину елементів — ту, яку видно у viewport, — а решту елементів заміняють порожніми заповнювачами. Коли елементи мають змінну висоту, стандартні підходи з фіксованою висотою не працюють, оскільки неможливо заздалегідь визначити точну позицію кожного елемента.\\n\\nМетоди обробки змінної висоти\\n\\n- Попереднє вимірювання: усі елементи рендерять один раз (можливо, за межами екрана), їхню висоту вимірюють і зберігають у масиві. Потім список використовує ці дані, щоб обчислювати позиції.\\n- Динамічне вимірювання: висоту вимірюють у момент, коли елемент уперше з'являється у видимій області. Після вимірювання позиції наступних елементів корегують.\\n- Оцінка на основі середнього: середню висоту елемента використовують задля приблизного обчислення, що може призвести до помилок у прокручуванні, але простіше реалізувати.\\n\\nПриклад реалізації на JavaScript\\n\\nЗастосування на практиці\\nБібліотеки на кшталт react-window або react-virtualized надають компоненти для роботи зі змінною висотою. Наприклад, у react-window використовують компонент VariableSizeList, який приймає функцію, щоб отримувати висоту кожного елемента.\\n\\nВисновок\\nВіртуальні списки зі змінною висотою потрібні, щоб ефективно працювати з динамічними даними, де розмір елементів заздалегідь невідомий. Їх широко застосовують у чатах, новинних стрічках і таблицях зі змінним вмістом, забезпечуючи плавне прокручування й низьке споживання пам'яті.","class VirtualList {\\n  constructor(container, items, estimatedHeight = 50) {\\n    this.container = container;\\n    this.items = items;\\n    this.estimatedHeight = estimatedHeight;\\n    this.heights = new Array(items.length).fill(estimatedHeight);\\n    this.positions = [];\\n    this.calculatePositions();\\n  }\\n\\n  calculatePositions() {\\n    let offset = 0;\\n    this.positions = this.heights.map((h) => {\\n      const pos = offset;\\n      offset += h;\\n      return pos;\\n    });\\n  }\\n\\n  updateHeight(index, actualHeight) {\\n    this.heights[index] = actualHeight;\\n    this.calculatePositions();\\n    this.render();\\n  }\\n\\n  render() {\\n    const scrollTop = this.container.scrollTop;\\n    const containerHeight = this.container.clientHeight;\\n    const startIndex = this.findIndex(scrollTop);\\n    const endIndex = this.findIndex(scrollTop + containerHeight);\\n    // the drawing of the elements from startIndex to endIndex\\n  }\\n\\n  findIndex(offset) {\\n    // a binary search over this.positions\\n  }\\n}"],[2580,"Так, у React у рефах можна зберігати довільні дані, не пов'язані з DOM. useRef створює об'єкт із властивістю current, яка зберігається між рендерами. Зміна current не спричиняє повторного рендера компонента. Це зручно, щоб зберігати таймери, попередні значення, посилання на екземпляри класів або будь-які інші змінювані дані, які не мають впливати на відображення.","Що таке useRef і як він працює\\nuseRef — хук React, який повертає змінюваний об'єкт з єдиною властивістю current. На відміну від useState, зміна значення current не спричиняє повторного рендера компонента. Це робить useRef ідеальним, щоб зберігати дані, які потрібно зберегти між рендерами, але які не впливають на UI.\\n\\nЗберігання довільних даних\\nКрім посилань на DOM-елементи, useRef може зберігати будь-які дані: числа, рядки, об'єкти, функції, екземпляри класів. Наприклад, можна зберігати ідентифікатор таймера, попереднє значення пропа або посилання на зовнішній сервіс.\\n\\nКоли це корисно\\n\\n- Зберігання таймерів й інтервалів задля їхнього подальшого очищення\\n- Збереження попередніх значень пропсів або стану задля порівняння\\n- Зберігання посилань на зовнішні бібліотеки або екземпляри класів\\n- Кешування результатів обчислень без зайвих рендерів\\n\\nВисновок\\nuseRef — потужний інструмент, щоб зберігати змінювані дані, які не мають впливати на рендер. Використовуйте його для таймерів, попередніх значень й будь-яких даних, які потрібно зберегти між рендерами, не спричиняючи оновлення компонента.","import { useRef, useEffect } from 'react';\\n\\nfunction Timer() {\\n  const timerRef = useRef(null);\\n  const countRef = useRef(0);\\n\\n  useEffect(() => {\\n    timerRef.current = setInterval(() => {\\n      countRef.current += 1;\\n      console.log('Count:', countRef.current);\\n    }, 1000);\\n\\n    return () => clearInterval(timerRef.current);\\n  }, []);\\n\\n  return <div>Check console</div>;\\n}"],[2581,"Щоб надіслати GET-запит через HttpClient, потрібно імпортувати HttpClientModule в AppModule й потім інжектувати HttpClient у сервіс або компонент. Викличте метод http.get(url), який повертає Observable. Підпишіться на нього за допомогою subscribe(), щоб отримати дані, або використайте пайп async у шаблоні.","Основи роботи з HttpClient в Angular\\nHttpClient — вбудований сервіс Angular, щоб виконувати HTTP-запити. Він побудований на основі Observable з RxJS, що дає змогу зручно працювати з асинхронними даними й застосовувати оператори для їхнього перетворення.\\n\\nКонфігурація й імпорт\\nСпочатку потрібно імпортувати HttpClientModule в кореневому модулі застосунку (зазвичай AppModule). Це роблять у секції imports.\\n\\nНадсилання GET-запиту\\nКоли його налаштували, можна інжектувати HttpClient у будь-який сервіс або компонент через конструктор. Щоб надіслати GET-запит, використовують метод get(), який приймає URL і необов'язкові параметри.\\n\\nОбробка відповіді\\nМетод get() повертає Observable. Щоб отримати дані, потрібно на нього підписатися. У компоненті це можна зробити так:\\n\\nМожна також використати пайп async у шаблоні задля автоматичної підписки й відписки.\\n\\nВисновок\\nHttpClient полегшує роботу з HTTP в Angular, надаючи типізовані відповіді й інтеграцію з RxJS. Його варто застосовувати для кожного мережевого запиту в Angular-застосунках, оскільки він забезпечує зручну обробку помилок, перехоплювачі й тестування.","import { HttpClientModule } from '@angular/common/http';\\n\\n@NgModule({\\n  imports: [\\n    HttpClientModule\\n  ]\\n})\\nexport class AppModule { }\\n\\nimport { HttpClient } from '@angular/common/http';\\nimport { Injectable } from '@angular/core';\\n\\n@Injectable({ providedIn: 'root' })\\nexport class DataService {\\n  constructor(private http: HttpClient) {}\\n\\n  getUsers() {\\n    return this.http.get('https://api.example.com/users');\\n  }\\n}\\n\\nthis.dataService.getUsers().subscribe({\\n  next: (data) => console.log(data),\\n  error: (err) => console.error(err)\\n});"],[2582,"BehaviorSubject — різновид Subject у RxJS, який зберігає останнє значення й передає його новим підписникам. На відміну від звичайного Subject, BehaviorSubject потребує початкового значення, коли його створюють. На підписці BehaviorSubject одразу видає поточне значення, а Subject видає лише нові події. Це робить BehaviorSubject зручним, щоб зберігати стан — наприклад, поточного користувача або тему дизайну.","Що таке BehaviorSubject?\\nBehaviorSubject — особливий тип Subject із бібліотеки RxJS, який є observable, здатним зберігати поточне значення. Коли BehaviorSubject створюють, обов'язково треба передати початкове значення. Коли новий підписник підписується на BehaviorSubject, він негайно отримує останнє (або початкове) значення й потім продовжує отримувати всі наступні оновлення.\\n\\nВідмінності від звичайного Subject\\nЗвичайний Subject не зберігає значення. Він просто передає події всім поточним підписникам. Якщо підписник підпишеться після того, як подія вже відбулася, він її не отримає. BehaviorSubject, навпаки, завжди зберігає останнє значення й видає його новим підписникам.\\n\\nПриклад коду\\n\\nДе його застосовують\\nBehaviorSubject часто використовують, щоб зберігати глобальний стан у застосунках — наприклад, поточного користувача, налаштування або тему. Він зручний, коли новий компонент має одразу отримати поточний стан, без додаткових запитів.\\n\\nВисновок: BehaviorSubject варто застосовувати, коли потрібно зберігати поточний стан і передавати його новим підписникам, на відміну від Subject, який придатний лише задля трансляції подій без збереження жодної історії.","import { Subject, BehaviorSubject } from 'rxjs';\\n\\nconst subject = new Subject();\\nconst behaviorSubject = new BehaviorSubject('initial');\\n\\nsubject.subscribe(value => console.log('Subject:', value));\\nbehaviorSubject.subscribe(value => console.log('BehaviorSubject:', value));\\n\\nsubject.next('A');\\nbehaviorSubject.next('A');\\n\\n// A new subscriber after the events\\nsubject.subscribe(value => console.log('Subject late:', value));\\nbehaviorSubject.subscribe(value => console.log('BehaviorSubject late:', value));\\n\\n// The output:\\n// Subject: A\\n// BehaviorSubject: initial\\n// BehaviorSubject: A\\n// BehaviorSubject late: A\\n// Subject late: (nothing)"],[2583,"Щоб отримати значення з події введення, використовуйте event.target.value. Коли користувач набирає текст у полі, браузер створює об'єкт події. Властивість target указує на елемент, який спричинив подію, а value містить поточне текстове значення цього елемента. Це стандартний спосіб звертатися до даних форми в React й у нативному JavaScript.","Як працює event.target.value\\nКоли користувач взаємодіє з елементом форми (наприклад, набирає текст в \`<input>\`), браузер генерує подію. Об'єкт події містить інформацію про дію, яка сталася. Властивість \`target\` посилається на DOM-елемент, який ініціював подію. Цей елемент має властивість \`value\`, яка зберігає поточний вміст поля введення.\\n\\nПриклад використання в нативному JavaScript\\n\\nУ цьому прикладі на кожному набраному символі в полі з id 'myInput' викликають функцію, яка отримує значення поля через \`event.target.value\` й виводить його в консоль.\\n\\nВикористання в React\\nУ React обробка подій схожа, але використовують синтаксис JSX. Значення зазвичай зберігають у стані компонента:\\n\\nТут \`event.target.value\` отримує нове значення поля, яке потім оновлює стан компонента через \`setText\`. Це дає React змогу контролювати значення поля й реагувати на зміни.\\n\\nДе це застосовують\\n\\n- Форми зворотного зв'язку, реєстрації й входу\\n- Поля пошуку з автодоповненням\\n- Текстові редактори й поля введення даних\\n\\nВисновок: \`event.target.value\` — основний спосіб отримати дані з полів введення у веброзробці. Його використовують і в нативному JavaScript, і в сучасних фреймворках (React, Vue, Angular), щоб обробляти введення користувача й керувати станом форми.","document.getElementById('myInput').addEventListener('input', function(event) {\\n  const inputValue = event.target.value;\\n  console.log('The current value:', inputValue);\\n});\\n\\nfunction MyComponent() {\\n  const [text, setText] = useState('');\\n\\n  const handleChange = (event) => {\\n    setText(event.target.value);\\n  };\\n\\n  return <input type=\\"text\\" value={text} onChange={handleChange} />;\\n}"],[2584,"useEffect гарантує, що запит виконують після рендера, а не під час нього, що запобігає блокуванню UI й забезпечує синхронізацію з актуальним станом. Обробник onChange викликають синхронно на кожній зміні, що може призвести до безлічі непотрібних запитів і до проблем із продуктивністю. useEffect також дає змогу легко керувати скасуванням запитів і залежностями.","Чому useEffect, а не onChange?\\nУ React обробники подій на кшталт onChange виконуються синхронно під час рендера. Якщо помістити в них fetch, новий запит запускатимуть щоразу, коли поле введення змінюється, що може призвести до лавини запитів і до гіршої продуктивності. До того ж стан компонента може змінитися перед тим, як запит завершиться, що призведе до гонки в даних.\\n\\nРоль useEffect\\nХук useEffect призначений, щоб виконувати побічні ефекти після того, як компонент відрендерився. Це гарантує, що запити даних не блокують рендера й виконуються лише тоді, коли вказані залежності змінюються. useEffect також надає механізм очищення, який дає змогу скасувати попередні запити, якщо залежність змінилася перед тим, як вони завершилися.\\n\\nПриклад коду\\n\\nВисновок\\nВикористання useEffect задля запитів при зміні стану забезпечує передбачувану поведінку, запобігає гонкам у даних й дає змогу ефективно керувати скасуванням запитів. Це особливо корисно у сценаріях пошуку з автодоповненням або фільтрації, де важливі продуктивність й актуальність даних.","import { useState, useEffect } from 'react';\\n\\nfunction SearchComponent() {\\n  const [query, setQuery] = useState('');\\n  const [results, setResults] = useState([]);\\n\\n  useEffect(() => {\\n    if (!query) return;\\n    const controller = new AbortController();\\n    const fetchData = async () => {\\n      try {\\n        const res = await fetch(\`/api/search?q=\${query}\`, {\\n          signal: controller.signal\\n        });\\n        const data = await res.json();\\n        setResults(data);\\n      } catch (err) {\\n        if (err.name !== 'AbortError') console.error(err);\\n      }\\n    };\\n    fetchData();\\n    return () => controller.abort(); // the cancellation of the previous request\\n  }, [query]);\\n\\n  return (\\n    <input value={query} onChange={(e) => setQuery(e.target.value)} />\\n  );\\n}"],[2585,"Effector — реактивний менеджер стану, заснований на подіях і потоках, на відміну від Redux, який використовує дії й редюсери. В Effector немає єдиного стора; замість нього використовують незалежні стори, які оновлюють через події. Основні відмінності: вбудована підтримка асинхронності через ефекти, відсутність шаблонного коду й простіша робота із залежностями.","Базова концепція Effector\\nEffector — сучасний менеджер стану для JavaScript-застосунків, який використовує реактивний підхід. На відміну від Redux, де станом керують через дії й редюсери, Effector спирається на події й стори. Події — функції, які можуть змінювати стан сторів, а стори — реактивні контейнери даних, які автоматично повідомляють підписників про зміни.\\n\\nКлючові відмінності від Redux\\n\\n- Архітектура: у Redux є єдиний глобальний стор, а в Effector можна створювати безліч незалежних сторів, що полегшує модульність.\\n- Асинхронність: Effector надає вбудовані ефекти для роботи з асинхронними операціями, як-от запитами до API, без потреби використовувати middleware (наприклад, Redux Thunk).\\n- Шаблонний код: у Redux потрібно багато шаблонного коду (типи дій, творці дій, редюсери); в Effector код лаконічніший.\\n- Реактивність: Effector використовує реактивні зв'язки між сторами й подіями, що дає йому змогу автоматично оновлювати дані, коли залежності змінюються.\\n\\nПриклад коду\\n\\nДе його застосовують\\nEffector добре підходить для складних застосунків із великою кількістю взаємопов'язаних частин стану, де важливі продуктивність і передбачуваність. Його часто використовують у React-проєктах, де потрібне гнучке керування станом без надмірного шаблонного коду.\\n\\nВисновок: Effector варто застосовувати, коли потрібне швидке, реактивне керування станом із мінімумом шаблонного коду, особливо в проєктах із частими асинхронними операціями й складними залежностями між частинами даних.","import { createStore, createEvent, createEffect } from 'effector';\\n\\n// We create an event\\nconst increment = createEvent();\\n\\n// We create a store with an initial value\\nconst counter = createStore(0)\\n  .on(increment, (state) => state + 1);\\n\\n// We create an effect for an asynchronous request\\nconst fetchUser = createEffect(async (id) => {\\n  const response = await fetch(\`/api/users/\${id}\`);\\n  return response.json();\\n});\\n\\n// We subscribe to the store's changes\\ncounter.watch((value) => console.log('Counter:', value));\\n\\n// We call the event\\nincrement(); // Counter: 1"],[2586,"Yup — бібліотека задля валідації даних на основі схем. Вона дає змогу описувати правила перевірки об'єктів, рядків, чисел й інших типів. Найчастіше її використовують із формами в React, щоб перевіряти введення користувача перед надсиланням.","Призначення Yup\\nYup — бібліотека, щоб створювати й виконувати схеми валідації даних у JavaScript. Вона надає декларативний API, щоб описувати правила перевірки значень, як-от рядків, чисел, масивів й об'єктів. Основна мета Yup — полегшити валідацію даних, особливо у формах, роблячи код читабельнішим і підтримуванішим.\\n\\nЯк це працює\\nВи визначаєте схему, яка описує очікувану структуру даних і правила для кожного поля. Потім ви викликаєте метод \`validate\` або \`isValid\`, щоб перевірити, чи об'єкт відповідає схемі. Якщо дані не проходять перевірки, Yup повертає зрозумілі повідомлення про помилки.\\n\\nПриклад використання\\n\\nДе її застосовують\\nYup часто використовують разом із бібліотеками керування формами, як-от Formik або React Hook Form. Це дає змогу централізовано описувати правила валідації й автоматично відображати помилки поруч із полями введення.\\n\\nВисновок\\nYup корисна, щоб створювати надійну, зрозумілу валідацію даних у вебзастосунках, особливо в роботі з формами. Вона допомагає уникати дублювання коду й полегшує обробку помилок.","import * as yup from 'yup';\\n\\nconst schema = yup.object().shape({\\n  name: yup.string().required('The name is required'),\\n  age: yup.number().positive().integer(),\\n  email: yup.string().email('An incorrect email'),\\n});\\n\\nschema.validate({ name: 'Anna', age: 25, email: 'anna@test.com' })\\n  .then(() => console.log('The validation has passed'))\\n  .catch(err => console.log(err.errors));"],[2587,"React Query автоматично кешує результати запитів, використовуючи унікальні ключі запитів. Дані вважають свіжими протягом установленого staleTime, після чого їх позначають як застарілі, і їх можна запросити знову, коли компонент знову монтується, або за таймером. Кеш зберігають у пам'яті, і його можна налаштувати за допомогою опції gcTime (раніше cacheTime), щоб керувати тим, як довго зберігають невикористані дані.","Основи кешування в React Query\\nReact Query (TanStack Query) надає потужний механізм задля кешування даних, отриманих із сервера. Кожний запит ідентифікують унікальним ключем запиту, який використовують, щоб зберігати дані в кеші й добувати їх. Кеш зберігають у пам'яті застосунку, і ним керують автоматично.\\n\\nКлючові концепції\\n\\n- staleTime — час у мілісекундах, протягом якого дані вважають свіжими. За замовчуванням 0, що означає: дані позначають як застарілі одразу.\\n- gcTime (раніше cacheTime) — час, протягом якого невикористані дані залишаються в кеші перед видаленням. За замовчуванням 5 хвилин.\\n- refetchOnMount — автоматичний повторний запит, коли компонент монтується, якщо дані застаріли.\\n- refetchOnWindowFocus — повторний запит, коли вікно браузера отримує фокус.\\n\\nПриклад налаштування кешування\\n\\nІнвалідація кешу\\nЩоб оновити дані після мутації, використовують інвалідацію кешу за допомогою queryClient.invalidateQueries. Це позначає дані як застарілі й ініціює повторний запит.\\n\\nВисновок\\nКешування в React Query дає змогу значно скоротити кількість запитів до сервера, покращити продуктивність і забезпечити актуальність даних. Рекомендують використовувати staleTime для даних, які рідко змінюються, й gcTime — щоб керувати пам'яттю.","import { useQuery } from '@tanstack/react-query';\\n\\nfunction useTodos() {\\n  return useQuery({\\n    queryKey: ['todos'],\\n    queryFn: fetchTodos,\\n    staleTime: 5 * 60 * 1000, // the data counts as fresh for 5 minutes\\n    gcTime: 10 * 60 * 1000,   // the data is held in the cache for 10 minutes after the component is removed\\n  });\\n}\\n\\nimport { useMutation, useQueryClient } from '@tanstack/react-query';\\n\\nfunction useAddTodo() {\\n  const queryClient = useQueryClient();\\n  return useMutation({\\n    mutationFn: addTodo,\\n    onSuccess: () => {\\n      queryClient.invalidateQueries({ queryKey: ['todos'] });\\n    },\\n  });\\n}"],[2588,"Якщо не вказати key при рендері списку в React, з'явиться попередження: «Warning: Each child in a list should have a unique 'key' prop.» Це попередження вказує, що React не може ефективно відстежувати зміни елементів списку. Без key React перемальовуватиме весь список на кожному оновленні, що знижує продуктивність.","Що таке key у React?\\nАтрибут \`key\` — спеціальний рядковий атрибут, який допомагає React ідентифікувати кожний елемент у списку. Коли ви рендерите масив даних за допомогою \`map()\`, React використовує \`key\`, щоб зіставити елементи до й після оновлення. Це ключова частина процесу узгодження, яка дає React змогу мінімізувати зміни в реальному DOM.\\n\\nЧому виникає попередження?\\nЯкщо \`key\` не вказано, React виводить попередження в консоль браузера: \`Warning: Each child in a list should have a unique 'key' prop.\` Це не помилка, а рекомендація. Без \`key\` React використовує індекс елемента в масиві як неявний ключ, що може призвести до неправильного оновлення стану компонентів, особливо коли елементи додають, видаляють або переставляють.\\n\\nПриклад коду з попередженням\\n\\nЯк належно використовувати key\\nВикористовуйте унікальний ідентифікатор із даних — наприклад, \`id\`:\\n\\nЯкщо унікального id немає, можна використати індекс, але це останній засіб, оскільки індекс нестабільний, коли список змінюється.\\n\\nВисновок\\nЗавжди вказуйте \`key\`, рендерячи списки в React, використовуючи стабільні унікальні ідентифікатори. Це покращує продуктивність і запобігає помилкам в оновленні стану, особливо в динамічних списках із додаванням або видаленням елементів.","function TodoList() {\\n  const items = ['Buy some milk', 'Call a friend', 'Do the homework'];\\n  return (\\n    <ul>\\n      {items.map((item) => (\\n        <li>{item}</li>  // the key is not stated — there will be a warning\\n      ))}\\n    </ul>\\n  );\\n}\\n\\nfunction TodoList() {\\n  const items = [\\n    { id: 1, text: 'Buy some milk' },\\n    { id: 2, text: 'Call a friend' },\\n  ];\\n  return (\\n    <ul>\\n      {items.map((item) => (\\n        <li key={item.id}>{item.text}</li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2589,"React Hook Form використовує некеровані компоненти й мінімізує кількість повторних рендерів, що робить його продуктивнішим. Final Form заснований на керованих компонентах й надає гнучкішу архітектуру з підписками на зміни. React Hook Form простіше інтегрувати з TypeScript, і він має менший розмір бандла.","Основні відмінності між React Hook Form і Final Form\\nReact Hook Form і Final Form — дві популярні бібліотеки задля керування формами в React, але вони мають принципово різні підходи до роботи. React Hook Form побудований на некерованих компонентах, що дає йому змогу уникати зайвих повторних рендерів і покращити продуктивність. Final Form, навпаки, використовує керовані компоненти й надає детальніший контроль над станом форми через підписки.\\n\\nАрхітектура й продуктивність\\nReact Hook Form мінімізує кількість повторних рендерів, оскільки він не зберігає стану форми в React-стані, а використовує refs задля доступу до значень полів. Це особливо корисно для великих форм із безліччю полів. Final Form використовує підписки на зміни, що дає йому змогу оновлювати лише ті компоненти, які підписані на певні поля, але він усе ж може бути менш продуктивним на дуже великих формах.\\n\\nПриклад коду\\n\\nІнтеграція й екосистема\\nReact Hook Form має вбудовану підтримку TypeScript й легко інтегрується з UI-бібліотеками, як-от Material-UI або Ant Design. Final Form також підтримує TypeScript, але потребує більше ручної конфігурації для роботи із зовнішніми компонентами. React Hook Form має менший розмір бандла (приблизно 8 КБ), що робить його кращим для проєктів, де важлива продуктивність завантаження.\\n\\nВисновок: React Hook Form краще підходить для проєктів, де важливі продуктивність і простота використання, особливо з TypeScript. Final Form варто обрати, якщо потрібна гнучкіша архітектура з детальним контролем над підписками й станом форми.","// React Hook Form\\nimport { useForm } from 'react-hook-form';\\n\\nfunction MyForm() {\\n  const { register, handleSubmit } = useForm();\\n  const onSubmit = (data) => console.log(data);\\n\\n  return (\\n    <form onSubmit={handleSubmit(onSubmit)}>\\n      <input {...register('name')} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}\\n\\n// Final Form\\nimport { Form, Field } from 'react-final-form';\\n\\nfunction MyForm() {\\n  const onSubmit = (values) => console.log(values);\\n\\n  return (\\n    <Form onSubmit={onSubmit}>\\n      {({ handleSubmit }) => (\\n        <form onSubmit={handleSubmit}>\\n          <Field name=\\"name\\">\\n            {({ input }) => <input {...input} />}\\n          </Field>\\n          <button type=\\"submit\\">Submit</button>\\n        </form>\\n      )}\\n    </Form>\\n  );\\n}"],[2590,"У React доступ до некерованого компонента отримують через refs. Створіть ref за допомогою useRef і прикріпіть його до елемента через атрибут ref. Потім звертайтеся до поточного значення через ref.current.value. Це дає змогу отримати дані безпосередньо з DOM, обходячи стан React.","Що таке некеровані компоненти?\\nНекеровані компоненти в React — елементи форми, які зберігають свій стан у DOM, а не в стані React. На відміну від керованих компонентів, де кожну зміну поля синхронізують зі станом через onChange, некеровані компоненти спираються на refs задля доступу до поточних значень.\\n\\nЯк отримати доступ?\\nЗадля доступу до некерованого компонента використовують хук \`useRef\`. Він створює об'єкт із властивістю \`current\`, яка посилається на DOM-елемент. Приклад:\\n\\nУ цьому прикладі \`inputRef\` прикріплений до поля введення. Коли форму надсилають, ми отримуємо значення через \`inputRef.current.value\`.\\n\\nКоли це використовувати?\\nНекеровані компоненти корисні для простих форм, де не потрібна миттєва валідація або складна логіка. Вони також зручні, коли інтегруються з бібліотеками, які керують DOM безпосередньо. Однак для складних форм із динамічними змінами краще використовувати керовані компоненти.\\n\\nВисновок: використовуйте некеровані компоненти й refs задля швидкого доступу до даних форми, коли не потрібний повний контроль над кожною зміною.","import React, { useRef } from 'react';\\n\\nfunction MyForm() {\\n  const inputRef = useRef(null);\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    alert('The value: ' + inputRef.current.value);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input ref={inputRef} type=\\"text\\" />\\n      <button type=\\"submit\\">Send</button>\\n    </form>\\n  );\\n}"],[2591,"Керовані компоненти зберігають свій стан у React, через useState, й оновлюють через onChange. Некеровані компоненти використовують ref задля безпосереднього доступу до DOM-елемента, а стан зберігають у самому DOM. Керовані дають більше контролю й передбачуваності; некеровані простіші для простих форм.","Основна різниця\\nКеровані й некеровані компоненти — два підходи до роботи з формами в React. У керованих компонентах стан поля введення зберігають у React-компоненті, через \`useState\`, і кожна зміна оновлює цей стан через обробник \`onChange\`. У некерованих компонентах стан зберігають у самому DOM, а задля доступу до значення використовують \`useRef\`.\\n\\nПриклад керованого компонента\\n\\nПриклад некерованого компонента\\n\\nКоли що використовувати\\n\\n- Керовані компоненти: коли потрібний миттєвий контроль над введенням (валідація, маски, динамічні зміни).\\n- Некеровані компоненти: для простих форм без складної логіки, де не потрібно відстежувати кожної зміни.\\n\\nВисновок: керовані компоненти кращі в більшості випадків, оскільки вони роблять стан передбачуваним і полегшують тестування. Некеровані компоненти можуть бути корисними задля інтеграції з не-React-кодом або для дуже простих полів.","import React, { useState } from 'react';\\n\\nfunction ControlledInput() {\\n  const [value, setValue] = useState('');\\n\\n  const handleChange = (e) => setValue(e.target.value);\\n\\n  return (\\n    <input\\n      type=\\"text\\"\\n      value={value}\\n      onChange={handleChange}\\n    />\\n  );\\n}\\n\\nimport React, { useRef } from 'react';\\n\\nfunction UncontrolledInput() {\\n  const inputRef = useRef(null);\\n\\n  const handleSubmit = () => {\\n    alert(inputRef.current.value);\\n  };\\n\\n  return (\\n    <div>\\n      <input type=\\"text\\" ref={inputRef} />\\n      <button onClick={handleSubmit}>Submit</button>\\n    </div>\\n  );\\n}"],[2592,"Метод shouldComponentUpdate у класових компонентах за змістом аналогічний React.memo. Він дає змогу запобігти повторному рендерингу компонента, якщо пропси не змінилися. React.memo робить те саме для функційних компонентів, обгортаючи їх й виконуючи поверхневе порівняння пропсів.","Зв'язок shouldComponentUpdate із React.memo\\nУ React класові компоненти мають метод життєвого циклу \`shouldComponentUpdate\`, який викликають перед рендерингом, коли компонент отримує нові пропси або стан. Цей метод повертає \`true\` (за замовчуванням) або \`false\`. Якщо він повертає \`false\`, рендеринг і наступні методи життєвого циклу пропускають. Це дає змогу оптимізувати продуктивність, уникаючи непотрібних оновлень.\\n\\n\`React.memo\` — функція вищого порядку для функційних компонентів. Вона обгортає компонент і виконує поверхневе порівняння попередніх і нових пропсів. Якщо пропси не змінилися, компонент не перерендерюється. По суті, \`React.memo\` автоматично реалізує логіку \`shouldComponentUpdate\` із поверхневим порівнянням.\\n\\nПриклади коду\\nКласовий компонент із shouldComponentUpdate:\\n\\nФункційний компонент із React.memo:\\n\\nЯкщо потрібне власне порівняння, \`React.memo\` приймає другий аргумент — функцію порівняння:\\n\\nВисновок\\nВикористовуйте \`shouldComponentUpdate\` у класових компонентах й \`React.memo\` у функційних, щоб запобігати надлишковим рендерам, коли пропси рідко змінюються. Це особливо корисно для компонентів, які рендерять важкі елементи або часто оновлюються.","class MyComponent extends React.Component {\\n  shouldComponentUpdate(nextProps) {\\n    // We compare only the props needed\\n    return nextProps.value !== this.props.value;\\n  }\\n\\n  render() {\\n    return <div>{this.props.value}</div>;\\n  }\\n}\\n\\nconst MyComponent = React.memo(({ value }) => {\\n  return <div>{value}</div>\\n});\\n// By default a shallow comparison of the props\\n\\nconst MyComponent = React.memo(\\n  ({ value }) => <div>{value}</div>,\\n  (prevProps, nextProps) => prevProps.value === nextProps.value\\n);"],[2593,"React використовує однонапрямлений потік даних. Дані передають від батьківських компонентів до дочірніх через пропси. Задля зворотного зв'язку дочірні компоненти викликають колбеки, передані через пропси. Стан піднімають вище ієрархією (lifting state up), щоб кілька компонентів могли його поділяти.","Однонапрямлений потік даних у React\\nReact використовує однонапрямлений потік даних. Це означає, що дані передають лише згори вниз — від батьківських компонентів до дочірніх. Такий підхід полегшує зневадження й робить поведінку застосунку передбачуваною.\\n\\nЯк це працює\\nБатьківський компонент передає дані дочірньому через атрибути, які називають пропсами. Дочірній компонент не може змінити ці дані безпосередньо. Якщо стан потрібно змінити, дочірній компонент викликає функцію зворотного виклику, передану через пропси, яка оновлює стан у батькові.\\n\\nЧому це важливо\\nОднонапрямлений потік даних запобігає хаотичним змінам стану, які важко відстежити. Кожний компонент отримує дані лише від свого батька й не може змінити їх безпосередньо. Це робить код передбачуванішим і полегшує рефакторинг.\\n\\nВисновок\\nОднонапрямлений потік даних у React — фундаментальний принцип, який забезпечує стабільність і передбачуваність застосунку. Його варто застосовувати в кожному React-проєкті, щоб полегшити керування станом і зневадження.","// The parent component\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  const increment = () => setCount(count + 1);\\n\\n  return <Child count={count} onIncrement={increment} />;\\n}\\n\\n// The child component\\nfunction Child({ count, onIncrement }) {\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={onIncrement}>+1</button>\\n    </div>\\n  );\\n}"],[2594,"Prop drilling виникає, коли дані передають через кілька рівнів компонентів, навіть якщо проміжні компоненти їх не використовують. Це робить код громіздким і важким для підтримки. Менеджери стану (наприклад, Redux, Zustand) або Context API дають змогу зберігати глобальний стан й надавати його безпосередньо тим компонентам, яким він потрібний, обходячи проміжні ланки.","Проблема prop drilling\\nУ React дані передають від батьківського компонента до дочірніх через пропси. У міру зростання застосунку виникає ситуація, у якій пропси доводиться передавати через кілька рівнів вкладеності, хоча проміжні компоненти їх не використовують. Це називають prop drilling. Такий підхід ускладнює рефакторинг, збільшує зв'язаність компонентів і робить код менш читабельним.\\n\\nЯк менеджери стану розв'язують цю проблему\\nМенеджери стану (наприклад, Redux, MobX, Zustand) або вбудований Context API надають механізм, щоб зберігати глобальний стан, доступний будь-якому компонентові без явного передавання через пропси. Компонент може підписатися на потрібну йому частину стану й автоматично отримувати оновлення.\\n\\nПриклад із Context API\\n\\nУ цьому прикладі Toolbar не отримує жодних пропсів, а ThemedButton використовує контекст безпосередньо. Це усуває prop drilling.\\n\\nВисновок\\nМенеджери стану й Context API розв'язують проблему prop drilling, роблячи архітектуру застосунку простішою, а код — підтримуванішим. Їх варто застосовувати, коли дані використовують багато компонентів на різних рівнях вкладеності, щоб уникнути зайвого передавання пропсів.","import React, { createContext, useContext, useState } from 'react';\\n\\nconst ThemeContext = createContext();\\n\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Toolbar />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction Toolbar() {\\n  return <ThemedButton />;\\n}\\n\\nfunction ThemedButton() {\\n  const { theme, setTheme } = useContext(ThemeContext);\\n  return (\\n    <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>\\n      Current theme: {theme}\\n    </button>\\n  );\\n}"],[2595,"HOC — функція, яка приймає компонент і повертає новий компонент із додатковими властивостями або логікою. У менеджерах стану — наприклад, у Redux — HOC \`connect\` використовують, щоб підписати компонент на стор і передати йому частину стану плюс дії. Це дає змогу відділити логіку керування станом від подання, роблячи код модульнішим і придатнішим для повторного використання.","Що таке HOC і як він працює в менеджерах стану\\nHigher-Order Component (HOC) — патерн у React, який є функцією, що приймає компонент і повертає новий компонент із розширеною функціональністю. У контексті менеджерів стану, як-от Redux, HOC використовують, щоб зв'язати компонент із глобальним станом застосунку.\\n\\nПриклад із connect у Redux\\nНайвідоміший приклад — функція \`connect\` із бібліотеки \`react-redux\`. Вона приймає дві функції, \`mapStateToProps\` і \`mapDispatchToProps\`, і повертає HOC, який обгортає ваш компонент. Усередині HOC підписується на стор Redux і передає потрібні дані й дії через пропси.\\n\\nЯк це працює всередині?\\nHOC, створений \`connect\`, усередині використовує \`React.Context\` або безпосередній доступ до стора (через \`useStore\` у сучасних версіях). Він відстежує зміни у сторі й, коли стан оновлюється, перемальовує обгорнутий компонент, передаючи йому нові пропси. Це дає компонентові змогу залишатися «дурним» (чисто презентаційним), не знаючи про існування Redux.\\n\\nЗастосування в інших менеджерах стану\\nАналогічний підхід використовують у MobX (через HOC \`observer\`) або в бібліотеках для роботи з Context (наприклад, \`withTheme\`). HOC дає змогу інкапсулювати логіку підписки на стан і робить компоненти придатнішими для повторного використання.\\n\\nВисновок: HOC у менеджерах стану — потужний інструмент, щоб розділити відповідальність між керуванням станом і відображенням UI. Він особливо корисний у великих застосунках, де потрібні централізований стан й чиста архітектура компонентів.","import { connect } from 'react-redux';\\n\\nconst mapStateToProps = (state) => ({\\n  count: state.counter.value\\n});\\n\\nconst mapDispatchToProps = (dispatch) => ({\\n  increment: () => dispatch({ type: 'INCREMENT' })\\n});\\n\\nconst Counter = ({ count, increment }) => (\\n  <div>\\n    <p>{count}</p>\\n    <button onClick={increment}>+</button>\\n  </div>\\n);\\n\\nexport default connect(mapStateToProps, mapDispatchToProps)(Counter);"],[2596,"У React дані передають від батька до дитини через пропси. Щоб передати дані назад, батько передає функцію зворотного виклику як проп. Дочірній компонент викликає цю функцію з потрібними даними, а батько отримує їх у своєму обробнику. Це називають підняттям стану (lifting state up).","Передавання даних із дочірнього компонента в батьківський у React\\nУ React дані зазвичай рухаються згори вниз — від батька до дочірніх компонентів через пропси. Однак часто виникає потреба передати інформацію назад — наприклад, коли користувач набирає текст у полі всередині дочірнього компонента, а батько має дізнатися це значення. Для цього використовують механізм колбеків.\\n\\nЯк це працює\\nБатьківський компонент визначає функцію-обробник і передає її дочірньому компонентові як проп. Дочірній компонент викликає цю функцію, передаючи в неї дані (наприклад, значення з поля введення). Батько отримує ці дані у своїй функції й може оновити свій стан або виконати інші дії.\\n\\nПриклад коду\\n\\nДе це застосовують\\n\\n- Форми: коли дані з кількох полів введення потрібно зібрати й передати вгору.\\n- Списки: на кліку по елементу списку батькові потрібно сказати, який елемент вибрано.\\n- Модальні вікна: коли модальне вікно закривається, потрібно передати результат (наприклад, підтвердження).\\n\\nВисновок\\nПередавання даних через колбеки — стандартний, простий спосіб організувати зворотний зв'язок від дочірнього компонента до батька. Цей підхід варто використовувати, коли стан потрібно підняти на рівень вище задля спільного використання даних кількома компонентами.","// The parent component\\nfunction Parent() {\\n  const [childData, setChildData] = useState('');\\n\\n  const handleDataFromChild = (data) => {\\n    setChildData(data);\\n  };\\n\\n  return (\\n    <div>\\n      <h1>The data from the child: {childData}</h1>\\n      <Child onSendData={handleDataFromChild} />\\n    </div>\\n  );\\n}\\n\\n// The child component\\nfunction Child({ onSendData }) {\\n  const [inputValue, setInputValue] = useState('');\\n\\n  const handleClick = () => {\\n    onSendData(inputValue); // We pass the data to the parent\\n  };\\n\\n  return (\\n    <div>\\n      <input\\n        type=\\"text\\"\\n        value={inputValue}\\n        onChange={(e) => setInputValue(e.target.value)}\\n      />\\n      <button onClick={handleClick}>Send to the parent</button>\\n    </div>\\n  );\\n}"],[2597,"HOC — функція, яка приймає компонент і повертає новий компонент із додатковою логікою. Вона розв'язує проблему дублювання коду, коли кілька компонентів використовують ту саму бізнес-логіку — наприклад, підписку на дані або обробку авторизації. HOC обгортає компонент, додаючи до нього пропси або поведінку, що дає змогу уникати повторення коду й покращує підтримуваність.","Що таке HOC й яку проблему він розв'язує\\nHigher-Order Component (HOC) — патерн у React, який дає змогу повторно використовувати логіку між компонентами. Якщо безліч компонентів містять ту саму бізнес-логіку — наприклад, завантаження даних з API, перевірку прав доступу або підписку на події, — то без HOC цю логіку довелося б дублювати в кожному компоненті. HOC розв'язує цю проблему, виступаючи обгорткою: він приймає компонент і повертає новий компонент із доданими властивостями або поведінкою.\\n\\nЯк це працює?\\nHOC — функція, яка приймає компонент і повертає новий компонент. Усередині HOC можна реалізувати спільну логіку й потім передати дані в обгорнутий компонент через пропси. Наприклад, якщо потрібно додати логіку авторизації до кількох сторінок, можна створити HOC \`withAuth\`, який перевіряє, чи користувач авторизований, і або рендерить компонент, або перенаправляє на сторінку входу.\\n\\nДе його застосовують?\\nHOC часто використовують, щоб:\\n- Додавати логіку підписки на дані (наприклад, із Redux або Context)\\n- Обробляти помилки або завантаження\\n- Керувати доступом (авторизацією)\\n- Логувати або збирати аналітику\\n\\nОднак із появою React Hooks (наприклад, \`useEffect\`, \`useContext\`) HOC стали менш популярними, оскільки хуки дають змогу повторно використовувати логіку без створення нових компонентів. Проте HOC залишаються корисними в застарілому коді або в роботі з бібліотеками, які їх потребують.\\n\\nВисновок\\nHOC — потужний інструмент задля повторного використання логіки в React, особливо коли ту саму поведінку потрібно додати до кількох компонентів без дублювання коду. Його варто застосовувати в проєктах, де хуки ще не використовують, або коли інтегруються з бібліотеками, які очікують HOC-обгорток.","function withAuth(WrappedComponent) {\\n  return function AuthenticatedComponent(props) {\\n    const isAuthenticated = checkAuth(); // the shared logic\\n    if (!isAuthenticated) {\\n      return <Redirect to=\\"/login\\" />;\\n    }\\n    return <WrappedComponent {...props} />;\\n  };\\n}\\n\\nconst ProtectedPage = withAuth(MyPage);"],[2598,"Користувач або код викликає dispatch(action). Redux передає дію й поточний стан у редюсер. Редюсер повертає новий стан. Стор зберігає його й повідомляє підписників. React перемальовує компоненти, підключені через connect або useSelector.","Життєвий цикл Redux\\nRedux — передбачуваний контейнер стану для JavaScript-застосунків. Увесь цикл починається з виклику функції dispatch з об'єктом дії, який містить type й необов'язкові дані. Потім Redux передає поточний стан і дію в кореневий редюсер, який вирішує, як змінити стан. Редюсер має бути чистою функцією: він не змінює початкового стану, а повертає новий об'єкт. Після цього стор оновлює свій внутрішній стан і викликає всіх підписників, зареєстрованих через subscribe. У React-застосунку підписку здійснюють через react-redux: connect або хуки useSelector/useDispatch. Коли стор повідомляє про зміну, React запускає повторний рендер компонентів, які залежать від тієї частини стану, яка змінилася.\\n\\nПриклад коду\\n\\nВисновок\\nРозуміння цього циклу потрібне задля зневадження, оптимізації продуктивності й належного проєктування архітектури Redux-застосунків. Використовуйте цей підхід, коли потрібне централізоване керування станом із передбачуваними змінами.","// an action creator\\nconst increment = () => ({ type: 'INCREMENT' });\\n\\n// a reducer\\nconst counter = (state = 0, action) => {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    default:\\n      return state;\\n  }\\n};\\n\\n// the store\\nconst store = createStore(counter);\\n\\n// the dispatch\\nstore.dispatch(increment());\\nconsole.log(store.getState()); // 1"],[2599,"У React, щоб завантажувати дані із сервера, використовують хук useEffect із порожнім масивом залежностей. Це аналог методу componentDidMount у класових компонентах. Хук виконується після першого рендера компонента, що гарантує наявність DOM-елементів. Такий підхід запобігає зайвим запитам на кожному оновленні стану.","Завантаження даних у React\\nУ React хук \`useEffect\` використовують, щоб виконувати побічні ефекти, як-от завантаження даних із сервера. Цей хук викликають після того, як компонент відрендерився й був доданий до DOM. Це гарантує, що ми маємо доступ до DOM-елементів й що запит не блокує початкового рендера.\\n\\nНалежне використання useEffect\\nЩоб завантажити дані лише один раз, коли компонент монтується, потрібно передати порожній масив залежностей як другий аргумент \`useEffect\`. Це еквівалентно методові \`componentDidMount\` у класових компонентах.\\n\\nВажливі аспекти\\n\\n- Не використовуйте асинхронної функції безпосередньо в \`useEffect\`; краще оголосити її всередині й викликати\\n- Завжди обробляйте помилки й стани завантаження\\n- Щоб скасовувати запити, коли компонент демонтується, використовуйте функцію очищення в \`useEffect\`\\n\\nВисновок: використання \`useEffect\` із порожнім масивом залежностей — стандартний, рекомендований спосіб завантажувати дані, коли компонент монтується в React. Це забезпечує передбачувану поведінку й запобігає втратам пам'яті.","import React, { useState, useEffect } from 'react';\\n\\nfunction UserList() {\\n  const [users, setUsers] = useState([]);\\n  const [loading, setLoading] = useState(true);\\n\\n  useEffect(() => {\\n    fetch('/api/users')\\n      .then(response => response.json())\\n      .then(data => {\\n        setUsers(data);\\n        setLoading(false);\\n      })\\n      .catch(error => console.error('Error:', error));\\n  }, []); // An empty array of dependencies\\n\\n  if (loading) return <div>Loading...</div>;\\n\\n  return (\\n    <ul>\\n      {users.map(user => (\\n        <li key={user.id}>{user.name}</li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2600,"React Router v6 представив кілька значних змін. Компонент Switch замінено на Routes, а Route тепер використовує element замість component. Порядок маршрутів більше не важливий, оскільки v6 використовує алгоритм ранжування. Хук useHistory замінено на useNavigate. Також у v6 з'явилася підтримка вкладених маршрутів і відносних посилань.","Основні відмінності між React Router v5 і v6\\nReact Router v6 є значним оновленням, яке спрощує API і робить маршрутизацію інтуїтивнішою. Головна зміна — заміна компонента Switch на Routes, який автоматично обирає найбільш відповідний маршрут, а не перший збіглий.\\nЗміни в компонентах маршрутів\\nУ v5 використовувався компонент Switch для групування Route, і порядок маршрутів мав значення. У v6 Switch замінено на Routes, а Route тепер приймає проп element замість component або render. Це дозволяє передавати компоненти напряму:\\n\\nНавігація та хуки\\nУ v5 для програмної навігації використовувався хук useHistory. У v6 він замінений на useNavigate, який надає гнучкіший API:\\n\\nВкладені маршрути та відносні посилання\\nReact Router v6 значно покращив підтримку вкладених маршрутів. Тепер можна визначати дочірні маршрути прямо всередині батьківського компонента, використовуючи Outlet:\\n\\nВисновок\\nReact Router v6 пропонує чистіший і передбачуваніший API, спрощує роботу з вкладеними маршрутами та покращує продуктивність. При міграції з v5 на v6 варто звернути увагу на заміну Switch на Routes, оновлення навігаційних хуків і рефакторинг вкладених маршрутів з використанням Outlet.","// React Router v5\\n<Switch>\\n  <Route path=\\"/home\\" component={Home} />\\n  <Route path=\\"/about\\" component={About} />\\n</Switch>\\n\\n// React Router v6\\n<Routes>\\n  <Route path=\\"/home\\" element={<Home />} />\\n  <Route path=\\"/about\\" element={<About />} />\\n</Routes>\\n\\n// React Router v5\\nconst history = useHistory();\\nhistory.push('/home');\\n\\n// React Router v6\\nconst navigate = useNavigate();\\nnavigate('/home');\\nnavigate(-1); // для переходу назад\\n\\nfunction App() {\\n  return (\\n    <Routes>\\n      <Route path=\\"/dashboard\\" element={<Dashboard />}>\\n        <Route path=\\"stats\\" element={<Stats />} />\\n        <Route path=\\"settings\\" element={<Settings />} />\\n      </Route>\\n    </Routes>\\n  );\\n}\\n\\nfunction Dashboard() {\\n  return (\\n    <div>\\n      <h1>Dashboard</h1>\\n      <Outlet /> {/* Тут відображатимуться дочірні маршрути */}\\n    </div>\\n  );\\n}"]]`);export{e as default};